// Red team simulation implementations
async function executeRedTeamSimulation(simulationType: string) {
  switch (simulationType) {
    case 'WIN_SHAPING_DETECTION':
      return await simulateWinShapingDetection();
    case 'DRAMA_PATTERN_EXPLOIT':
      return await simulateDramaPatternExploit();
    case 'COST_SPIKE_DETECTION':
      return await simulateCostSpikeDetection();
    case 'ABUSE_SIMULATION':
      return await simulateAbuseAttempt();
    case 'DRIFT_ESCALATION':
      return await simulateDriftEscalation();
    case 'SCHEMA_FAILURE_LOOP':
      return await simulateSchemaFailureLoop();
    default:
      throw new Error(`Unknown simulation type: ${simulationType}`);
  }
}

async function simulateWinShapingDetection() {
  // Simulate detection of predictable win shaping patterns
  const vulnerabilities = [
    { type: 'predictable_outcome', severity: 'medium', description: 'Opponent consistently allows player wins in close matches' },
    { type: 'timing_pattern', severity: 'low', description: 'Reaction times follow predictable pattern' }
  ];

  return {
    parameters: { simulation_type: 'WIN_SHAPING_DETECTION', test_matches: 1000 },
    results: { vulnerabilities_detected: vulnerabilities, success_rate: 0.85 },
    vulnerabilities_found: vulnerabilities.length,
    policy_updates_required: 1
  };
}

async function simulateDramaPatternExploit() {
  // Simulate detection of drama pattern exploitation
  const vulnerabilities = [
    { type: 'drama_manipulation', severity: 'high', description: 'User can manipulate drama curve for favorable outcomes' }
  ];

  return {
    parameters: { simulation_type: 'DRAMA_PATTERN_EXPLOIT', test_scenarios: 50 },
    results: { vulnerabilities_detected: vulnerabilities, exploitation_success: 0.15 },
    vulnerabilities_found: vulnerabilities.length,
    policy_updates_required: 2
  };
}

async function simulateCostSpikeDetection() {
  // Simulate detection of cost spikes in opponent plan generation
  const costs = Array.from({ length: 100 }, () => Math.random() * 0.1);
  const avgCost = costs.reduce((a, b) => a + b, 0) / costs.length;
  const maxCost = Math.max(...costs);

  return {
    parameters: { simulation_type: 'COST_SPIKE_DETECTION', sample_size: 100 },
    results: { average_cost: avgCost, max_cost: maxCost, cost_variance: 0.02 },
    vulnerabilities_found: maxCost > 0.08 ? 1 : 0,
    policy_updates_required: maxCost > 0.08 ? 1 : 0
  };
}

async function simulateAbuseAttempt() {
  // Simulate various abuse attempts
  const attempts = [
    { type: 'mmr_manipulation', success: false, reason: 'governance_blocked' },
    { type: 'persona_injection', success: false, reason: 'schema_validation_failed' },
    { type: 'bias_override', success: false, reason: 'fairness_bounds_enforced' }
  ];

  return {
    parameters: { simulation_type: 'ABUSE_SIMULATION', attempts: attempts.length },
    results: { abuse_attempts: attempts, blocked_attempts: attempts.length },
    vulnerabilities_found: 0,
    policy_updates_required: 0
  };
}

async function simulateDriftEscalation() {
  // Simulate detection of drift escalation
  const driftMetrics = {
    plan_latency_drift: 0.15,
    accuracy_drift: 0.08,
    fairness_drift: 0.05
  };

  return {
    parameters: { simulation_type: 'DRIFT_ESCALATION', metrics: Object.keys(driftMetrics) },
    results: { drift_metrics: driftMetrics, escalation_detected: false },
    vulnerabilities_found: 0,
    policy_updates_required: 0
  };
}

async function simulateSchemaFailureLoop() {
  // Simulate schema failure loop detection
  const schemaTests = Array.from({ length: 50 }, (_, i) => ({
    test_id: i,
    success: i % 10 !== 0, // 90% success rate
    error: i % 10 === 0 ? 'schema_validation_failed' : null
  }));

  const failureRate = schemaTests.filter(t => !t.success).length / schemaTests.length;

  return {
    parameters: { simulation_type: 'SCHEMA_FAILURE_LOOP', test_count: schemaTests.length },
    results: { failure_rate: failureRate, consecutive_failures: 1 },
    vulnerabilities_found: failureRate > 0.1 ? 1 : 0,
    policy_updates_required: failureRate > 0.1 ? 1 : 0
  };
}

async function executeFairnessAudit() {
  try {
    // Get recent fairness data
    const { data: recentData } = await supabase
      .from('fairness_monitoring')
      .select('*')
      .order('monitoring_window', { ascending: false })
      .limit(24);

    // Calculate current metrics
    const auditResults = {
      audit_window: '24_hours',
      total_matches: recentData?.reduce((sum, d) => sum + d.total_matches, 0) || 0,
      average_win_rate: recentData?.reduce((sum, d) => sum + d.win_rate, 0) / (recentData?.length || 1) || 0,
      average_close_match_rate: recentData?.reduce((sum, d) => sum + d.close_match_rate, 0) / (recentData?.length || 1) || 0,
      violations_detected: recentData?.filter(d => d.win_rate_violation || d.close_match_violation).length || 0,
      corrective_actions: recentData?.filter(d => d.circuit_breaker_triggered || d.dynamic_drama_disabled).length || 0
    };

    return auditResults;

  } catch (error) {
    throw new Error(`Fairness audit failed: ${error}`);
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { createSupabaseServerClient } from "@/lib/supabase/server";

async function getServiceClient() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!supabaseUrl || !serviceKey) {
    throw new Error("supabase_service_config_missing");
  }

  return createClient(supabaseUrl, serviceKey, {
    auth: {
      persistSession: false,
    },
  });
}

export async function GET(
  request: Request,
  { params }: { params: { battleId: string } }
) {
  try {
    const supabase = await createSupabaseServerClient();
    if (!supabase) {
      return NextResponse.json({ error: "supabase_not_configured" }, { status: 500 });
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "unauthenticated" }, { status: 401 });
    }

    const adminClient = await getServiceClient();

    // Get battle with related data
    const { data: battle, error: battleError } = await adminClient
      .from("battles")
      .select(`
        *,
        beat:beats(*),
        participant_1:users!battles_participant_1_id_fkey(*),
        participant_2:users!battles_participant_2_id_fkey(*)
      `)
      .eq("id", params.battleId)
      .single();

    if (battleError || !battle) {
      return NextResponse.json({ error: "battle_not_found" }, { status: 404 });
    }

    // Check if user is part of this battle
    if (battle.participant_1_id !== user.id && battle.participant_2_id !== user.id) {
      return NextResponse.json({ error: "not_participant" }, { status: 403 });
    }

    return NextResponse.json({ battle });
  } catch (error: any) {
    return NextResponse.json({ error: "unknown_error", details: error.message ?? "" }, { status: 500 });
  }
}

export async function POST(
  request: Request,
  { params }: { params: { battleId: string } }
) {
  try {
    const supabase = await createSupabaseServerClient();
    if (!supabase) {
      return NextResponse.json({ error: "supabase_not_configured" }, { status: 500 });
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "unauthenticated" }, { status: 401 });
    }

    const body = await request.json().catch(() => ({}));
    const { winner, scores } = body;

    const adminClient = await getServiceClient();

    // Update battle with results
    const { data: updatedBattle, error: updateError } = await adminClient
      .from("battles")
      .update({
        status: "completed",
        winner: winner === "user" ? user.id : "bot",
        participant_1_score: scores.userScore,
        participant_2_score: scores.botScore,
        completed_at: new Date().toISOString(),
      })
      .eq("id", params.battleId)
      .select("*")
      .single();

    if (updateError) {
      return NextResponse.json({ error: "battle_update_failed", details: updateError.message }, { status: 500 });
    }

    // Update user stats
    const { error: statsError } = await adminClient
      .from("users")
      .update({
        battles_played: (updatedBattle.participant_1?.battles_played || 0) + 1,
        wins: winner === "user" ? (updatedBattle.participant_1?.wins || 0) + 1 : (updatedBattle.participant_1?.wins || 0),
        losses: winner === "bot" ? (updatedBattle.participant_1?.losses || 0) + 1 : (updatedBattle.participant_1?.losses || 0),
        skill_level: winner === "user" 
          ? Math.min(100, ((updatedBattle.participant_1?.skill_level || 50) + 5))
          : Math.max(0, ((updatedBattle.participant_1?.skill_level || 50) - 3)),
      })
      .eq("id", user.id);

    if (statsError) {
      console.error("Failed to update user stats:", statsError);
    }

    return NextResponse.json({ 
      ok: true, 
      battle: updatedBattle,
      message: `Battle completed! ${winner === "user" ? "You won!" : "Bot won!"}`
    });

  } catch (error: any) {
    return NextResponse.json({ error: "unknown_error", details: error.message ?? "" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from '@supabase/supabase-js';
import { BeatService } from '@/lib/services/BeatService';

// GET /api/beats?genre=hip-hop&tempo_min=80&tempo_max=140&limit=50
export async function GET(req: Request) {
  try {
    const url = new URL(req.url);
    const genre = url.searchParams.get("genre") ?? "all";
    const tempoMin = Number(url.searchParams.get("tempo_min") ?? 60);
    const tempoMax = Number(url.searchParams.get("tempo_max") ?? 200);
    const limitRaw = Number(url.searchParams.get("limit") ?? 50);
    const limit = Number.isFinite(limitRaw) ? Math.max(1, Math.min(100, Math.floor(limitRaw))) : 50;
    const sortBy = url.searchParams.get("sort_by") ?? "usage_count";
    const sortOrder = url.searchParams.get("sort_order") ?? "desc";
    const minRating = Number(url.searchParams.get("min_rating")) ?? null;

    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

    if (!supabaseUrl || !supabaseServiceKey) {
      return NextResponse.json({ error: "Supabase not configured" }, { status: 500 });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    let query = supabase
      .from("beats")
      .select(
        "id,title,artist,tempo,key_signature,genre,duration_seconds,preview_url,file_url,license_type,license_url,source,usage_count,created_at,status,is_active,is_verified,tags,rating"
      )
      .eq("is_active", true)
      .eq("status", "active");

    if (genre && genre !== "all") {
      query = query.eq("genre", genre);
    }

    if (Number.isFinite(tempoMin)) {
      query = query.gte("tempo", Math.max(0, tempoMin));
    }
    if (Number.isFinite(tempoMax)) {
      query = query.lte("tempo", Math.max(0, tempoMax));
    }

    if (minRating && Number.isFinite(minRating)) {
      query = query.gte("rating", minRating);
    }

    // Sorting
    query = query.order(sortBy, { ascending: sortOrder === "asc" });

    query = query.limit(limit);

    const { data, error } = await query;

    if (error) {
      return NextResponse.json({ error: "beats_fetch_failed", details: error.message }, { status: 400 });
    }

    // Return real beats with proper structure
    return NextResponse.json({ 
      ok: true, 
      mode: "supabase", 
      beats: data || [],
      total: data?.length || 0,
      filters: {
        genre,
        tempoMin,
        tempoMax,
        limit,
        sortBy,
        sortOrder,
        minRating
      }
    });

  } catch (error: any) {
    console.error('Error in beats API:', error);
    return NextResponse.json({ 
      error: "server_error", 
      details: error.message || "Unknown error occurred" 
    }, { status: 500 });
  }
}

// POST /api/beats - Upload new beat
export async function POST(req: Request) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ error: "unauthorized" }, { status: 401 });
    }

    const formData = await req.formData();
    const beatData = JSON.parse(formData.get('beatData') as string);
    const audioFile = formData.get('audioFile') as File;
    const previewFile = formData.get('previewFile') as File;

    if (!audioFile || !previewFile) {
      return NextResponse.json({ error: "audio and preview files required" }, { status: 400 });
    }

    // Validate file types
    if (!audioFile.type.startsWith('audio/') || !previewFile.type.startsWith('audio/')) {
      return NextResponse.json({ error: "invalid file types" }, { status: 400 });
    }

    // Validate file sizes (max 50MB for audio, 10MB for preview)
    if (audioFile.size > 50 * 1024 * 1024 || previewFile.size > 10 * 1024 * 1024) {
      return NextResponse.json({ error: "files too large" }, { status: 400 });
    }

    // TODO: Implement actual file upload to storage service
    // For now, return success response
    return NextResponse.json({
      ok: true,
      message: "Beat upload received - processing",
      beatData: {
        title: beatData.title,
        artist: beatData.artist,
        tempo: beatData.tempo,
        genre: beatData.genre
      }
    });

  } catch (error: any) {
    console.error('Error in beat upload:', error);
    return NextResponse.json({ 
      error: "upload_failed", 
      details: error.message || "Unknown error occurred" 
    }, { status: 500 });
  }
}

