"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import {
  Users, Swords, Trophy, Shield, Activity, Zap,
  Search, ChevronLeft, ChevronRight, RefreshCw,
} from "lucide-react";

// ─── Types ──────────────────────────────────────────────────────────────────

type Stats = {
  total_users: number;
  total_battles: number;
  live_battles: number;
  total_tournaments: number;
  open_mod_cases: number;
  activity_24h: number;
};

type UserRow = {
  id: string;
  handle: string;
  display_name: string | null;
  avatar_url: string | null;
  role: string;
  elo_rating: number;
  tier: string;
  token_balance: number;
  created_at: string;
};

const ROLE_OPTIONS = ["all", "user", "mod", "admin", "banned"] as const;
const ROLE_COLORS: Record<string, string> = {
  admin: "border-red-500/40 text-red-400",
  mod: "border-purple-500/40 text-purple-400",
  banned: "border-muted-foreground/40 text-muted-foreground line-through",
  user: "border-border/40 text-muted-foreground",
};

// ─── Stat Card ───────────────────────────────────────────────────────────────

function StatCard({
  label,
  value,
  icon,
  color,
  sub,
}: {
  label: string;
  value: number | string;
  icon: React.ReactNode;
  color: string;
  sub?: string;
}) {
  return (
    <Card className="border-border/60 bg-card/30 p-4">
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className={`text-2xl font-black tabular-nums ${color}`}>{value}</div>
          <div className="mt-0.5 text-xs font-medium text-muted-foreground">{label}</div>
          {sub && <div className="mt-0.5 text-[10px] text-muted-foreground/60">{sub}</div>}
        </div>
        <div className={`mt-0.5 ${color}`}>{icon}</div>
      </div>
    </Card>
  );
}

// ─── User Table Row ──────────────────────────────────────────────────────────

function UserTableRow({
  user,
  onUpdate,
}: {
  user: UserRow;
  onUpdate: (id: string, updates: { role?: string; token_balance?: number }) => Promise<void>;
}) {
  const [editing, setEditing] = React.useState(false);
  const [role, setRole] = React.useState(user.role);
  const [tokens, setTokens] = React.useState(String(user.token_balance));
  const [saving, setSaving] = React.useState(false);

  async function handleSave() {
    setSaving(true);
    await onUpdate(user.id, {
      role,
      token_balance: parseInt(tokens, 10),
    });
    setSaving(false);
    setEditing(false);
  }

  return (
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-border/60 bg-card/20 px-4 py-3 text-sm">
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-medium truncate">{user.display_name ?? user.handle}</span>
          <span className="font-mono text-xs text-muted-foreground">@{user.handle}</span>
          <Badge variant="outline" className={`text-[10px] ${ROLE_COLORS[user.role] ?? ROLE_COLORS.user}`}>
            {user.role}
          </Badge>
        </div>
        <div className="mt-1 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
          <span>ELO {user.elo_rating}</span>
          <span>{user.tier}</span>
          <span>💎 {user.token_balance} tokens</span>
          <span className="font-mono opacity-60">{user.id.slice(0, 8)}…</span>
        </div>
      </div>

      <div className="flex shrink-0 items-center gap-2">
        {editing ? (
          <>
            <Select value={role} onValueChange={setRole}>
              <SelectTrigger className="h-7 w-24 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {["user", "mod", "admin", "banned"].map(r => (
                  <SelectItem key={r} value={r}>{r}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Input
              className="h-7 w-24 text-xs"
              value={tokens}
              onChange={e => setTokens(e.target.value)}
              placeholder="Tokens"
            />
            <Button size="sm" className="h-7 text-xs" onClick={handleSave} disabled={saving}>
              {saving ? "…" : "Save"}
            </Button>
            <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => setEditing(false)}>
              Cancel
            </Button>
          </>
        ) : (
          <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setEditing(true)}>
            Edit
          </Button>
        )}
      </div>
    </div>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────

export function AdminDashboard() {
  const [stats, setStats] = React.useState<Stats | null>(null);
  const [users, setUsers] = React.useState<UserRow[]>([]);
  const [total, setTotal] = React.useState(0);
  const [pages, setPages] = React.useState(1);
  const [page, setPage] = React.useState(0);
  const [search, setSearch] = React.useState("");
  const [roleFilter, setRoleFilter] = React.useState("all");
  const [loading, setLoading] = React.useState(true);
  const [statsLoading, setStatsLoading] = React.useState(true);

  // Debounce search
  const [debouncedSearch, setDebouncedSearch] = React.useState("");
  React.useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search), 350);
    return () => clearTimeout(t);
  }, [search]);

  async function loadStats() {
    setStatsLoading(true);
    try {
      const res = await fetch("/api/admin/stats");
      if (res.ok) setStats(await res.json());
    } catch {
      toast.error("Failed to load stats");
    } finally {
      setStatsLoading(false);
    }
  }

  async function loadUsers() {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: String(page),
        ...(debouncedSearch ? { q: debouncedSearch } : {}),
        ...(roleFilter !== "all" ? { role: roleFilter } : {}),
      });
      const res = await fetch(`/api/admin/users?${params}`);
      const data = await res.json();
      setUsers(data.users ?? []);
      setTotal(data.total ?? 0);
      setPages(data.pages ?? 1);
    } catch {
      toast.error("Failed to load users");
    } finally {
      setLoading(false);
    }
  }

  React.useEffect(() => { loadStats(); }, []);
  React.useEffect(() => { loadUsers(); }, [page, debouncedSearch, roleFilter]);

  async function handleUserUpdate(id: string, updates: { role?: string; token_balance?: number }) {
    try {
      const res = await fetch(`/api/admin/users/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updates),
      });
      const json = await res.json();
      if (!res.ok) { toast.error(json.error ?? "Update failed"); return; }
      toast.success("User updated");
      setUsers(prev => prev.map(u => u.id === id ? { ...u, ...json.user } : u));
    } catch {
      toast.error("Network error");
    }
  }

  return (
    <div className="space-y-6">
      {/* Stats grid */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
        {statsLoading ? (
          Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="h-20 animate-pulse rounded-lg bg-muted/30" />
          ))
        ) : stats ? (
          <>
            <StatCard label="Total Users" value={stats.total_users} icon={<Users className="h-4 w-4" />} color="text-blue-400" />
            <StatCard label="Total Battles" value={stats.total_battles} icon={<Swords className="h-4 w-4" />} color="text-orange-400" />
            <StatCard label="Live Now" value={stats.live_battles} icon={<Zap className="h-4 w-4" />} color="text-green-400" sub="active battles" />
            <StatCard label="Tournaments" value={stats.total_tournaments} icon={<Trophy className="h-4 w-4" />} color="text-yellow-400" />
            <StatCard label="Open Cases" value={stats.open_mod_cases} icon={<Shield className="h-4 w-4" />} color={stats.open_mod_cases > 0 ? "text-red-400" : "text-muted-foreground"} />
            <StatCard label="Activity 24h" value={stats.activity_24h} icon={<Activity className="h-4 w-4" />} color="text-purple-400" />
          </>
        ) : null}
      </div>

      <Separator />

      {/* User management */}
      <div className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-base font-semibold">User Management</h2>
            <p className="text-xs text-muted-foreground">{total} total users</p>
          </div>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => { loadStats(); loadUsers(); }}
            className="gap-1.5"
          >
            <RefreshCw className="h-3.5 w-3.5" />
            Refresh
          </Button>
        </div>

        {/* Filters */}
        <div className="flex flex-wrap items-center gap-2">
          <div className="relative flex-1 min-w-[200px] max-w-xs">
            <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search handle or name…"
              value={search}
              onChange={e => { setSearch(e.target.value); setPage(0); }}
              className="h-8 pl-8 text-xs"
            />
          </div>
          <Select value={roleFilter} onValueChange={v => { setRoleFilter(v); setPage(0); }}>
            <SelectTrigger className="h-8 w-28 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {ROLE_OPTIONS.map(r => (
                <SelectItem key={r} value={r}>{r === "all" ? "All roles" : r}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* User list */}
        {loading ? (
          <div className="space-y-2">
            {Array.from({ length: 8 }).map((_, i) => (
              <div key={i} className="h-16 animate-pulse rounded-lg bg-muted/30" />
            ))}
          </div>
        ) : users.length === 0 ? (
          <Card className="border-border/60 bg-card/30 p-8 text-center">
            <Users className="mx-auto h-8 w-8 text-muted-foreground/30" />
            <p className="mt-2 text-sm text-muted-foreground">No users found.</p>
          </Card>
        ) : (
          <div className="space-y-1.5">
            {users.map(u => (
              <UserTableRow key={u.id} user={u} onUpdate={handleUserUpdate} />
            ))}
          </div>
        )}

        {/* Pagination */}
        {pages > 1 && (
          <div className="flex items-center justify-between text-sm">
            <span className="text-xs text-muted-foreground">
              Page {page + 1} of {pages} · {total} users
            </span>
            <div className="flex gap-2">
              <Button
                size="sm"
                variant="outline"
                disabled={page === 0}
                onClick={() => setPage(p => p - 1)}
                className="h-7 gap-1 text-xs"
              >
                <ChevronLeft className="h-3.5 w-3.5" />
                Prev
              </Button>
              <Button
                size="sm"
                variant="outline"
                disabled={page >= pages - 1}
                onClick={() => setPage(p => p + 1)}
                className="h-7 gap-1 text-xs"
              >
                Next
                <ChevronRight className="h-3.5 w-3.5" />
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface GovernanceStats {
  total_plans: number;
  tier_distribution: {
    TIER1: number;
    TIER2: number;
    FALLBACK: number;
    BLOCKED: number;
  };
  persona_distribution: {
    Aggro: number;
    Turtle: number;
    Counter: number;
    Gambler: number;
  };
  drama_distribution: {
    close_win: number;
    close_loss: number;
    comeback: number;
    control_win: number;
    stomp_rare: number;
  };
  average_latency: number;
  average_cost: number;
  circuit_breaker_status: {
    state: string;
    failures: number;
    lastFailureTime: number;
  };
}

interface TelemetryMetrics {
  ttfm_p50: number;
  ttfm_p90: number;
  ttfm_p95: number;
  ttfm_p99: number;
  rematch_rate: number;
  rage_quit_rate: number;
  disconnect_rate: number;
  governance_block_rate: number;
  circuit_breaker_open_rate: number;
  fairness_violation_rate: number;
  total_matches: number;
  total_queue_enters: number;
}

interface RedTeamResult {
  id: string;
  simulation_type: string;
  run_date: string;
  vulnerabilities_found: number;
  policy_updates_required: number;
  results: any;
}

export function GovernanceDashboard() {
  const [stats, setStats] = useState<GovernanceStats | null>(null);
  const [metrics, setMetrics] = useState<TelemetryMetrics | null>(null);
  const [redTeamResults, setRedTeamResults] = useState<RedTeamResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadDashboardData();
    const interval = setInterval(loadDashboardData, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);

      const token = localStorage.getItem('admin_token');
      if (!token) {
        setError('Admin authentication required');
        return;
      }

      const [statsResponse, metricsResponse, redTeamResponse] = await Promise.all([
        fetch('/api/admin/governance?endpoint=stats', {
          headers: { 'Authorization': `Bearer ${token}` }
        }),
        fetch('/api/admin/governance?endpoint=metrics', {
          headers: { 'Authorization': `Bearer ${token}` }
        }),
        fetch('/api/admin/governance?endpoint=red-team', {
          headers: { 'Authorization': `Bearer ${token}` }
        })
      ]);

      if (!statsResponse.ok || !metricsResponse.ok || !redTeamResponse.ok) {
        throw new Error('Failed to fetch dashboard data');
      }

      const [statsData, metricsData, redTeamData] = await Promise.all([
        statsResponse.json(),
        metricsResponse.json(),
        redTeamResponse.json()
      ]);

      setStats(statsData.data);
      setMetrics(metricsData.data);
      setRedTeamResults(redTeamData.data);

    } catch (error) {
      console.error('Dashboard load error:', error);
      setError(error instanceof Error ? error.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const runRedTeamSimulation = async (simulationType: string) => {
    try {
      const token = localStorage.getItem('admin_token');
      if (!token) return;

      const response = await fetch('/api/admin/governance', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          action: 'run-red-team',
          simulation_type: simulationType
        })
      });

      if (!response.ok) {
        throw new Error('Failed to run simulation');
      }

      await loadDashboardData(); // Refresh data

    } catch (error) {
      console.error('Red team simulation error:', error);
    }
  };

  const resetCircuitBreaker = async () => {
    try {
      const token = localStorage.getItem('admin_token');
      if (!token) return;

      const response = await fetch('/api/admin/governance', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ action: 'reset-circuit-breaker' })
      });

      if (!response.ok) {
        throw new Error('Failed to reset circuit breaker');
      }

      await loadDashboardData();

    } catch (error) {
      console.error('Circuit breaker reset error:', error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading governance dashboard...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="p-6 max-w-md">
          <h2 className="text-xl font-semibold text-red-600 mb-4">Error</h2>
          <p className="text-gray-600 mb-4">{error}</p>
          <Button onClick={loadDashboardData}>Retry</Button>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2">Governance Dashboard</h1>
          <p className="text-gray-600">
            Monitor the Governed Hybrid Opponent System
          </p>
        </div>

        <Tabs defaultValue="overview" className="space-y-6">
          <TabsList>
            <TabsTrigger value="overview">Overview</TabsTrigger>
            <TabsTrigger value="telemetry">Telemetry</TabsTrigger>
            <TabsTrigger value="red-team">Red Team</TabsTrigger>
            <TabsTrigger value="actions">Actions</TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="space-y-6">
            {/* Key Metrics */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <Card className="p-4">
                <h3 className="text-sm font-medium text-gray-600">Total Plans</h3>
                <div className="text-2xl font-bold">{stats?.total_plans || 0}</div>
              </Card>
              <Card className="p-4">
                <h3 className="text-sm font-medium text-gray-600">Avg Latency</h3>
                <div className="text-2xl font-bold">{stats?.average_latency || 0}ms</div>
              </Card>
              <Card className="p-4">
                <h3 className="text-sm font-medium text-gray-600">Avg Cost</h3>
                <div className="text-2xl font-bold">${(stats?.average_cost || 0).toFixed(4)}</div>
              </Card>
              <Card className="p-4">
                <h3 className="text-sm font-medium text-gray-600">Circuit Breaker</h3>
                <div className="text-2xl font-bold">
                  <Badge variant={stats?.circuit_breaker_status?.state === 'CLOSED' ? 'default' : 'destructive'}>
                    {stats?.circuit_breaker_status?.state || 'UNKNOWN'}
                  </Badge>
                </div>
              </Card>
            </div>

            {/* Tier Distribution */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Card className="p-6">
                <h3 className="text-lg font-semibold mb-4">Tier Distribution</h3>
                <div className="space-y-3">
                  {Object.entries(stats?.tier_distribution || {}).map(([tier, count]) => (
                    <div key={tier} className="flex justify-between items-center">
                      <span className="font-medium">{tier}</span>
                      <div className="flex items-center gap-2">
                        <div className="w-32 bg-gray-200 rounded-full h-2">
                          <div 
                            className="bg-blue-600 h-2 rounded-full"
                            style={{ width: `${(count / (stats?.total_plans || 1)) * 100}%` }}
                          ></div>
                        </div>
                        <span className="text-sm text-gray-600">{count}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </Card>

              <Card className="p-6">
                <h3 className="text-lg font-semibold mb-4">Persona Distribution</h3>
                <div className="space-y-3">
                  {Object.entries(stats?.persona_distribution || {}).map(([persona, count]) => (
                    <div key={persona} className="flex justify-between items-center">
                      <span className="font-medium">{persona}</span>
                      <div className="flex items-center gap-2">
                        <div className="w-32 bg-gray-200 rounded-full h-2">
                          <div 
                            className="bg-green-600 h-2 rounded-full"
                            style={{ width: `${(count / (stats?.total_plans || 1)) * 100}%` }}
                          ></div>
                        </div>
                        <span className="text-sm text-gray-600">{count}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </Card>
            </div>

            {/* Drama Distribution */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold mb-4">Drama Archetype Distribution</h3>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                {Object.entries(stats?.drama_distribution || {}).map(([archetype, count]) => (
                  <div key={archetype} className="text-center">
                    <div className="text-2xl font-bold">{count}</div>
                    <div className="text-sm text-gray-600">{archetype.replace('_', ' ')}</div>
                  </div>
                ))}
              </div>
            </Card>
          </TabsContent>

          <TabsContent value="telemetry" className="space-y-6">
            {/* Performance Metrics */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Card className="p-6">
                <h3 className="text-lg font-semibold mb-4">TTFM Metrics</h3>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span>P50:</span>
                    <span className="font-mono">{metrics?.ttfm_p50 || 0}ms</span>
                  </div>
                  <div className="flex justify-between">
                    <span>P90:</span>
                    <span className="font-mono">{metrics?.ttfm_p90 || 0}ms</span>
                  </div>
                  <div className="flex justify-between">
                    <span>P95:</span>
                    <span className="font-mono">{metrics?.ttfm_p95 || 0}ms</span>
                  </div>
                  <div className="flex justify-between">
                    <span>P99:</span>
                    <span className="font-mono">{metrics?.ttfm_p99 || 0}ms</span>
                  </div>
                </div>
              </Card>

              <Card className="p-6">
                <h3 className="text-lg font-semibold mb-4">User Behavior</h3>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span>Rematch Rate:</span>
                    <span className="font-mono">{((metrics?.rematch_rate || 0) * 100).toFixed(1)}%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Rage Quit Rate:</span>
                    <span className="font-mono text-red-600">{((metrics?.rage_quit_rate || 0) * 100).toFixed(1)}%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Disconnect Rate:</span>
                    <span className="font-mono">{((metrics?.disconnect_rate || 0) * 100).toFixed(1)}%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Total Matches:</span>
                    <span className="font-mono">{metrics?.total_matches || 0}</span>
                  </div>
                </div>
              </Card>
            </div>

            {/* System Health */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold mb-4">System Health</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="text-center">
                  <div className={`text-2xl font-bold ${(metrics?.governance_block_rate || 0) > 0.05 ? 'text-red-600' : 'text-green-600'}`}>
                    {((metrics?.governance_block_rate || 0) * 100).toFixed(1)}%
                  </div>
                  <div className="text-sm text-gray-600">Governance Block Rate</div>
                </div>
                <div className="text-center">
                  <div className={`text-2xl font-bold ${(metrics?.circuit_breaker_open_rate || 0) > 0 ? 'text-red-600' : 'text-green-600'}`}>
                    {metrics?.circuit_breaker_open_rate || 0}
                  </div>
                  <div className="text-sm text-gray-600">Circuit Breaker Opens/hr</div>
                </div>
                <div className="text-center">
                  <div className={`text-2xl font-bold ${(metrics?.fairness_violation_rate || 0) > 0 ? 'text-red-600' : 'text-green-600'}`}>
                    {metrics?.fairness_violation_rate || 0}
                  </div>
                  <div className="text-sm text-gray-600">Fairness Violations/hr</div>
                </div>
              </div>
            </Card>
          </TabsContent>

          <TabsContent value="red-team" className="space-y-6">
            <Card className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-semibold">Red Team Simulations</h3>
                <Button onClick={() => runRedTeamSimulation('WIN_SHAPING_DETECTION')}>
                  Run Win Shaping Test
                </Button>
              </div>

              <div className="space-y-4">
                {redTeamResults.map((result) => (
                  <div key={result.id} className="border rounded p-4">
                    <div className="flex justify-between items-start mb-2">
                      <h4 className="font-medium">{result.simulation_type.replace('_', ' ')}</h4>
                      <div className="flex gap-2">
                        <Badge variant={result.vulnerabilities_found > 0 ? 'destructive' : 'default'}>
                          {result.vulnerabilities_found} vulnerabilities
                        </Badge>
                        <Badge variant={result.policy_updates_required > 0 ? 'outline' : 'default'}>
                          {result.policy_updates_required} updates needed
                        </Badge>
                      </div>
                    </div>
                    <div className="text-sm text-gray-600">
                      Run: {new Date(result.run_date).toLocaleString()}
                    </div>
                  </div>
                ))}

                {redTeamResults.length === 0 && (
                  <div className="text-center text-gray-500 py-8">
                    No red team simulations run yet
                  </div>
                )}
              </div>
            </Card>
          </TabsContent>

          <TabsContent value="actions" className="space-y-6">
            <Card className="p-6">
              <h3 className="text-lg font-semibold mb-4">Admin Actions</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Button onClick={() => resetCircuitBreaker()} variant="outline">
                  Reset Circuit Breaker
                </Button>
                <Button onClick={() => runRedTeamSimulation('ABUSE_SIMULATION')} variant="outline">
                  Run Abuse Simulation
                </Button>
                <Button onClick={() => runRedTeamSimulation('DRAMA_PATTERN_EXPLOIT')} variant="outline">
                  Test Drama Pattern Exploit
                </Button>
                <Button onClick={() => runRedTeamSimulation('COST_SPIKE_DETECTION')} variant="outline">
                  Test Cost Spike Detection
                </Button>
              </div>
            </Card>

            <Card className="p-6">
              <h3 className="text-lg font-semibold mb-4">System Status</h3>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span>Plan Generation Latency Target:</span>
                  <span className={stats?.average_latency && stats.average_latency < 300 ? 'text-green-600' : 'text-red-600'}>
                    {stats?.average_latency || 0}ms / 300ms
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>TTFM P90 Target:</span>
                  <span className={metrics?.ttfm_p90 && metrics.ttfm_p90 < 15000 ? 'text-green-600' : 'text-red-600'}>
                    {metrics?.ttfm_p90 || 0}ms / 15000ms
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Rage Quit Threshold:</span>
                  <span className={metrics?.rage_quit_rate && metrics.rage_quit_rate < 0.05 ? 'text-green-600' : 'text-red-600'}>
                    {((metrics?.rage_quit_rate || 0) * 100).toFixed(1)}% / 5%
                  </span>
                </div>
              </div>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import { formatDistanceToNow } from "@/lib/utils";
import { AlertTriangle, CheckCircle, Clock, Shield, TrendingUp, XCircle, FileText } from "lucide-react";

type ModerationCase = {
  id: string;
  reason: string;
  status: "open" | "in_review" | "resolved" | "escalated" | "closed";
  created_at: string;
  updated_at: string;
  subject_user_id: string | null;
  battle_id: string | null;
  created_by: string | null;
};

type ModerationAction = {
  id: string;
  action_type: string;
  payload: Record<string, unknown> | null;
  created_at: string;
  actor_user_id: string;
};

type Stats = {
  open: number;
  in_review: number;
  resolved: number;
  escalated: number;
};

const STATUS_CONFIG: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
  open: { label: "Open", color: "border-red-500/40 text-red-400", icon: <AlertTriangle className="h-3 w-3" /> },
  in_review: { label: "In Review", color: "border-yellow-500/40 text-yellow-400", icon: <Clock className="h-3 w-3" /> },
  resolved: { label: "Resolved", color: "border-green-500/40 text-green-400", icon: <CheckCircle className="h-3 w-3" /> },
  escalated: { label: "Escalated", color: "border-purple-500/40 text-purple-400", icon: <TrendingUp className="h-3 w-3" /> },
  closed: { label: "Closed", color: "border-muted-foreground/40 text-muted-foreground", icon: <XCircle className="h-3 w-3" /> },
};

const ACTION_LABELS: Record<string, string> = {
  warn: "⚠️ Warn User",
  mute: "🔇 Mute User",
  ban: "🚫 Ban User",
  remove_content: "🗑️ Remove Content",
  dismiss: "✅ Dismiss",
  escalate: "⬆️ Escalate",
  close: "🔒 Close",
  note: "📝 Add Note",
};

function StatCard({ label, value, color }: { label: string; value: number; color: string }) {
  return (
    <Card className="border-border/60 bg-card/30 p-4">
      <div className="text-2xl font-black">{value}</div>
      <div className={`mt-0.5 text-xs font-medium ${color}`}>{label}</div>
    </Card>
  );
}

function CaseRow({
  modCase,
  onClick,
}: {
  modCase: ModerationCase;
  onClick: () => void;
}) {
  const cfg = STATUS_CONFIG[modCase.status] ?? STATUS_CONFIG.open;
  return (
    <button
      onClick={onClick}
      className="flex w-full flex-wrap items-start justify-between gap-3 rounded-lg border border-border/60 bg-card/30 p-4 text-left transition-colors hover:bg-card/60"
    >
      <div className="min-w-0 flex-1">
        <p className="line-clamp-2 text-sm font-medium">{modCase.reason}</p>
        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {modCase.subject_user_id && (
            <span className="font-mono">User: {modCase.subject_user_id.slice(0, 8)}…</span>
          )}
          {modCase.battle_id && (
            <span className="font-mono">Battle: {modCase.battle_id.slice(0, 8)}…</span>
          )}
          <span>{formatDistanceToNow(modCase.created_at)}</span>
        </div>
      </div>
      <Badge variant="outline" className={`shrink-0 flex items-center gap-1 ${cfg.color}`}>
        {cfg.icon} {cfg.label}
      </Badge>
    </button>
  );
}

function CaseDetailModal({
  caseId,
  open,
  onClose,
  onUpdate,
}: {
  caseId: string | null;
  open: boolean;
  onClose: () => void;
  onUpdate: () => void;
}) {
  const [modCase, setModCase] = React.useState<ModerationCase | null>(null);
  const [actions, setActions] = React.useState<ModerationAction[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [actionType, setActionType] = React.useState<string>("");
  const [note, setNote] = React.useState("");
  const [newStatus, setNewStatus] = React.useState<string>("");
  const [submitting, setSubmitting] = React.useState(false);

  React.useEffect(() => {
    if (!caseId || !open) return;
    setLoading(true);
    fetch(`/api/moderation/cases/${caseId}`)
      .then(r => r.json())
      .then(data => {
        setModCase(data.case ?? null);
        setActions(data.actions ?? []);
        setNewStatus(data.case?.status ?? "");
      })
      .catch(() => toast.error("Failed to load case"))
      .finally(() => setLoading(false));
  }, [caseId, open]);

  async function handleSubmit() {
    if (!caseId) return;
    setSubmitting(true);
    try {
      const res = await fetch(`/api/moderation/cases/${caseId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...(newStatus !== modCase?.status ? { status: newStatus } : {}),
          ...(actionType ? { action_type: actionType } : {}),
          ...(note.trim() ? { note: note.trim() } : {}),
        }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error ?? "Action failed");
        return;
      }
      toast.success("Case updated");
      setModCase(json.case);
      setNote("");
      setActionType("");
      onUpdate();
      // Re-fetch actions
      fetch(`/api/moderation/cases/${caseId}`)
        .then(r => r.json())
        .then(d => setActions(d.actions ?? []));
    } catch {
      toast.error("Network error");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="h-4 w-4" />
            Case Details
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="space-y-3">
            <div className="h-20 animate-pulse rounded bg-muted/30" />
            <div className="h-12 animate-pulse rounded bg-muted/30" />
          </div>
        ) : modCase ? (
          <div className="space-y-4">
            {/* Case info */}
            <div className="rounded-lg border border-border/60 bg-muted/10 p-4 text-sm">
              <p className="font-medium">{modCase.reason}</p>
              <div className="mt-2 grid grid-cols-2 gap-2 text-xs text-muted-foreground">
                <div>Status: <span className="text-foreground font-medium">{modCase.status}</span></div>
                <div>Opened: {formatDistanceToNow(modCase.created_at)}</div>
                {modCase.subject_user_id && <div className="col-span-2 font-mono">User: {modCase.subject_user_id}</div>}
                {modCase.battle_id && <div className="col-span-2 font-mono">Battle: {modCase.battle_id}</div>}
              </div>
            </div>

            {/* Action history */}
            {actions.length > 0 && (
              <div>
                <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">Action History</p>
                <div className="max-h-36 space-y-1.5 overflow-y-auto">
                  {actions.map(a => (
                    <div key={a.id} className="flex items-start justify-between gap-2 rounded border border-border/40 bg-muted/10 px-3 py-2 text-xs">
                      <div>
                        <span className="font-medium">{ACTION_LABELS[a.action_type] ?? a.action_type}</span>
                        {a.payload?.note && <span className="ml-2 text-muted-foreground">— {a.payload.note as string}</span>}
                      </div>
                      <span className="shrink-0 text-muted-foreground">{formatDistanceToNow(a.created_at)}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <Separator />

            {/* Take action */}
            <div className="space-y-3">
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Take Action</p>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="mb-1 block text-xs text-muted-foreground">Update Status</label>
                  <Select value={newStatus} onValueChange={setNewStatus}>
                    <SelectTrigger className="h-8 text-xs">
                      <SelectValue placeholder="Status" />
                    </SelectTrigger>
                    <SelectContent>
                      {Object.entries(STATUS_CONFIG).map(([val, cfg]) => (
                        <SelectItem key={val} value={val}>{cfg.label}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <label className="mb-1 block text-xs text-muted-foreground">Action Type</label>
                  <Select value={actionType} onValueChange={setActionType}>
                    <SelectTrigger className="h-8 text-xs">
                      <SelectValue placeholder="Action (optional)" />
                    </SelectTrigger>
                    <SelectContent>
                      {Object.entries(ACTION_LABELS).map(([val, label]) => (
                        <SelectItem key={val} value={val}>{label}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <Textarea
                placeholder="Optional note or reason for this action…"
                value={note}
                onChange={e => setNote(e.target.value)}
                className="h-20 text-sm"
              />

              <Button
                size="sm"
                onClick={handleSubmit}
                disabled={submitting || (!actionType && !note.trim() && newStatus === modCase.status)}
                className="w-full"
              >
                {submitting ? "Saving…" : "Submit Action"}
              </Button>
            </div>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground">Case not found.</p>
        )}
      </DialogContent>
    </Dialog>
  );
}

export function ModerationConsole() {
  const [stats, setStats] = React.useState<Stats | null>(null);
  const [cases, setCases] = React.useState<ModerationCase[]>([]);
  const [statusFilter, setStatusFilter] = React.useState("open");
  const [page, setPage] = React.useState(0);
  const [totalPages, setTotalPages] = React.useState(1);
  const [total, setTotal] = React.useState(0);
  const [loading, setLoading] = React.useState(true);
  const [selectedCaseId, setSelectedCaseId] = React.useState<string | null>(null);
  const [modalOpen, setModalOpen] = React.useState(false);

  async function fetchData() {
    setLoading(true);
    try {
      const [statsRes, casesRes] = await Promise.all([
        fetch("/api/moderation/stats"),
        fetch(`/api/moderation/cases?status=${statusFilter}&page=${page}`),
      ]);
      const [statsData, casesData] = await Promise.all([statsRes.json(), casesRes.json()]);
      setStats(statsData);
      setCases(casesData.cases ?? []);
      setTotalPages(casesData.pages ?? 1);
      setTotal(casesData.total ?? 0);
    } catch {
      toast.error("Failed to load moderation data");
    } finally {
      setLoading(false);
    }
  }

  React.useEffect(() => { fetchData(); }, [statusFilter, page]);

  function openCase(id: string) {
    setSelectedCaseId(id);
    setModalOpen(true);
  }

  return (
    <div className="space-y-6">
      {/* Stats */}
      {stats && (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          <StatCard label="Open" value={stats.open} color="text-red-400" />
          <StatCard label="In Review" value={stats.in_review} color="text-yellow-400" />
          <StatCard label="Escalated" value={stats.escalated} color="text-purple-400" />
          <StatCard label="Resolved" value={stats.resolved} color="text-green-400" />
        </div>
      )}

      {/* Filter bar */}
      <div className="flex flex-wrap items-center gap-2">
        {Object.entries(STATUS_CONFIG).map(([val, cfg]) => (
          <Button
            key={val}
            size="sm"
            variant={statusFilter === val ? "default" : "outline"}
            onClick={() => { setStatusFilter(val); setPage(0); }}
          >
            {cfg.label}
          </Button>
        ))}
        <Button size="sm" variant={statusFilter === "all" ? "default" : "outline"} onClick={() => { setStatusFilter("all"); setPage(0); }}>
          All ({total})
        </Button>
      </div>

      {/* Case list */}
      {loading ? (
        <div className="space-y-2">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="h-20 animate-pulse rounded-lg bg-muted/30" />
          ))}
        </div>
      ) : cases.length === 0 ? (
        <Card className="border-border/60 bg-card/30 p-10 text-center">
          <Shield className="mx-auto h-8 w-8 text-muted-foreground/30" />
          <p className="mt-2 text-sm text-muted-foreground">
            No {statusFilter === "all" ? "" : statusFilter} cases.
          </p>
        </Card>
      ) : (
        <div className="space-y-2">
          {cases.map(c => (
            <CaseRow key={c.id} modCase={c} onClick={() => openCase(c.id)} />
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between text-sm">
          <span className="text-muted-foreground">
            Page {page + 1} of {totalPages}
          </span>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" disabled={page === 0} onClick={() => setPage(p => p - 1)}>Previous</Button>
            <Button size="sm" variant="outline" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>Next</Button>
          </div>
        </div>
      )}

      {/* Case detail modal */}
      <CaseDetailModal
        caseId={selectedCaseId}
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onUpdate={fetchData}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { BeatPlayer } from './BeatPlayer';

interface Beat {
  id: string;
  title: string;
  artist: string;
  tempo: number;
  key_signature: string;
  genre: string;
  duration_seconds: number;
  preview_url: string;
  file_url: string;
  is_active: boolean;
  is_verified: boolean;
  usage_count: number;
  created_at: string;
}

interface BeatLibraryProps {
  onBeatSelect?: (beat: Beat) => void;
  selectedBeatId?: string;
}

export function BeatLibrary({ onBeatSelect, selectedBeatId }: BeatLibraryProps) {
  const [beats, setBeats] = useState<Beat[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGenre, setSelectedGenre] = useState<string>('all');
  const [selectedBeat, setSelectedBeat] = useState<Beat | undefined>();
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  const genres = ['all', 'hip-hop', 'r&b', 'trap', 'drill', 'afrobeat', 'pop', 'electronic'];

  useEffect(() => {
    fetchBeats();
  }, [currentPage, selectedGenre, searchTerm]);

  const fetchBeats = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '20',
        ...(selectedGenre !== 'all' && { genre: selectedGenre }),
        ...(searchTerm && { search: searchTerm })
      });

      const response = await fetch(`/api/beats?${params}`);
      if (!response.ok) {
        throw new Error('Failed to fetch beats');
      }

      const data = await response.json();
      setBeats(data.beats || []);
      setTotalPages(data.totalPages || 1);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load beats');
      setBeats([]);
    } finally {
      setLoading(false);
    }
  };

  const handleBeatSelect = (beat: Beat) => {
    setSelectedBeat(beat);
    setIsPlaying(false);
    onBeatSelect?.(beat);
  };

  const handlePlayPause = () => {
    if (selectedBeat) {
      setIsPlaying(!isPlaying);
    }
  };

  const filteredBeats = beats.filter(beat =>
    beat.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    beat.artist.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading && beats.length === 0) {
    return (
      <div className="space-y-6">
        <div className="text-center py-12">
          <div className="w-16 h-16 border-4 border-gray-300 border-t-gray-600 rounded-full animate-spin mx-auto mb-4" />
          <p className="text-gray-600">Loading beats...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-semibold">Beat Library</h2>
        <p className="text-gray-600">Choose the perfect beat for your battle</p>
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="flex flex-col md:flex-row gap-4">
          <Input
            placeholder="Search beats or artists..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="flex-1"
          />
          <div className="flex gap-2 flex-wrap">
            {genres.map(genre => (
              <Button
                key={genre}
                variant={selectedGenre === genre ? 'default' : 'outline'}
                size="sm"
                onClick={() => setSelectedGenre(genre)}
              >
                {genre.charAt(0).toUpperCase() + genre.slice(1)}
              </Button>
            ))}
          </div>
        </div>
      </Card>

      {/* Beat Player */}
      {selectedBeat && (
        <BeatPlayer
          beat={selectedBeat}
          isPlaying={isPlaying}
          onPlayPause={handlePlayPause}
        />
      )}

      {/* Error Display */}
      {error && (
        <Card className="p-4 border-red-300 bg-red-50">
          <p className="text-red-700">{error}</p>
          <Button onClick={fetchBeats} variant="outline" size="sm" className="mt-2">
            Retry
          </Button>
        </Card>
      )}

      {/* Beats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredBeats.map(beat => (
          <Card 
            key={beat.id} 
            className={`p-4 cursor-pointer transition-all hover:shadow-md ${
              selectedBeatId === beat.id ? 'ring-2 ring-blue-500' : ''
            }`}
            onClick={() => handleBeatSelect(beat)}
          >
            <div className="space-y-3">
              {/* Beat Info */}
              <div>
                <h3 className="font-semibold truncate">{beat.title}</h3>
                <p className="text-sm text-gray-600 truncate">{beat.artist}</p>
              </div>

              {/* Metadata */}
              <div className="flex gap-2 flex-wrap">
                <Badge variant="secondary">{beat.genre}</Badge>
                <Badge variant="outline">{beat.tempo} BPM</Badge>
                <Badge variant="outline">{beat.key_signature}</Badge>
                {beat.is_verified && (
                  <Badge variant="default" className="bg-green-500">Verified</Badge>
                )}
              </div>

              {/* Stats */}
              <div className="flex justify-between text-sm text-gray-500">
                <span>{Math.floor(beat.duration_seconds / 60)}:{(beat.duration_seconds % 60).toString().padStart(2, '0')}</span>
                <span>{beat.usage_count} uses</span>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-2">
                <Button
                  size="sm"
                  variant={selectedBeatId === beat.id ? 'default' : 'outline'}
                  className="flex-1"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleBeatSelect(beat);
                  }}
                >
                  {selectedBeatId === beat.id ? 'Selected' : 'Select'}
                </Button>

                {/* Preview Button */}
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={(e) => {
                    e.stopPropagation();
                    // Handle preview
                    if (selectedBeat?.id === beat.id) {
                      handlePlayPause();
                    } else {
                      handleBeatSelect(beat);
                      setTimeout(() => setIsPlaying(true), 100);
                    }
                  }}
                >
                  {selectedBeat?.id === beat.id && isPlaying ? (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  ) : (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  )}
                </Button>
              </div>
            </div>
          </Card>
        ))}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={currentPage === 1}
            onClick={() => setCurrentPage(currentPage - 1)}
          >
            Previous
          </Button>
          <span className="py-2 px-4">
            Page {currentPage} of {totalPages}
          </span>
          <Button
            variant="outline"
            disabled={currentPage === totalPages}
            onClick={() => setCurrentPage(currentPage + 1)}
          >
            Next
          </Button>
        </div>
      )}

      {/* Empty State */}
      {!loading && filteredBeats.length === 0 && !error && (
        <div className="text-center py-12">
          <div className="w-16 h-16 bg-gray-200 rounded-full mx-auto mb-4 flex items-center justify-center">
            <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" />
            </svg>
          </div>
          <p className="text-gray-600">No beats found</p>
          <p className="text-sm text-gray-500">Try adjusting your filters or search terms</p>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Mic, MicOff, Play, Pause, SkipForward, Trophy, Users, Clock } from 'lucide-react';
import { toast } from 'sonner';

interface BattleRoomProps {
  battleId: string;
  roomCode: string;
  isCreator: boolean;
  onLeave: () => void;
}

interface BattleParticipant {
  id: string;
  username: string;
  avatar?: string;
  tier: string;
  isReady: boolean;
  isRecording: boolean;
  audioLevel: number;
}

interface BattleState {
  status: 'waiting' | 'starting' | 'active' | 'round_active' | 'completed';
  currentRound: number;
  totalRounds: number;
  timeRemaining: number;
  roundTimeLimit: number;
  participants: BattleParticipant[];
  currentTurn?: string;
  beat?: {
    id: string;
    title: string;
    artist: string;
    tempo: number;
    previewUrl: string;
  };
}

export function BattleRoom({ battleId, roomCode, isCreator, onLeave }: BattleRoomProps) {
  const [battleState, setBattleState] = useState<BattleState>({
    status: 'waiting',
    currentRound: 1,
    totalRounds: 2,
    timeRemaining: 0,
    roundTimeLimit: 30,
    participants: [],
    beat: undefined
  });

  const [isRecording, setIsRecording] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [audioLevel, setAudioLevel] = useState(0);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const websocketRef = useRef<WebSocket | null>(null);

  // Initialize WebSocket connection
  useEffect(() => {
    const wsUrl = `ws://localhost:8080/v1/ws/battles/${battleId}?token=${localStorage.getItem('access_token')}`;
    const ws = new WebSocket(wsUrl);
    websocketRef.current = ws;

    ws.onopen = () => {
      console.log('Connected to battle room');
      ws.send(JSON.stringify({
        type: 'join_room',
        data: { room_code: roomCode }
      }));
    };

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data);
      handleWebSocketMessage(message);
    };

    ws.onclose = () => {
      console.log('Disconnected from battle room');
    };

    return () => {
      ws.close();
    };
  }, [battleId, roomCode]);

  const handleWebSocketMessage = (message: any) => {
    switch (message.type) {
      case 'battle_update':
        setBattleState(prev => ({ ...prev, ...message.data }));
        break;
      case 'round_start':
        setBattleState(prev => ({ ...prev, status: 'round_active', currentTurn: message.data.participant_id }));
        if (message.data.participant_id === getCurrentUserId()) {
          startRecording();
        }
        break;
      case 'round_complete':
        setBattleState(prev => ({ ...prev, status: 'active' }));
        if (message.data.participant_id === getCurrentUserId()) {
          stopRecording();
        }
        break;
      case 'battle_complete':
        setBattleState(prev => ({ ...prev, status: 'completed' }));
        break;
      case 'participant_joined':
        setBattleState(prev => ({
          ...prev,
          participants: [...prev.participants, message.data.participant]
        }));
        break;
      case 'participant_left':
        setBattleState(prev => ({
          ...prev,
          participants: prev.participants.filter(p => p.id !== message.data.participant_id)
        }));
        break;
    }
  };

  const getCurrentUserId = () => {
    // Get current user ID from auth context or localStorage
    return localStorage.getItem('user_id') || '';
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      audioContextRef.current = new AudioContext();
      analyserRef.current = audioContextRef.current.createAnalyser();
      const source = audioContextRef.current.createMediaStreamSource(stream);
      source.connect(analyserRef.current);

      mediaRecorderRef.current = new MediaRecorder(stream);
      const chunks: Blob[] = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunks.push(event.data);
        }
      };

      mediaRecorderRef.current.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        submitRecording(blob);
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);

      // Monitor audio levels
      monitorAudioLevel();

    } catch (error) {
      console.error('Error starting recording:', error);
      toast.error('Failed to start recording');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);

      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    }
  };

  const monitorAudioLevel = () => {
    if (!analyserRef.current || !isRecording) return;

    const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
    analyserRef.current.getByteFrequencyData(dataArray);

    const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
    setAudioLevel(average / 255);

    if (isRecording) {
      requestAnimationFrame(monitorAudioLevel);
    }
  };

  const submitRecording = async (audioBlob: Blob) => {
    try {
      const formData = new FormData();
      formData.append('audio_file', audioBlob);
      formData.append('round_number', battleState.currentRound.toString());
      formData.append('duration_seconds', '30');

      const response = await fetch(`/api/battles/${battleId}/rounds`, {
        method: 'POST',
        body: formData,
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to submit recording');
      }

      toast.success('Recording submitted successfully');
    } catch (error) {
      console.error('Error submitting recording:', error);
      toast.error('Failed to submit recording');
    }
  };

  const startBattle = () => {
    if (!isCreator) return;

    websocketRef.current?.send(JSON.stringify({
      type: 'start_battle',
      data: {}
    }));
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'waiting': return 'bg-yellow-500';
      case 'starting': return 'bg-blue-500';
      case 'active': return 'bg-green-500';
      case 'round_active': return 'bg-red-500';
      case 'completed': return 'bg-purple-500';
      default: return 'bg-gray-500';
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 text-white p-4">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center space-x-4">
            <h1 className="text-3xl font-bold">Battle Room</h1>
            <Badge variant="secondary" className="text-white bg-black/20">
              Room Code: {roomCode}
            </Badge>
            <Badge className={`${getStatusColor(battleState.status)} text-white`}>
              {battleState.status.replace('_', ' ').toUpperCase()}
            </Badge>
          </div>

          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-2">
              <Clock className="w-4 h-4" />
              <span>{formatTime(battleState.timeRemaining)}</span>
            </div>
            <Button variant="outline" onClick={onLeave}>
              Leave Battle
            </Button>
          </div>
        </div>

        {/* Battle Info */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
          {/* Participants */}
          <Card className="bg-black/20 border-white/10">
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <Users className="w-5 h-5" />
                <span>Participants</span>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {battleState.participants.map((participant) => (
                  <motion.div
                    key={participant.id}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="flex items-center justify-between p-3 rounded-lg bg-white/5"
                  >
                    <div className="flex items-center space-x-3">
                      <div className="w-10 h-10 rounded-full bg-gradient-to-r from-purple-500 to-pink-500 flex items-center justify-center">
                        <span className="text-sm font-bold">
                          {participant.username.charAt(0).toUpperCase()}
                        </span>
                      </div>
                      <div>
                        <p className="font-semibold">{participant.username}</p>
                        <Badge variant="outline" className="text-xs">
                          {participant.tier}
                        </Badge>
                      </div>
                    </div>

                    <div className="flex items-center space-x-2">
                      {participant.isRecording && (
                        <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                      )}
                      {participant.isReady && (
                        <Badge variant="default" className="text-xs bg-green-500">
                          Ready
                        </Badge>
                      )}
                    </div>
                  </motion.div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Battle Controls */}
          <Card className="bg-black/20 border-white/10">
            <CardHeader>
              <CardTitle>Battle Controls</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="text-center">
                <p className="text-2xl font-bold mb-2">
                  Round {battleState.currentRound} of {battleState.totalRounds}
                </p>
                <Progress 
                  value={(battleState.currentRound / battleState.totalRounds) * 100} 
                  className="w-full mb-4"
                />
              </div>

              {battleState.beat && (
                <div className="p-4 rounded-lg bg-white/5">
                  <p className="font-semibold mb-2">Current Beat</p>
                  <p className="text-sm">{battleState.beat.title} - {battleState.beat.artist}</p>
                  <p className="text-xs text-gray-400">{battleState.beat.tempo} BPM</p>
                </div>
              )}

              {isCreator && battleState.status === 'waiting' && (
                <Button onClick={startBattle} className="w-full" size="lg">
                  <Play className="w-4 h-4 mr-2" />
                  Start Battle
                </Button>
              )}

              {battleState.status === 'completed' && (
                <div className="text-center">
                  <Trophy className="w-12 h-12 mx-auto mb-2 text-yellow-500" />
                  <p className="text-lg font-semibold">Battle Complete!</p>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Audio Controls */}
          <Card className="bg-black/20 border-white/10">
            <CardHeader>
              <CardTitle>Audio Controls</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex justify-center space-x-4">
                <Button
                  variant={isRecording ? "destructive" : "default"}
                  size="lg"
                  onClick={isRecording ? stopRecording : startRecording}
                  disabled={battleState.status !== 'round_active' || battleState.currentTurn !== getCurrentUserId()}
                >
                  {isRecording ? (
                    <>
                      <Pause className="w-4 h-4 mr-2" />
                      Stop Recording
                    </>
                  ) : (
                    <>
                      <Mic className="w-4 h-4 mr-2" />
                      Start Recording
                    </>
                  )}
                </Button>

                <Button
                  variant="outline"
                  size="lg"
                  onClick={toggleMute}
                >
                  {isMuted ? (
                    <MicOff className="w-4 h-4" />
                  ) : (
                    <Mic className="w-4 h-4" />
                  )}
                </Button>
              </div>

              {/* Audio Level Meter */}
              <div className="space-y-2">
                <p className="text-sm text-gray-400">Audio Level</p>
                <div className="h-4 bg-black/30 rounded-full overflow-hidden">
                  <motion.div
                    className="h-full bg-gradient-to-r from-green-500 to-yellow-500"
                    style={{ width: `${audioLevel * 100}%` }}
                    animate={{ width: `${audioLevel * 100}%` }}
                    transition={{ duration: 0.1 }}
                  />
                </div>
              </div>

              {battleState.status === 'round_active' && battleState.currentTurn === getCurrentUserId() && (
                <div className="text-center p-4 rounded-lg bg-red-500/20 border border-red-500/50">
                  <p className="text-red-400 font-semibold">Your Turn!</p>
                  <p className="text-sm">Start recording when ready</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Spectator Area */}
        {battleState.participants.length < 2 && (
          <Card className="bg-black/20 border-white/10">
            <CardContent className="text-center py-8">
              <Users className="w-12 h-12 mx-auto mb-4 text-gray-400" />
              <p className="text-lg font-semibold mb-2">Waiting for Participants</p>
              <p className="text-gray-400">Share room code: {roomCode}</p>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

import { useRouter, useSearchParams } from "next/navigation";
import type { RealtimeChannel } from "@supabase/supabase-js";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";

import { VideoBattleProduction } from "@/components/battle/VideoBattleProduction";
import { useBattleSessionStore, type BattleSessionMode } from "@/lib/battle/session-store";
import { createSupabaseBrowserClient } from "@/lib/supabase/browser";

type BattleParticipant = {
  user_id: string;
  slot: number;
  score: number | null;
  handle?: string | null;
  display_name?: string | null;
};

type BattleSessionMetadata = {
  id: string;
  status: string;
  mode: string;
  created_by?: string | null;
  viewer_user_id?: string | null;
  started_at?: string | null;
  ended_at?: string | null;
  created_at: string | null;
  can_manage?: boolean;
  viewer_role?: string | null;
  current_round?: number | null;
  voting_opened_at?: string | null;
  voting_closes_at?: string | null;
  result?: unknown | null;
  participants: BattleParticipant[];
};

type FinalizeApiOk = {
  ok: true;
  mode: "supabase";
  battleId: string;
  result: {
    battle_id: string;
    winner_slot?: number | null;
    final_scores?: { 1: number; 2: number } | null;
  };
};

function formatMMSS(totalSeconds: number) {
  const s = Math.max(0, Math.floor(totalSeconds));
  const mm = String(Math.floor(s / 60)).padStart(2, "0");
  const ss = String(s % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

type Beat = { id: string; title: string; bpm: number; lengthSeconds: number };

// TODO: Replace with real beat library integration
// This should fetch from a real beat library API or database
type MicStatus = "idle" | "requesting" | "granted" | "denied" | "unsupported" | "error";

type ChatMessage = { id: string; author: string; body: string; ts: number };

type SessionRole = "user" | "mod" | "admin";

type RecordingRow = {
  id: string;
  storage_bucket: string | null;
  storage_path: string | null;
  uploaded_at?: string | null;
  created_at?: string;
  mime_type?: string | null;
  duration_seconds?: number | null;
  bytes?: number | null;
  note?: string | null;
};

export function BattleRoomCockpit() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const storedBattleId = useBattleSessionStore((s) => s.battleId);
  const storedMode = useBattleSessionStore((s) => s.mode);
  const setStoredSession = useBattleSessionStore((s) => s.setSession);
  const clearStoredSession = useBattleSessionStore((s) => s.clear);

  const [round] = React.useState(1);
  const [latencyMs] = React.useState<number | null>(null);
  const [sessionId, setSessionId] = React.useState<string | null>(null);
  const [sessionMode, setSessionMode] = React.useState<"supabase" | null>(null);
  const [sessionError, setSessionError] = React.useState<string | null>(null);
  const [autoCreateEnabled, setAutoCreateEnabled] = React.useState(true);

  const [sessionMeta, setSessionMeta] = React.useState<BattleSessionMetadata | null>(null);
  const [sessionMetaError, setSessionMetaError] = React.useState<string | null>(null);
  const [joinError, setJoinError] = React.useState<string | null>(null);
  const [isJoining, setIsJoining] = React.useState(false);
  const [statusError, setStatusError] = React.useState<string | null>(null);
  const [isUpdatingStatus, setIsUpdatingStatus] = React.useState(false);
  const [finalizeError, setFinalizeError] = React.useState<string | null>(null);
  const [isFinalizing, setIsFinalizing] = React.useState(false);
  const [finalizeInfo, setFinalizeInfo] = React.useState<FinalizeApiOk | null>(null);
  const [nowMs, setNowMs] = React.useState(() => Date.now());

  React.useEffect(() => {
    let cancelled = false;

    const urlBattleId = searchParams.get("battleId");
    const resolvedId = urlBattleId ?? storedBattleId;
    const resolvedMode: BattleSessionMode | null = storedMode;

    if (resolvedId) {
      setSessionId(resolvedId);
      setSessionMode(resolvedMode ?? "supabase");
      setSessionError(null);

      if (!urlBattleId) {
        const next = new URLSearchParams(searchParams.toString());
        next.set("battleId", resolvedId);
        router.replace(`/app/battles/room?${next.toString()}`);
      }
      if (!storedBattleId || storedBattleId !== resolvedId) {
        setStoredSession({
          battleId: resolvedId,
          mode: "supabase" as BattleSessionMode,
        });
      }
      return () => {
        cancelled = true;
      };
    }

    if (!autoCreateEnabled) {
      return () => {
        cancelled = true;
      };
    }

    async function ensureSession() {
      try {
        const res = await fetch("/api/battle-session", {
          method: "POST",
          headers: { "content-type": "application/json" },
        });
        const body = (await res.json()) as
          | { ok: true; mode: "supabase"; battleId: string }
          | { error: string; details?: string };
        if (cancelled) return;

        if (!res.ok || !("ok" in body)) {
          setSessionError("Unable to create battle session.");
          return;
        }

        setSessionId(body.battleId);
        setSessionMode(body.mode);
        setStoredSession({ battleId: body.battleId, mode: body.mode });

        const next = new URLSearchParams(searchParams.toString());
        next.set("battleId", body.battleId);
        router.replace(`/app/battles/room?${next.toString()}`);
      } catch {
        if (cancelled) return;
        setSessionError("Unable to create battle session.");
      }
    }

    void ensureSession();
    return () => {
      cancelled = true;
    };
  }, [autoCreateEnabled, router, searchParams, setStoredSession, storedBattleId, storedMode]);

  React.useEffect(() => {
    let cancelled = false;
    async function loadMeta() {
      if (!sessionId) {
        setSessionMeta(null);
        setSessionMetaError(null);
        return;
      }

      try {
        const url = `/api/battle-session?battleId=${encodeURIComponent(sessionId)}`;
        const res = await fetch(url, { method: "GET" });
        const body = (await res.json()) as
          | { ok: true; mode: "supabase"; session: BattleSessionMetadata }
          | { error: string; details?: string };

        if (cancelled) return;

        if (!res.ok || !("ok" in body)) {
          setSessionMeta(null);
          setSessionMetaError("Unable to load battle metadata.");
          return;
        }

        setSessionMeta(body.session);
        setSessionMetaError(null);
      } catch {
        if (cancelled) return;
        setSessionMeta(null);
        setSessionMetaError("Unable to load battle metadata.");
      }
    }

    void loadMeta();
    return () => {
      cancelled = true;
    };
  }, [sessionId]);

  async function joinAsB() {
    if (!sessionId) return;
    setIsJoining(true);
    setJoinError(null);
    try {
      const res = await fetch("/api/battle-session/join", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ battleId: sessionId }),
      });

      if (!res.ok) {
        setJoinError("Unable to join battle.");
        return;
      }

      const url = `/api/battle-session?battleId=${encodeURIComponent(sessionId)}`;
      const metaRes = await fetch(url, { method: "GET" });
      const metaBody = (await metaRes.json()) as
        | { ok: true; mode: "supabase"; session: BattleSessionMetadata }
        | { error: string; details?: string };

      if (!metaRes.ok || !("ok" in metaBody)) {
        setJoinError("Joined, but unable to refresh battle metadata.");
        return;
      }

      setSessionMeta(metaBody.session);
    } catch {
      setJoinError("Unable to join battle.");
    } finally {
      setIsJoining(false);
    }
  }

  async function updateBattleStatus(status: "live" | "complete") {
    if (!sessionId) return;
    setIsUpdatingStatus(true);
    setStatusError(null);
    try {
      const res = await fetch("/api/battle-session/status", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ battleId: sessionId, status }),
      });

      if (!res.ok) {
        setStatusError("Unable to update battle status.");
        return;
      }

      const url = `/api/battle-session?battleId=${encodeURIComponent(sessionId)}`;
      const metaRes = await fetch(url, { method: "GET" });
      const metaBody = (await metaRes.json()) as
        | { ok: true; mode: "supabase"; session: BattleSessionMetadata }
        | { error: string; details?: string };

      if (!metaRes.ok || !("ok" in metaBody)) {
        setStatusError("Updated, but unable to refresh battle metadata.");
        return;
      }

      setSessionMeta(metaBody.session);
    } catch {
      setStatusError("Unable to update battle status.");
    } finally {
      setIsUpdatingStatus(false);
    }
  }

  async function finalizeBattle() {
    if (!sessionId) return;
    setIsFinalizing(true);
    setFinalizeError(null);
    setFinalizeInfo(null);
    try {
      const res = await fetch("/api/battle-session/finalize", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ battleId: sessionId }),
      });

      const body = (await res.json().catch(() => null)) as unknown;

      if (!res.ok) {
        const details =
          body && typeof body === "object" && body && "details" in body
            ? String((body as { details?: unknown }).details)
            : null;
        setFinalizeError(details ? `Unable to finalize battle: ${details}` : "Unable to finalize battle.");
        return;
      }

      if (body && typeof body === "object" && "ok" in body && (body as { ok?: unknown }).ok === true) {
        setFinalizeInfo(body as FinalizeApiOk);
      }

      const url = `/api/battle-session?battleId=${encodeURIComponent(sessionId)}`;
      const metaRes = await fetch(url, { method: "GET" });
      const metaBody = (await metaRes.json()) as
        | { ok: true; mode: "supabase"; session: BattleSessionMetadata }
        | { error: string; details?: string };

      if (!metaRes.ok || !("ok" in metaBody)) {
        setFinalizeError("Finalized, but unable to refresh battle metadata.");
        return;
      }

      setSessionMeta(metaBody.session);
    } catch {
      setFinalizeError("Unable to finalize battle.");
    } finally {
      setIsFinalizing(false);
    }
  }

  const derivedResult =
    (finalizeInfo?.result as unknown) ?? (sessionMeta?.result as unknown) ?? null;

  const counts =
    derivedResult && typeof derivedResult === "object" && "counts" in derivedResult
      ? ((derivedResult as { counts?: Record<string, number> }).counts ?? null)
      : null;

  const winnerSlot =
    derivedResult && typeof derivedResult === "object" && "winner_slot" in derivedResult
      ? ((derivedResult as { winner_slot?: number | null }).winner_slot ?? null)
      : null;

  const votingClosesAt = sessionMeta?.voting_closes_at ?? null;
  const votingClosesMs = votingClosesAt ? new Date(votingClosesAt).getTime() : null;
  const votingRemainingSeconds = votingClosesMs
    ? Math.max(0, Math.floor((votingClosesMs - nowMs) / 1000))
    : null;
  const votingClosed =
    sessionMode === "supabase" && (votingRemainingSeconds === null || votingRemainingSeconds <= 0);

  const battleStatus = sessionMeta?.status ?? "--";
  const statusBadge =
    battleStatus === "live"
      ? { label: `LIVE (${sessionMode ?? "…"})`, className: "bg-emerald-500/15 text-emerald-200" }
      : battleStatus === "queued" || battleStatus === "draft"
        ? { label: `${battleStatus.toUpperCase()} (${sessionMode ?? "…"})`, className: "bg-amber-500/15 text-amber-200" }
        : battleStatus === "complete"
          ? { label: `COMPLETE (${sessionMode ?? "…"})`, className: "bg-slate-500/20 text-slate-200" }
          : battleStatus === "canceled"
            ? { label: `CANCELED (${sessionMode ?? "…"})`, className: "bg-slate-500/20 text-slate-200" }
            : { label: `${battleStatus.toUpperCase()} (${sessionMode ?? "…"})`, className: "bg-slate-500/20 text-slate-200" };

  function leaveBattle() {
    clearStoredSession();
    setSessionId(null);
    setSessionMode(null);
    setSessionError(null);
    setAutoCreateEnabled(false);
    router.replace("/app/battles/room");
  }

  function startNewBattle() {
    setAutoCreateEnabled(true);
  }

  const slotA = sessionMeta?.participants?.find((p) => p.slot === 1) ?? null;
  const slotB = sessionMeta?.participants?.find((p) => p.slot === 2) ?? null;
  const showJoinAsB = Boolean(sessionId && !slotB);

  function formatParticipantLabel(p: BattleParticipant | null) {
    if (!p) return "--------";
    const label = p.display_name ?? p.handle;
    if (label && label.trim().length > 0) return label;
    return p.user_id.slice(0, 8);
  }

  const [countdownSeconds, setCountdownSeconds] = React.useState(10);
  React.useEffect(() => {
    const t = window.setInterval(() => {
      setCountdownSeconds((s) => (s > 0 ? s - 1 : 0));
    }, 1000);
    return () => window.clearInterval(t);
  }, []);

  const [beatModalOpen, setBeatModalOpen] = React.useState(false);
  const [currentBeat, setCurrentBeat] = React.useState<Beat | null>(null);
  const [beatPlaying, setBeatPlaying] = React.useState(false);

  const [micStatus, setMicStatus] = React.useState<MicStatus>("idle");
  const [isClient, setIsClient] = React.useState(false);

  // FIX: Initialize mic status only on client side
  React.useEffect(() => {
    setIsClient(true);
    if (!navigator.mediaDevices?.getUserMedia) {
      setMicStatus("unsupported");
    } else if (typeof MediaRecorder === "undefined") {
      setMicStatus("unsupported");
    }
  }, []);
  const [micError, setMicError] = React.useState<string | null>(null);
  const streamRef = React.useRef<MediaStream | null>(null);
  const recorderRef = React.useRef<MediaRecorder | null>(null);
  const chunksRef = React.useRef<BlobPart[]>([]);
  const [recordingState, setRecordingState] = React.useState<"idle" | "recording" | "stopped" | "playing">(
    "idle",
  );
  const [recordingSeconds, setRecordingSeconds] = React.useState(0);
  const [recordingBlob, setRecordingBlob] = React.useState<Blob | null>(null);
  const [recordingUrl, setRecordingUrl] = React.useState<string | null>(null);
  const audioRef = React.useRef<HTMLAudioElement | null>(null);

  React.useEffect(() => {
    if (recordingState !== "recording") return;
    const t = window.setInterval(() => {
      setRecordingSeconds((s) => s + 1);
    }, 1000);
    return () => window.clearInterval(t);
  }, [recordingState]);

  React.useEffect(() => {
    return () => {
      if (recordingUrl) URL.revokeObjectURL(recordingUrl);
      if (streamRef.current) {
        for (const track of streamRef.current.getTracks()) track.stop();
        streamRef.current = null;
      }
    };
  }, [recordingUrl]);

  React.useEffect(() => {
    const t = window.setInterval(() => setNowMs(Date.now()), 1000);
    return () => window.clearInterval(t);
  }, []);

  const [messages, setMessages] = React.useState<ChatMessage[]>([]);
  const [chatDraft, setChatDraft] = React.useState("");
  const [onlineCount, setOnlineCount] = React.useState<number | null>(null);
  const [typingUserIds, setTypingUserIds] = React.useState<string[]>([]);

  const [voteA, setVoteA] = React.useState(0);
  const [voteB, setVoteB] = React.useState(0);
  const [hasVoted, setHasVoted] = React.useState(false);
  const [myVote, setMyVote] = React.useState<1 | 2 | null>(null);
  const [chatError, setChatError] = React.useState<string | null>(null);
  const [voteError, setVoteError] = React.useState<string | null>(null);
  const [recordingsCount, setRecordingsCount] = React.useState<number | null>(null);
  const [recordings, setRecordings] = React.useState<RecordingRow[]>([]);
  const [latestRecordingId, setLatestRecordingId] = React.useState<string | null>(null);
  const [recordingUploadError, setRecordingUploadError] = React.useState<string | null>(null);
  const [isUploadingRecording, setIsUploadingRecording] = React.useState(false);
  const [playbackError, setPlaybackError] = React.useState<string | null>(null);
  const [isPlayingPersisted, setIsPlayingPersisted] = React.useState(false);
  const [sessionRole, setSessionRole] = React.useState<SessionRole>("user");
  const [deleteError, setDeleteError] = React.useState<string | null>(null);
  const [deletingRecordingId, setDeletingRecordingId] = React.useState<string | null>(null);
  const lastRecordingsSnapshotRef = React.useRef<RecordingRow[] | null>(null);
  const realtimeChannelRef = React.useRef<RealtimeChannel | null>(null);
  const typingTimeoutRef = React.useRef<number | null>(null);

  const isSupabaseMode = sessionMode === "supabase";

  const reloadMessages = React.useCallback(async () => {
    if (!sessionId || !isSupabaseMode) return;
    const res = await fetch(`/api/battle-session/messages?battleId=${encodeURIComponent(sessionId)}`);
    const body = (await res.json()) as
      | { ok: true; mode: "supabase"; messages: ChatMessage[] }
      | { error: string; details?: string };
    if (res.ok && "ok" in body) {
      setMessages(body.messages);
      setChatError(null);
    } else {
      setChatError("Unable to load chat.");
    }
  }, [isSupabaseMode, sessionId]);

  const reloadVotes = React.useCallback(async () => {
    if (!sessionId || !isSupabaseMode) return;
    const res = await fetch(`/api/battle-session/votes?battleId=${encodeURIComponent(sessionId)}`);
    const body = (await res.json()) as
      | { ok: true; mode: "supabase"; counts: { 1: number; 2: number }; my_vote: 1 | 2 | null }
      | { error: string; details?: string };
    if (res.ok && "ok" in body) {
      setVoteA(body.counts[1]);
      setVoteB(body.counts[2]);
      setMyVote(body.my_vote);
      setHasVoted(Boolean(body.my_vote));
      setVoteError(null);
    } else {
      setVoteError("Unable to load votes.");
    }
  }, [isSupabaseMode, sessionId]);

  const reloadRecordings = React.useCallback(async () => {
    if (!sessionId || !isSupabaseMode) return;
    const res = await fetch(`/api/battle-session/recordings?battleId=${encodeURIComponent(sessionId)}`);
    const body = (await res.json()) as
      | { ok: true; mode: "supabase"; recordings: RecordingRow[] }
      | { error: string; details?: string };
    if (res.ok && "ok" in body) {
      setRecordings(body.recordings);
      const finalized = body.recordings.filter((r) => r.storage_bucket && r.storage_path && r.uploaded_at);
      setRecordingsCount(finalized.length);
      setLatestRecordingId(finalized.at(-1)?.id ?? null);
    }
  }, [isSupabaseMode, sessionId]);

  React.useEffect(() => {
    let cancelled = false;
    async function loadChatAndVotes() {
      if (!sessionId || !isSupabaseMode) return;

      try {
        const [messagesRes, votesRes] = await Promise.all([
          fetch(`/api/battle-session/messages?battleId=${encodeURIComponent(sessionId)}`),
          fetch(`/api/battle-session/votes?battleId=${encodeURIComponent(sessionId)}`),
        ]);

        const messagesBody = (await messagesRes.json()) as
          | { ok: true; mode: "supabase"; messages: ChatMessage[] }
          | { error: string; details?: string };
        const votesBody = (await votesRes.json()) as
          | { ok: true; mode: "supabase"; counts: { 1: number; 2: number }; my_vote: 1 | 2 | null }
          | { error: string; details?: string };

        if (cancelled) return;

        if (messagesRes.ok && "ok" in messagesBody) {
          setMessages(messagesBody.messages);
          setChatError(null);
        } else {
          setChatError("Unable to load chat.");
        }

        if (votesRes.ok && "ok" in votesBody) {
          setVoteA(votesBody.counts[1]);
          setVoteB(votesBody.counts[2]);
          setMyVote(votesBody.my_vote);
          setHasVoted(Boolean(votesBody.my_vote));
          setVoteError(null);
        } else {
          setVoteError("Unable to load votes.");
        }
      } catch {
        if (cancelled) return;
        setChatError("Unable to load chat.");
        setVoteError("Unable to load votes.");
      }
    }

    void loadChatAndVotes();
    return () => {
      cancelled = true;
    };
  }, [isSupabaseMode, sessionId]);

  React.useEffect(() => {
    if (!sessionId || !isSupabaseMode) return;
    void reloadRecordings();
  }, [isSupabaseMode, reloadRecordings, sessionId]);

  React.useEffect(() => {
    const role = sessionMeta?.viewer_role;
    if (role === "admin" || role === "mod" || role === "user") {
      setSessionRole(role);
    }
  }, [sessionMeta?.viewer_role]);

  React.useEffect(() => {
    if (!sessionId || !isSupabaseMode) return;

    let supabase: ReturnType<typeof createSupabaseBrowserClient> | null = null;
    try {
      supabase = createSupabaseBrowserClient();
    } catch {
      return;
    }

    const userId = sessionMeta?.viewer_user_id ?? null;
    const presenceKey = userId ?? crypto.randomUUID();

    const channel = supabase
      .channel(`battle_${sessionId}`, {
        config: {
          presence: {
            key: presenceKey,
          },
        },
      })
      .on("presence", { event: "sync" }, () => {
        const state = channel.presenceState();
        const count = Object.keys(state).length;
        setOnlineCount(count);
      })
      .on("broadcast", { event: "typing" }, (payload) => {
        const userId = (payload as { payload?: unknown } | null)?.payload;
        if (!userId || typeof userId !== "string") return;
        setTypingUserIds((prev) => {
          if (prev.includes(userId)) return prev;
          return [...prev, userId];
        });
        window.setTimeout(() => {
          setTypingUserIds((prev) => prev.filter((id) => id !== userId));
        }, 2500);
      })
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "battle_messages",
          filter: `battle_id=eq.${sessionId}`,
        },
        () => {
          void reloadMessages();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "battle_votes",
          filter: `battle_id=eq.${sessionId}`,
        },
        () => {
          void reloadVotes();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "battle_recordings",
          filter: `battle_id=eq.${sessionId}`,
        },
        () => {
          void reloadRecordings();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "battle_recordings",
          filter: `battle_id=eq.${sessionId}`,
        },
        () => {
          void reloadRecordings();
        },
      )
      .subscribe();

    realtimeChannelRef.current = channel;
    void channel.track({ user_id: userId ?? presenceKey });

    return () => {
      realtimeChannelRef.current = null;
      try {
        void supabase?.removeChannel(channel);
      } catch {
        // ignore
      }
    };
  }, [isSupabaseMode, reloadMessages, reloadRecordings, reloadVotes, sessionId, sessionMeta?.viewer_user_id]);

  React.useEffect(() => {
    if (!isSupabaseMode || !sessionId) return;
    const userId = sessionMeta?.viewer_user_id;
    if (!userId) return;

    if (typingTimeoutRef.current) window.clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = window.setTimeout(() => {
      const channel = realtimeChannelRef.current as
        | { send: (opts: { type: "broadcast"; event: string; payload: unknown }) => Promise<unknown> }
        | null;
      if (!channel) return;
      void channel.send({ type: "broadcast", event: "typing", payload: userId });
    }, 250);

    return () => {
      if (typingTimeoutRef.current) window.clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = null;
    };
  }, [chatDraft, isSupabaseMode, sessionId, sessionMeta?.viewer_user_id]);

  async function submitChat() {
    const body = chatDraft.trim();
    if (!body) return;

    if (!isSupabaseMode || !sessionId) {
      setMessages((prev) => [
        ...prev,
        { id: `m-${Date.now()}`, author: "You", body, ts: Date.now() },
      ]);
      setChatDraft("");
      return;
    }

    setChatError(null);
    try {
      const res = await fetch("/api/battle-session/messages", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ battleId: sessionId, body }),
      });

      if (!res.ok) {
        setChatError("Unable to send message.");
        return;
      }

      setChatDraft("");
      await reloadMessages();
    } catch {
      setChatError("Unable to send message.");
    }
  }

  async function submitVote(slot: 1 | 2) {
    if (!sessionId) return;
    if (!isSupabaseMode) {
      if (hasVoted) return;
      if (slot === 1) setVoteA((n) => n + 1);
      if (slot === 2) setVoteB((n) => n + 1);
      setHasVoted(true);
      return;
    }

    if (hasVoted) return;
    setVoteError(null);
    try {
      const res = await fetch("/api/battle-session/votes", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ battleId: sessionId, slot }),
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => null)) as unknown;
        const code =
          body && typeof body === "object" && body && "error" in body
            ? String((body as { error?: unknown }).error)
            : null;
        if (code === "voting_closed") {
          setVoteError("Voting is closed.");
          return;
        }
        setVoteError("Unable to submit vote.");
        return;
      }

      await reloadVotes();
    } catch {
      setVoteError("Unable to submit vote.");
    }
  }

  const lastRecordingMetaPostedRef = React.useRef<string | null>(null);
  React.useEffect(() => {
    let cancelled = false;

    async function cleanupRecording(recordingId: string) {
      try {
        await fetch("/api/battle-session/recordings/cleanup", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ recordingId }),
        });
      } catch {
        // best-effort
      }
    }

    async function uploadRecording() {
      if (!recordingBlob || !sessionId || !isSupabaseMode) return;
      const key = `${recordingBlob.size}:${recordingBlob.type}:${recordingSeconds}:${sessionId}`;
      if (lastRecordingMetaPostedRef.current === key) return;
      lastRecordingMetaPostedRef.current = key;

      setRecordingUploadError(null);
      setIsUploadingRecording(true);

      try {
        const initRes = await fetch("/api/battle-session/recordings/upload", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            battleId: sessionId,
            mimeType: recordingBlob.type || null,
            durationSeconds: recordingSeconds,
            bytes: recordingBlob.size,
          }),
        });

        const initBody = (await initRes.json()) as
          | {
              ok: true;
              mode: "supabase";
              recordingId: string;
              bucket: string;
              path: string;
              token: string;
              signedUrl: string;
            }
          | { error: string; details?: string };

        if (!initRes.ok || !("ok" in initBody)) {
          setRecordingUploadError("Unable to initialize upload.");
          return;
        }

        let supabase: ReturnType<typeof createSupabaseBrowserClient>;
        try {
          supabase = createSupabaseBrowserClient();
        } catch {
          await cleanupRecording(initBody.recordingId);
          setRecordingUploadError("Supabase is not configured.");
          return;
        }

        const { error: uploadError } = await supabase.storage
          .from(initBody.bucket)
          .uploadToSignedUrl(initBody.path, initBody.token, recordingBlob);

        if (uploadError) {
          await cleanupRecording(initBody.recordingId);
          setRecordingUploadError("Upload failed.");
          return;
        }

        const finalizeRes = await fetch("/api/battle-session/recordings/finalize", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ recordingId: initBody.recordingId }),
        });

        if (!finalizeRes.ok) {
          await cleanupRecording(initBody.recordingId);
          setRecordingUploadError("Upload failed.");
          return;
        }

        if (cancelled) return;
        setLatestRecordingId(initBody.recordingId);
        await reloadRecordings();
      } catch {
        setRecordingUploadError("Upload failed.");
      } finally {
        setIsUploadingRecording(false);
      }
    }

    void uploadRecording();
    return () => {
      cancelled = true;
    };
  }, [isSupabaseMode, recordingBlob, recordingSeconds, reloadRecordings, sessionId]);

  async function playPersisted(recordingId: string) {
    setPlaybackError(null);
    setIsPlayingPersisted(true);

    try {
      const res = await fetch(
        `/api/battle-session/recordings/download?recordingId=${encodeURIComponent(recordingId)}`,
      );
      const body = (await res.json()) as
        | { ok: true; mode: "supabase"; url: string }
        | { error: string; details?: string };

      if (!res.ok || !("ok" in body) || !body.url) {
        setPlaybackError("Unable to load playback URL.");
        return;
      }

      if (!audioRef.current) {
        setPlaybackError("Audio element not ready.");
        return;
      }

      audioRef.current.src = body.url;
      await audioRef.current.play();
    } catch {
      setPlaybackError("Playback failed.");
    } finally {
      setIsPlayingPersisted(false);
    }
  }

  async function playLatestPersisted() {
    if (!latestRecordingId) return;
    await playPersisted(latestRecordingId);
  }

  async function downloadPersisted(recordingId: string) {
    try {
      const res = await fetch(
        `/api/battle-session/recordings/download?recordingId=${encodeURIComponent(recordingId)}`,
      );
      const body = (await res.json()) as
        | { ok: true; mode: "supabase"; url: string }
        | { error: string; details?: string };
      if (!res.ok || !("ok" in body) || !body.url) {
        setPlaybackError("Unable to load download URL.");
        return;
      }

      window.open(body.url, "_blank", "noopener,noreferrer");
    } catch {
      setPlaybackError("Unable to download recording.");
    }
  }

  async function deletePersistedRecording(recordingId: string) {
    const confirmed = window.confirm("Delete this persisted recording? This cannot be undone.");
    if (!confirmed) return;

    setDeleteError(null);
    setDeletingRecordingId(recordingId);

    lastRecordingsSnapshotRef.current = recordings;
    setRecordings((prev) => prev.filter((r) => r.id !== recordingId));
    try {
      const res = await fetch("/api/battle-session/recordings/delete", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ recordingId }),
      });
      const body = (await res.json().catch(() => null)) as unknown;
      if (!res.ok) {
        if (lastRecordingsSnapshotRef.current) {
          setRecordings(lastRecordingsSnapshotRef.current);
          lastRecordingsSnapshotRef.current = null;
        }
        setDeleteError(
          body && typeof body === "object" && body && "error" in body
            ? `Delete failed: ${(body as { error?: unknown }).error as string}`
            : "Delete failed.",
        );
        return;
      }

      lastRecordingsSnapshotRef.current = null;
      await reloadRecordings();
    } catch {
      if (lastRecordingsSnapshotRef.current) {
        setRecordings(lastRecordingsSnapshotRef.current);
        lastRecordingsSnapshotRef.current = null;
      }
      setDeleteError("Delete failed.");
    } finally {
      setDeletingRecordingId(null);
    }
  }

  const canRecord = recordingState === "idle" || recordingState === "stopped";
  const canStop = recordingState === "recording";
  const canPlayRecording = recordingState === "stopped";
  const canStopPlayback = recordingState === "playing";

  async function enableMic() {
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setMicStatus("unsupported");
      setMicError("Mic capture is not supported in this browser.");
      return;
    }
    setMicError(null);
    setMicStatus("requesting");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      setMicStatus("granted");
    } catch (err) {
      const name = (err as { name?: string } | null)?.name;
      if (name === "NotAllowedError" || name === "PermissionDeniedError") {
        setMicStatus("denied");
        setMicError("Mic permission was denied.");
        return;
      }
      setMicStatus("error");
      setMicError("Unable to access microphone.");
    }
  }

  function startRecording() {
    if (!streamRef.current) {
      setMicError("Enable mic before recording.");
      return;
    }
    setMicError(null);

    if (recordingUrl) {
      URL.revokeObjectURL(recordingUrl);
      setRecordingUrl(null);
    }
    setRecordingBlob(null);
    chunksRef.current = [];

    const recorder = new MediaRecorder(streamRef.current);
    recorderRef.current = recorder;
    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) chunksRef.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
      setRecordingBlob(blob);
      const url = URL.createObjectURL(blob);
      setRecordingUrl(url);
      setRecordingState("stopped");
    };

    setRecordingSeconds(0);
    setRecordingState("recording");
    recorder.start(250);
  }

  function stopRecording() {
    const recorder = recorderRef.current;
    if (!recorder) return;
    if (recorder.state === "inactive") return;
    recorder.stop();
  }

  async function playRecording() {
    if (!recordingUrl || !audioRef.current) return;
    setRecordingState("playing");
    audioRef.current.src = recordingUrl;
    try {
      await audioRef.current.play();
    } catch {
      setMicError("Playback failed.");
      setRecordingState("stopped");
    }
  }

  function stopPlayback() {
    if (!audioRef.current) return;
    audioRef.current.pause();
    audioRef.current.currentTime = 0;
    setRecordingState(recordingBlob ? "stopped" : "idle");
  }

  return (
    <div data-testid="battle-room" className="space-y-6">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Battle Room</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Battle cockpit UI (production ready - real battles only).
          </p>
        </div>
        <div className="text-right text-xs text-muted-foreground">
          {isSupabaseMode ? (
            <>
              <div>Online: {onlineCount ?? "…"}</div>
              <div>
                Typing: {typingUserIds.length > 0 ? `${typingUserIds.length}` : "—"}
              </div>
            </>
          ) : (
            <div>Realtime: off</div>
          )}
        </div>
      </div>

      <Card className="border-border/60 bg-card/40 p-4 backdrop-blur">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Badge className={statusBadge.className}>{statusBadge.label}</Badge>
            <div className="text-xs text-muted-foreground">
              Round <span className="text-foreground">{round}</span>
            </div>
            <Separator orientation="vertical" className="mx-1 h-4" />
            <div className="text-xs text-muted-foreground">
              Latency <span className="text-foreground">{latencyMs ?? "--"}ms</span>
            </div>
            <Separator orientation="vertical" className="mx-1 h-4" />
            <div className="text-xs text-muted-foreground">
              Session{" "}
              <span className="font-mono text-foreground">
                {sessionId ? sessionId.slice(0, 8) : "--------"}
              </span>
            </div>

            <Separator orientation="vertical" className="mx-1 h-4" />
            <div className="text-xs text-muted-foreground">
              Status{" "}
              <span className="text-foreground">{sessionMeta?.status ?? "--"}</span>
            </div>
            <Separator orientation="vertical" className="mx-1 h-4" />
            <div className="text-xs text-muted-foreground">
              A{" "}
              <span className="font-mono text-foreground">{formatParticipantLabel(slotA)}</span>
            </div>
            <div className="text-xs text-muted-foreground">
              B{" "}
              <span className="font-mono text-foreground">{formatParticipantLabel(slotB)}</span>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="text-xs text-muted-foreground">Countdown</div>
            <div className="rounded-md border border-border/60 bg-background/40 px-3 py-1 font-mono text-sm">
              {formatMMSS(countdownSeconds)}
            </div>

            {sessionMeta?.can_manage ? (
              sessionMeta.status === "complete" || sessionMeta.status === "canceled" ? null : (
                <>
                  {sessionMeta.status !== "live" ? (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => updateBattleStatus("live")}
                      disabled={isUpdatingStatus}
                    >
                      {isUpdatingStatus ? "Updating…" : "Start"}
                    </Button>
                  ) : (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => void finalizeBattle()}
                      disabled={isFinalizing || votingClosed}
                    >
                      {isFinalizing ? "Finalizing…" : "Finalize"}
                    </Button>
                  )}
                </>
              )
            ) : null}

            {showJoinAsB ? (
              <Button size="sm" variant="secondary" onClick={joinAsB} disabled={isJoining}>
                {isJoining ? "Joining…" : "Join as B"}
              </Button>
            ) : null}

            {sessionId ? (
              <Button size="sm" variant="outline" onClick={leaveBattle}>
                Leave battle
              </Button>
            ) : (
              <Button size="sm" onClick={startNewBattle}>
                Start session
              </Button>
            )}
          </div>
        </div>
      </Card>

      {/* Video Battle UI */}
      {sessionId && sessionMeta?.viewer_user_id ? (
        <VideoBattleProduction
          battleId={sessionId}
          viewerUserId={sessionMeta.viewer_user_id}
          localSlot={slotA?.user_id === sessionMeta?.viewer_user_id ? 1 : 2}
          onStreamReady={(stream) => {
            // Optional: handle stream ready for recording/broadcast
            console.log("Local video stream ready:", stream);
          }}
        />
      ) : null}

      {sessionError ? (
        <div className="text-xs text-amber-200/90">{sessionError}</div>
      ) : null}

      {sessionMetaError ? (
        <div className="text-xs text-amber-200/90">{sessionMetaError}</div>
      ) : null}

      {joinError ? <div className="text-xs text-amber-200/90">{joinError}</div> : null}

      {statusError ? <div className="text-xs text-amber-200/90">{statusError}</div> : null}

      {finalizeError ? <div className="text-xs text-amber-200/90">{finalizeError}</div> : null}

      {sessionMeta?.status === "complete" && (sessionMeta.result || finalizeInfo?.result) ? (
        <Card className="border-border/60 bg-card/40 p-4 backdrop-blur">
          <div className="text-sm font-medium">Result</div>
          <div className="mt-2 grid gap-2 text-xs">
            <div>
              Winner:{" "}
              <span className="font-mono text-foreground">
                {winnerSlot === 1 ? "A" : winnerSlot === 2 ? "B" : "Tie"}
              </span>
            </div>
            <div>
              Votes:{" "}
              <span className="font-mono text-foreground">
                A={counts?.["1"] ?? 0} / B={counts?.["2"] ?? 0}
              </span>
            </div>
            {finalizeInfo ? (
              <div className="text-muted-foreground">Battle finalized</div>
            ) : null}
          </div>
        </Card>
      ) : null}

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="space-y-4">
          <Card
            data-testid="beat-slot"
            className="border-border/60 bg-card/40 p-5 backdrop-blur"
          >
            <div className="flex items-center justify-between gap-4">
              <div>
                <div className="text-sm font-medium">Beat</div>
                <div className="mt-1 text-xs text-muted-foreground">
                  {currentBeat
                    ? `${currentBeat.title} · ${currentBeat.bpm} BPM · ${currentBeat.lengthSeconds}s`
                    : "No beat library available"}
                </div>
              </div>
              <Badge variant="secondary">slot</Badge>
            </div>

            <Separator className="my-4" />

            <div className="flex flex-wrap items-center gap-2">
              <Button variant="outline" onClick={() => setBeatModalOpen(true)}>
                Choose Beat
              </Button>
              <Button
                onClick={() => setBeatPlaying((p) => !p)}
                disabled={!currentBeat}
              >
                {beatPlaying ? "Pause" : "Play"}
              </Button>
              <div className="ml-auto text-xs text-muted-foreground">
                {currentBeat ? (beatPlaying ? "Playing" : "Idle") : "No beat available"}
              </div>
            </div>
          </Card>

          <Card
            data-testid="recording-slot"
            className="border-border/60 bg-card/40 p-5 backdrop-blur"
          >
            <div className="flex items-center justify-between gap-4">
              <div>
                <div className="text-sm font-medium">Recording</div>
                <div className="mt-1 text-xs text-muted-foreground">
                  Status: <span className="text-foreground">{recordingState}</span> · Duration:{" "}
                  <span className="font-mono text-foreground">
                    {formatMMSS(recordingSeconds)}
                  </span>
                  {isSupabaseMode ? (
                    <>
                      {" "}· Persisted{" "}
                      <span className="font-mono text-foreground">
                        {recordingsCount ?? "--"}
                      </span>
                    </>
                  ) : null}
                </div>
              </div>
              <Badge variant="secondary">slot</Badge>
            </div>

            <Separator className="my-4" />

            <div className="grid gap-3">
              <div className="h-14 rounded-lg border border-border/60 bg-background/30">
                <div className="h-full w-full rounded-lg bg-gradient-to-r from-cyan-500/10 via-fuchsia-500/10 to-emerald-500/10" />
              </div>

              <audio
                ref={audioRef}
                className="hidden"
                onEnded={() => setRecordingState(recordingBlob ? "stopped" : "idle")}
              />

              <div className="flex flex-wrap items-center gap-2">
                {isClient && micStatus !== "granted" ? (
                  <Button
                    variant="outline"
                    onClick={enableMic}
                    disabled={micStatus === "requesting" || micStatus === "unsupported"}
                  >
                    {micStatus === "requesting" ? "Requesting…" : "Enable Mic"}
                  </Button>
                ) : isClient && micStatus === "granted" ? (
                  <Badge className="bg-cyan-500/15 text-cyan-200">Mic ready</Badge>
                ) : (
                  <Button variant="outline" disabled>
                    Loading...
                  </Button>
                )}

                <Button
                  onClick={startRecording}
                  disabled={!canRecord || micStatus !== "granted"}
                >
                  Record
                </Button>
                <Button
                  variant="outline"
                  onClick={stopRecording}
                  disabled={!canStop}
                >
                  Stop
                </Button>
                <Button
                  variant="secondary"
                  onClick={playRecording}
                  disabled={!canPlayRecording || !recordingUrl}
                >
                  Play
                </Button>

                {isSupabaseMode ? (
                  <Button
                    variant="outline"
                    onClick={() => void playLatestPersisted()}
                    disabled={!latestRecordingId || isPlayingPersisted}
                  >
                    {isPlayingPersisted ? "Loading…" : "Play Persisted"}
                  </Button>
                ) : null}
                <Button
                  variant="outline"
                  onClick={stopPlayback}
                  disabled={!canStopPlayback}
                >
                  Stop Playback
                </Button>

                <div className="ml-auto text-xs text-muted-foreground">
                  {isClient && (
                    <>
                      {isSupabaseMode && isUploadingRecording
                        ? "Uploading…"
                        : micStatus === "unsupported"
                          ? "Unsupported"
                          : "MediaRecorder"}
                    </>
                  )}
                  {!isClient && "Loading..."}
                </div>
              </div>

              {isClient && micStatus === "denied" ? (
                <div className="text-xs text-amber-200/90">
                  Mic permission denied. Update site permissions and try again.
                </div>
              ) : null}
              {isClient && micError ? (
                <div className="text-xs text-amber-200/90">{micError}</div>
              ) : null}

              {recordingUploadError ? (
                <div className="text-xs text-amber-200/90">{recordingUploadError}</div>
              ) : null}

              {playbackError ? (
                <div className="text-xs text-amber-200/90">{playbackError}</div>
              ) : null}

              {deleteError ? (
                <div className="text-xs text-amber-200/90">{deleteError}</div>
              ) : null}

              {isSupabaseMode ? (
                <div className="rounded-lg border border-border/60 bg-background/25 p-3">
                  <div className="text-xs text-muted-foreground">Persisted recordings</div>
                  <div className="mt-2 grid gap-2">
                    {recordings
                      .filter((r) => r.storage_bucket && r.storage_path && r.uploaded_at)
                      .slice()
                      .reverse()
                      .map((r, idx) => (
                        <div key={r.id} className="flex items-center gap-2">
                          <div className="min-w-0 flex-1 text-xs text-muted-foreground">
                            <span className="font-mono text-foreground">#{idx + 1}</span>
                            {r.created_at ? (
                              <span className="ml-2">{new Date(r.created_at).toLocaleString()}</span>
                            ) : null}

                            <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1">
                              {typeof r.duration_seconds === "number" ? (
                                <span>{formatMMSS(r.duration_seconds)}</span>
                              ) : null}
                              {typeof r.bytes === "number" ? (
                                <span>{(r.bytes / 1024).toFixed(1)} KB</span>
                              ) : null}
                              {r.mime_type ? <span>{r.mime_type}</span> : null}
                            </div>
                          </div>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => void playPersisted(r.id)}
                            disabled={isPlayingPersisted || Boolean(deletingRecordingId)}
                          >
                            Play
                          </Button>

                          <Button
                            size="sm"
                            variant="secondary"
                            onClick={() => void downloadPersisted(r.id)}
                            disabled={Boolean(deletingRecordingId)}
                          >
                            Download
                          </Button>

                          {sessionRole === "admin" || sessionRole === "mod" ? (
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={() => void deletePersistedRecording(r.id)}
                              disabled={deletingRecordingId === r.id || isPlayingPersisted}
                            >
                              {deletingRecordingId === r.id ? "Deleting…" : "Delete"}
                            </Button>
                          ) : null}
                        </div>
                      ))}
                    {recordings.filter((r) => r.storage_bucket && r.storage_path && r.uploaded_at)
                      .length === 0 ? (
                      <div className="text-xs text-muted-foreground">No persisted recordings yet.</div>
                    ) : null}
                  </div>
                </div>
              ) : null}
            </div>
          </Card>
        </div>

        <div className="space-y-4">
          <Card
            data-testid="chat-slot"
            className="border-border/60 bg-card/40 p-5 backdrop-blur"
          >
            <div className="flex items-center justify-between gap-4">
              <div>
                <div className="text-sm font-medium">Chat</div>
                <div className="mt-1 text-xs text-muted-foreground">
                  {isSupabaseMode ? "Session messages" : "No chat available"}
                </div>
              </div>
              <Badge variant="secondary">slot</Badge>
            </div>

            <Separator className="my-4" />

            <div className="grid gap-3">
              <div className="max-h-56 overflow-auto rounded-lg border border-border/60 bg-background/25 p-3">
                <div className="space-y-2">
                  {messages.map((m) => (
                    <div key={m.id} className="text-sm">
                      <span className="text-xs text-muted-foreground">{m.author}</span>
                      <span className="text-muted-foreground">: </span>
                      <span className="text-foreground">{m.body}</span>
                    </div>
                  ))}
                </div>
              </div>

              {chatError ? <div className="text-xs text-amber-200/90">{chatError}</div> : null}

              <div className="flex items-end gap-2">
                <Textarea
                  value={chatDraft}
                  onChange={(e) => setChatDraft(e.target.value)}
                  placeholder="Say something…"
                  className="min-h-[44px]"
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && !e.shiftKey) {
                      e.preventDefault();
                      submitChat();
                    }
                  }}
                />
                <Button onClick={submitChat} disabled={!chatDraft.trim()}>
                  Send
                </Button>
              </div>
            </div>
          </Card>

          <Card
            data-testid="vote-slot"
            className="border-border/60 bg-card/40 p-5 backdrop-blur"
          >
            {(() => {
              const remainingSeconds = votingRemainingSeconds;

              return (
                <>
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <div className="text-sm font-medium">Judge / Vote</div>
                      <div className="mt-1 text-xs text-muted-foreground">
                        {isSupabaseMode ? "Session vote totals" : "Local vote counts (anti-double-vote lock)"}
                      </div>
                      {isSupabaseMode ? (
                        <div className="mt-1 text-xs text-muted-foreground">
                          Voting {votingClosed ? "closed" : "open"}
                          {remainingSeconds !== null && !votingClosed
                            ? ` · closes in ${remainingSeconds}s`
                            : ""}
                        </div>
                      ) : null}
                    </div>
                    <Badge variant="secondary">live</Badge>
                  </div>

                  <Separator className="my-4" />

                  <div className="grid gap-3">
                    <div className="grid grid-cols-2 gap-2">
                      <Button
                        onClick={() => {
                          void submitVote(1);
                        }}
                        disabled={hasVoted || votingClosed}
                      >
                        Vote A
                        <span className="ml-2 rounded-md border border-border/60 bg-background/40 px-2 py-0.5 text-xs">
                          {voteA}
                        </span>
                      </Button>
                      <Button
                        variant="secondary"
                        onClick={() => {
                          void submitVote(2);
                        }}
                        disabled={hasVoted || votingClosed}
                      >
                        Vote B
                        <span className="ml-2 rounded-md border border-border/60 bg-background/40 px-2 py-0.5 text-xs">
                          {voteB}
                        </span>
                      </Button>
                    </div>

                    {voteError ? <div className="text-xs text-amber-200/90">{voteError}</div> : null}

                    {votingClosed ? (
                      <div className="text-xs text-muted-foreground">Voting is closed for this round.</div>
                    ) : null}

                    <div className="flex items-center justify-between gap-2">
                      <div className="text-xs text-muted-foreground">
                        {hasVoted
                          ? `Vote submitted${myVote ? ` (you voted ${myVote === 1 ? "A" : "B"})` : ""}`
                          : votingClosed
                            ? "Voting is closed"
                            : "You can vote once"}
                      </div>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => {
                          if (isSupabaseMode) return;
                          setHasVoted(false);
                        }}
                        disabled={isSupabaseMode}
                      >
                        Reset (dev)
                      </Button>
                    </div>
                  </div>
                </>
              );
            })()}
          </Card>
        </div>
      </div>

      <Dialog open={beatModalOpen} onOpenChange={setBeatModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Choose a beat</DialogTitle>
            <DialogDescription>
              Beat library integration needed - no beats available yet.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-2">
            <div className="p-4 rounded-lg border border-border/60 bg-background/30">
              <p className="text-muted-foreground text-sm">
                No beats available. Beat library integration is required for production.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Input value={"Search disabled"} readOnly />
            <Button variant="outline" onClick={() => setBeatModalOpen(false)}>
              Close
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Search, Play, Pause, Volume2, Music, Clock, TrendingUp, Filter, Upload } from 'lucide-react';
import { toast } from 'sonner';
import { BeatUploadModal } from '@/components/audio/BeatUploadModal';

interface Beat {
  id: string;
  title: string;
  artist: string;
  tempo: number;
  key_signature: string;
  genre: string;
  duration_seconds: number;
  preview_url: string;
  usage_count: number;
  created_at: string;
}

interface BeatLibraryProps {
  onBeatSelect: (beat: Beat) => void;
  selectedBeatId?: string;
  canUpload?: boolean;
}

export function BeatLibrary({ onBeatSelect, selectedBeatId, canUpload = false }: BeatLibraryProps) {
  const [beats, setBeats] = useState<Beat[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('all');
  const [tempoRange, setTempoRange] = useState([60, 180]);
  const [playingBeatId, setPlayingBeatId] = useState<string | null>(null);
  const [uploadOpen, setUploadOpen] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const genres = [
    'all', 'hip-hop', 'trap', 'boom-bap', 'lo-fi', 'drill', 'r&b', 'pop', 'electronic', 'rock', 'afrobeat',
  ];

  useEffect(() => { fetchBeats(); }, [selectedGenre, tempoRange]);

  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.src = '';
      }
    };
  }, []);

  const fetchBeats = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (selectedGenre !== 'all') params.append('genre', selectedGenre);
      params.append('tempo_min', tempoRange[0].toString());
      params.append('tempo_max', tempoRange[1].toString());
      params.append('limit', '50');
      const response = await fetch(`/api/beats?${params.toString()}`);
      if (!response.ok) throw new Error('Failed to fetch beats');
      const data = await response.json();
      setBeats(data.beats || []);
    } catch (error) {
      console.error('Error fetching beats:', error);
      toast.error('Failed to load beats');
    } finally {
      setLoading(false);
    }
  };

  const handlePlayPreview = async (beat: Beat) => {
    try {
      if (playingBeatId === beat.id && audioRef.current) {
        audioRef.current.pause();
        setPlayingBeatId(null);
        return;
      }
      if (audioRef.current) audioRef.current.pause();
      if (!beat.preview_url) { toast.error('No preview available'); return; }
      const audio = new Audio();
      audio.src = beat.preview_url;
      audioRef.current = audio;
      audio.onplay = () => setPlayingBeatId(beat.id);
      audio.onpause = () => setPlayingBeatId(null);
      audio.onended = () => setPlayingBeatId(null);
      audio.onerror = () => { toast.error('Failed to play preview'); setPlayingBeatId(null); };
      await audio.play();
    } catch {
      toast.error('Failed to play preview');
    }
  };

  const handleBeatSelect = (beat: Beat) => {
    onBeatSelect(beat);
    toast.success(`Selected: ${beat.title} by ${beat.artist}`);
  };

  const filteredBeats = beats.filter(beat =>
    beat.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    beat.artist.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const formatDuration = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getGenreColor = (genre: string) => {
    const colors: Record<string, string> = {
      'hip-hop': 'bg-purple-500', 'trap': 'bg-red-500', 'boom-bap': 'bg-blue-500',
      'lo-fi': 'bg-green-500', 'drill': 'bg-orange-500', 'r&b': 'bg-pink-500',
      'pop': 'bg-yellow-500', 'electronic': 'bg-cyan-500', 'rock': 'bg-gray-500',
      'afrobeat': 'bg-lime-500',
    };
    return colors[genre] || 'bg-gray-500';
  };

  return (
    <div className="space-y-6">
      {/* Filters */}
      <Card className="border-border/60 bg-card/30 p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search beats..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Select value={selectedGenre} onValueChange={setSelectedGenre}>
            <SelectTrigger><SelectValue placeholder="Genre" /></SelectTrigger>
            <SelectContent>
              {genres.map(genre => (
                <SelectItem key={genre} value={genre}>
                  {genre === 'all' ? 'All Genres' : genre.charAt(0).toUpperCase() + genre.slice(1)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <div className="col-span-2">
            <div className="flex items-center gap-2 mb-2 text-sm text-muted-foreground">
              <Filter className="h-4 w-4" />
              Tempo: {tempoRange[0]}–{tempoRange[1]} BPM
            </div>
            <Slider value={tempoRange} onValueChange={setTempoRange} min={60} max={200} step={5} />
          </div>
        </div>
      </Card>

      {/* Beat Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading ? (
          Array.from({ length: 9 }).map((_, i) => (
            <div key={`sk-${i}`} className="h-48 animate-pulse rounded-lg bg-muted/30" />
          ))
        ) : filteredBeats.length === 0 ? (
          <div className="col-span-full py-12 text-center">
            <Music className="mx-auto h-12 w-12 text-muted-foreground/30" />
            <p className="mt-3 text-sm font-medium">No beats found</p>
            <p className="mt-1 text-xs text-muted-foreground">Try adjusting your filters</p>
          </div>
        ) : (
          filteredBeats.map(beat => (
            <Card
              key={beat.id}
              className={`cursor-pointer border-border/60 bg-card/30 transition-all hover:bg-card/60 hover:shadow-md ${
                selectedBeatId === beat.id ? 'ring-2 ring-primary' : ''
              }`}
            >
              <CardContent className="p-5 space-y-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0 flex-1">
                    <p className="font-semibold truncate">{beat.title}</p>
                    <p className="text-sm text-muted-foreground truncate">{beat.artist}</p>
                  </div>
                  <Badge className={`${getGenreColor(beat.genre)} text-white text-[10px] shrink-0`}>
                    {beat.genre}
                  </Badge>
                </div>
                <div className="grid grid-cols-2 gap-2 text-xs text-muted-foreground">
                  <div className="flex items-center gap-1.5"><Clock className="h-3.5 w-3.5" />{formatDuration(beat.duration_seconds)}</div>
                  <div className="flex items-center gap-1.5"><TrendingUp className="h-3.5 w-3.5" />{beat.tempo} BPM</div>
                  <div className="flex items-center gap-1.5"><Music className="h-3.5 w-3.5" />{beat.key_signature}</div>
                  <div className="flex items-center gap-1.5"><Volume2 className="h-3.5 w-3.5" />{beat.usage_count} uses</div>
                </div>
                <div className="flex gap-2">
                  <Button size="sm" variant="outline" className="flex-1 gap-1.5" onClick={() => handlePlayPreview(beat)}>
                    {playingBeatId === beat.id ? <><Pause className="h-3.5 w-3.5" />Stop</> : <><Play className="h-3.5 w-3.5" />Preview</>}
                  </Button>
                  <Button
                    size="sm"
                    className="flex-1"
                    variant={selectedBeatId === beat.id ? 'secondary' : 'default'}
                    onClick={() => handleBeatSelect(beat)}
                    disabled={selectedBeatId === beat.id}
                  >
                    {selectedBeatId === beat.id ? 'Selected' : 'Select'}
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {/* Upload FAB — admins/mods only */}
      {canUpload && (
        <div className="fixed bottom-8 right-8 z-30">
          <Button
            size="lg"
            className="h-14 w-14 rounded-full p-0 shadow-lg"
            onClick={() => setUploadOpen(true)}
            title="Upload beat"
          >
            <Upload className="h-5 w-5" />
          </Button>
        </div>
      )}

      <BeatUploadModal
        open={uploadOpen}
        onClose={() => setUploadOpen(false)}
        onUploaded={fetchBeats}
      />
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Badge } from '@/components/ui/badge';
import { Music, Clock, Trophy, Users, Zap, ArrowLeft } from 'lucide-react';
import { toast } from 'sonner';

interface CreateBattleProps {
  onBack: () => void;
  onBattleCreated: (battle: any) => void;
  selectedBeat?: any;
}

interface BattleConfig {
  battle_type: 'ranked' | 'casual' | 'tournament';
  format: '30s' | '60s' | '90s';
  entry_fee_tokens: number;
  max_participants: number;
  beat_preferences: {
    genre?: string;
    tempo_range: [number, number];
  };
}

export function CreateBattle({ onBack, onBattleCreated, selectedBeat }: CreateBattleProps) {
  const [config, setConfig] = useState<BattleConfig>({
    battle_type: 'casual',
    format: '30s',
    entry_fee_tokens: 0,
    max_participants: 2,
    beat_preferences: {
      genre: 'all',
      tempo_range: [80, 120]
    }
  });

  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);

  const genres = [
    'all', 'hip-hop', 'trap', 'boom-bap', 'lo-fi', 'drill', 'r&b', 'pop', 'electronic', 'rock'
  ];

  const handleCreateBattle = async () => {
    try {
      setLoading(true);

      const response = await fetch('/api/battles', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        },
        body: JSON.stringify(config)
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error?.message || 'Failed to create battle');
      }

      const battle = await response.json();
      toast.success('Battle created successfully!');
      onBattleCreated(battle);
    } catch (error) {
      console.error('Error creating battle:', error);
      toast.error(error instanceof Error ? error.message : 'Failed to create battle');
    } finally {
      setLoading(false);
    }
  };

  const updateConfig = (key: keyof BattleConfig, value: any) => {
    setConfig(prev => ({ ...prev, [key]: value }));
  };

  const updateBeatPreferences = (key: string, value: any) => {
    setConfig(prev => ({
      ...prev,
      beat_preferences: {
        ...prev.beat_preferences,
        [key]: value
      }
    }));
  };

  const nextStep = () => {
    if (step < 3) setStep(step + 1);
  };

  const prevStep = () => {
    if (step > 1) setStep(step - 1);
  };

  const getBattleTypeColor = (type: string) => {
    switch (type) {
      case 'ranked': return 'bg-red-500';
      case 'casual': return 'bg-green-500';
      case 'tournament': return 'bg-purple-500';
      default: return 'bg-gray-500';
    }
  };

  const getFormatColor = (format: string) => {
    switch (format) {
      case '30s': return 'bg-blue-500';
      case '60s': return 'bg-orange-500';
      case '90s': return 'bg-pink-500';
      default: return 'bg-gray-500';
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 text-white p-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <Button variant="ghost" onClick={onBack} className="text-white">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
          <h1 className="text-3xl font-bold">Create Battle</h1>
          <div className="flex items-center space-x-2">
            <div className={`w-3 h-3 rounded-full ${step >= 1 ? 'bg-green-500' : 'bg-gray-600'}`} />
            <div className={`w-3 h-3 rounded-full ${step >= 2 ? 'bg-green-500' : 'bg-gray-600'}`} />
            <div className={`w-3 h-3 rounded-full ${step >= 3 ? 'bg-green-500' : 'bg-gray-600'}`} />
          </div>
        </div>

        {/* Step 1: Battle Type */}
        {step === 1 && (
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -50 }}
          >
            <Card className="bg-black/20 border-white/10">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <Trophy className="w-5 h-5" />
                  <span>Battle Type</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {[
                    { type: 'ranked', title: 'Ranked Battle', description: 'Competitive rating system', icon: '🏆' },
                    { type: 'casual', title: 'Casual Battle', description: 'Fun and practice', icon: '🎮' },
                    { type: 'tournament', title: 'Tournament', description: 'Official competition', icon: '🏅' }
                  ].map((option) => (
                    <div
                      key={option.type}
                      onClick={() => updateConfig('battle_type', option.type)}
                      className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${
                        config.battle_type === option.type
                          ? 'border-purple-500 bg-purple-500/20'
                          : 'border-white/20 hover:border-white/40'
                      }`}
                    >
                      <div className="text-2xl mb-2">{option.icon}</div>
                      <h3 className="font-semibold mb-1">{option.title}</h3>
                      <p className="text-sm text-gray-400">{option.description}</p>
                    </div>
                  ))}
                </div>

                <div className="flex justify-between">
                  <Button variant="outline" onClick={onBack}>
                    Cancel
                  </Button>
                  <Button onClick={nextStep}>
                    Next Step
                  </Button>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}

        {/* Step 2: Battle Format */}
        {step === 2 && (
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -50 }}
          >
            <Card className="bg-black/20 border-white/10">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <Clock className="w-5 h-5" />
                  <span>Battle Format</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                <div>
                  <Label className="text-lg font-semibold mb-4 block">Round Duration</Label>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {[
                      { format: '30s', title: '30 Seconds', description: 'Quick rounds', duration: 30 },
                      { format: '60s', title: '60 Seconds', description: 'Standard rounds', duration: 60 },
                      { format: '90s', title: '90 Seconds', description: 'Extended rounds', duration: 90 }
                    ].map((option) => (
                      <div
                        key={option.format}
                        onClick={() => updateConfig('format', option.format)}
                        className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${
