"use client";

import React, { useState, useEffect, useRef } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { BattleWebSocketClient, ChatMessage } from '@/lib/websocket/client';

interface BattleChatProps {
  roomId: string;
  userId: string;
  username: string;
  isModerator?: boolean;
}

export function BattleChat({ roomId, userId, username, isModerator = false }: BattleChatProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isConnected, setIsConnected] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'connected' | 'disconnected' | 'connecting' | 'reconnecting'>('disconnected');
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [onlineUsers, setOnlineUsers] = useState<{ id: string; username: string }[]>([]);

  const wsClientRef = useRef<BattleWebSocketClient | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Initialize WebSocket client
    const wsClient = new BattleWebSocketClient();
    wsClientRef.current = wsClient;

    // Set up callbacks
    wsClient.setCallbacks({
      onMessage: (message) => {
        setMessages(prev => [...prev, message]);
        scrollToBottom();
      },
      onStatusChange: (status) => {
        setConnectionStatus(status);
        setIsConnected(status === 'connected');
      },
      onTyping: (users) => {
        setTypingUsers(users);
      },
      onUserJoined: (user) => {
        setOnlineUsers(prev => [...prev, user]);
        setMessages(prev => [...prev, {
          id: `system-${Date.now()}`,
          userId: 'system',
          username: 'System',
          message: `${user.username} joined the battle`,
          timestamp: Date.now(),
          type: 'system'
        }]);
      },
      onUserLeft: (leftUserId) => {
        setOnlineUsers(prev => prev.filter(u => u.id !== leftUserId));
        const leftUser = onlineUsers.find(u => u.id === leftUserId);
        if (leftUser) {
          setMessages(prev => [...prev, {
            id: `system-${Date.now()}`,
            userId: 'system',
            username: 'System',
            message: `${leftUser.username} left the battle`,
            timestamp: Date.now(),
            type: 'system'
          }]);
        }
      }
    });

    // Connect to WebSocket
    wsClient.connect({
      url: process.env.NEXT_PUBLIC_WEBSOCKET_URL || 'ws://localhost:8080',
      roomId,
      userId,
      token: isModerator ? 'moderator-token' : undefined
    });

    return () => {
      wsClient.disconnect();
    };
  }, [roomId, userId, isModerator]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = () => {
    if (!newMessage.trim() || !isConnected) return;

    const client = wsClientRef.current;
    if (client) {
      client.sendMessage(newMessage.trim());
      setNewMessage('');
      inputRef.current?.focus();
    }
  };

  const handleTyping = () => {
    const client = wsClientRef.current;
    if (client) {
      client.sendTyping(true);

      // Clear existing timeout
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }

      // Set new timeout to stop typing indicator
      typingTimeoutRef.current = setTimeout(() => {
        client.sendTyping(false);
      }, 1000);
    }
  };

  const handleFlagMessage = (messageId: string) => {
    const client = wsClientRef.current;
    if (client) {
      client.flagMessage(messageId, 'Inappropriate content');
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const formatTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getStatusColor = () => {
    switch (connectionStatus) {
      case 'connected': return 'bg-green-500';
      case 'connecting': return 'bg-yellow-500';
      case 'reconnecting': return 'bg-orange-500';
      case 'disconnected': return 'bg-red-500';
    }
  };

  const getStatusText = () => {
    switch (connectionStatus) {
      case 'connected': return 'Connected';
      case 'connecting': return 'Connecting...';
      case 'reconnecting': return 'Reconnecting...';
      case 'disconnected': return 'Disconnected';
    }
  };

  return (
    <Card className="flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold">Battle Chat</h3>
            <div className="flex items-center gap-2 mt-1">
              <div className={`w-2 h-2 rounded-full ${getStatusColor()}`} />
              <span className="text-sm text-gray-600">{getStatusText()}</span>
              <Badge variant="secondary">{onlineUsers.length + 1} online</Badge>
            </div>
          </div>
          {isModerator && (
            <Badge variant="default" className="bg-purple-500">Moderator</Badge>
          )}
        </div>
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-4">
        <div className="space-y-3">
          {messages.map((message) => (
            <div
              key={message.id}
              className={`flex flex-col ${
                message.userId === userId ? 'items-end' : 'items-start'
              }`}
            >
              <div
                className={`max-w-[80%] rounded-lg p-3 ${
                  message.type === 'system'
                    ? 'bg-gray-100 text-gray-600 text-sm'
                    : message.userId === userId
                    ? 'bg-blue-500 text-white'
                    : 'bg-gray-200'
                }`}
              >
                {message.type !== 'system' && (
                  <div className="font-medium text-sm mb-1">
                    {message.username}
                  </div>
                )}
                <div className="break-words">{message.message}</div>
                <div className={`text-xs mt-1 ${
                  message.type === 'system' ? 'text-gray-500' :
                  message.userId === userId ? 'text-blue-100' : 'text-gray-500'
                }`}>
                  {formatTime(message.timestamp)}
                </div>
              </div>

              {/* Moderator actions */}
              {isModerator && message.type === 'message' && message.userId !== userId && (
                <div className="flex gap-2 mt-1">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleFlagMessage(message.id)}
                    className="text-xs"
                  >
                    Flag
                  </Button>
                </div>
              )}
            </div>
          ))}

          {/* Typing indicator */}
          {typingUsers.length > 0 && (
            <div className="text-sm text-gray-500 italic">
              {typingUsers.join(', ')} {typingUsers.length === 1 ? 'is' : 'are'} typing...
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </ScrollArea>

      {/* Input */}
      <div className="p-4 border-t">
        <div className="flex gap-2">
          <Input
            ref={inputRef}
            value={newMessage}
            onChange={(e) => {
              setNewMessage(e.target.value);
              handleTyping();
            }}
            onKeyPress={handleKeyPress}
            placeholder={isConnected ? "Type a message..." : "Connecting..."}
            disabled={!isConnected}
            maxLength={500}
          />
          <Button
            onClick={handleSendMessage}
            disabled={!isConnected || !newMessage.trim()}
          >
            Send
          </Button>
        </div>

        {/* Character count */}
        <div className="text-xs text-gray-500 mt-1">
          {newMessage.length}/500 characters
        </div>
      </div>
    </Card>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { formatDistanceToNow } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Trophy, Swords, Star, Users, Zap, TrendingUp } from "lucide-react";

type FeedActor = {
  id: string;
  handle: string;
  display_name: string | null;
  avatar_url: string | null;
  tier: string;
  is_verified: boolean;
  elo_rating: number;
};

type FeedItem = {
  id: string;
  type: string;
  subject_id: string | null;
  subject_type: string | null;
  meta: Record<string, unknown>;
  created_at: string;
  actor: FeedActor;
};

const FEED_ICONS: Record<string, React.ReactNode> = {
  battle_win: <Trophy className="h-4 w-4 text-yellow-400" />,
  battle_complete: <Swords className="h-4 w-4 text-blue-400" />,
  achievement_earned: <Star className="h-4 w-4 text-purple-400" />,
  joined_tournament: <Users className="h-4 w-4 text-green-400" />,
  challenge_issued: <Zap className="h-4 w-4 text-orange-400" />,
  rank_up: <TrendingUp className="h-4 w-4 text-pink-400" />,
  first_battle: <Swords className="h-4 w-4 text-cyan-400" />,
};

function feedLabel(item: FeedItem): string {
  const handle = item.actor.handle;
  switch (item.type) {
    case "battle_win":
      return `${handle} won a battle`;
    case "battle_complete":
      return `${handle} completed a battle`;
    case "achievement_earned":
      return `${handle} earned "${item.meta.label ?? "an achievement"}"`;
    case "joined_tournament":
      return `${handle} joined ${item.meta.tournament_name ?? "a tournament"}`;
    case "challenge_issued":
      return `${handle} issued a challenge`;
    case "rank_up":
      return `${handle} ranked up to ${item.meta.tier ?? "a new tier"}`;
    case "first_battle":
      return `${handle} fought their first battle`;
    default:
      return `${handle} did something`;
  }
}

function TierBadge({ tier }: { tier: string }) {
  const colors: Record<string, string> = {
    bronze: "bg-amber-800/30 text-amber-400 border-amber-600/40",
    silver: "bg-slate-400/20 text-slate-300 border-slate-400/40",
    gold: "bg-yellow-400/20 text-yellow-300 border-yellow-400/40",
    platinum: "bg-cyan-400/20 text-cyan-300 border-cyan-400/40",
    diamond: "bg-blue-400/20 text-blue-300 border-blue-500/40",
    legend: "bg-purple-400/20 text-purple-300 border-purple-500/40",
  };
  return (
    <span className={`rounded border px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide ${colors[tier] ?? colors.bronze}`}>
      {tier}
    </span>
  );
}

function FeedCard({ item }: { item: FeedItem }) {
  const icon = FEED_ICONS[item.type] ?? <Swords className="h-4 w-4 text-muted-foreground" />;

  return (
    <div className="flex items-start gap-3 rounded-lg border border-border/50 bg-card/30 px-4 py-3 backdrop-blur transition-colors hover:bg-card/50">
      <div className="mt-0.5 shrink-0 rounded-full border border-border/60 bg-background/40 p-2">
        {icon}
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <Link href={`/app/players/${item.actor.id}`} className="font-medium hover:underline">
            {item.actor.display_name ?? item.actor.handle}
          </Link>
          <TierBadge tier={item.actor.tier} />
          {item.actor.is_verified && (
            <span className="text-blue-400" title="Verified">✓</span>
          )}
        </div>
        <p className="mt-0.5 text-sm text-muted-foreground">{feedLabel(item)}</p>
        <p className="mt-1 text-xs text-muted-foreground/60">
          {formatDistanceToNow(item.created_at)}
        </p>
      </div>
      {item.subject_type === "battle" && item.subject_id && (
        <Button asChild size="sm" variant="outline" className="shrink-0 self-center">
          <Link href={`/app/battles/room?battleId=${item.subject_id}`}>Watch</Link>
        </Button>
      )}
    </div>
  );
}

export function CommunityFeed() {
  const [items, setItems] = React.useState<FeedItem[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [filter, setFilter] = React.useState<"global" | "following">("global");
  const [hasMore, setHasMore] = React.useState(true);
  const [offset, setOffset] = React.useState(0);

  const fetchFeed = React.useCallback(async (filterVal: string, offsetVal: number, append = false) => {
    setLoading(true);
    try {
      const res = await fetch(`/api/community/feed?filter=${filterVal}&offset=${offsetVal}&limit=20`);
      if (!res.ok) throw new Error("Failed to load feed");
      const json = await res.json();
      const newItems: FeedItem[] = json.items ?? [];
      setItems(prev => append ? [...prev, ...newItems] : newItems);
      setHasMore(newItems.length === 20);
    } catch {
      // swallow
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    setOffset(0);
    fetchFeed(filter, 0, false);
  }, [filter, fetchFeed]);

  function loadMore() {
    const next = offset + 20;
    setOffset(next);
    fetchFeed(filter, next, true);
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold">Community Feed</h2>
        <Tabs value={filter} onValueChange={v => setFilter(v as "global" | "following")}>
          <TabsList className="h-8">
            <TabsTrigger value="global" className="text-xs">Global</TabsTrigger>
            <TabsTrigger value="following" className="text-xs">Following</TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {loading && items.length === 0 ? (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="h-16 animate-pulse rounded-lg bg-muted/30" />
          ))}
        </div>
      ) : items.length === 0 ? (
        <Card className="border-border/60 bg-card/30 p-8 text-center">
          <p className="text-sm text-muted-foreground">
            {filter === "following"
              ? "Follow some players to see their activity here."
              : "No activity yet. Be the first to battle!"}
          </p>
        </Card>
      ) : (
        <div className="space-y-2">
          {items.map(item => (
            <FeedCard key={item.id} item={item} />
          ))}
          {hasMore && (
            <Button
              onClick={loadMore}
              variant="outline"
              className="w-full"
              disabled={loading}
            >
              {loading ? "Loading…" : "Load more"}
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Crown, TrendingUp, Shield } from "lucide-react";

type LeaderboardEntry = {
  rank: number;
  id: string;
  handle: string;
  display_name: string | null;
  avatar_url: string | null;
  elo_rating: number;
  wins: number;
  losses: number;
  total_battles: number;
  tier: string;
  is_verified: boolean;
  win_rate: number;
};

const TIER_COLORS: Record<string, string> = {
  bronze: "text-amber-600",
  silver: "text-slate-400",
  gold: "text-yellow-400",
  platinum: "text-cyan-400",
  diamond: "text-blue-400",
  legend: "text-purple-400",
};

const TIER_ICONS: Record<string, React.ReactNode> = {
  legend: <Crown className="h-3.5 w-3.5 text-purple-400" />,
  diamond: <Shield className="h-3.5 w-3.5 text-blue-400" />,
  platinum: <TrendingUp className="h-3.5 w-3.5 text-cyan-400" />,
};

function RankBadge({ rank }: { rank: number }) {
  if (rank === 1) return <span className="text-lg">🥇</span>;
  if (rank === 2) return <span className="text-lg">🥈</span>;
  if (rank === 3) return <span className="text-lg">🥉</span>;
  return <span className="w-6 text-center text-sm font-mono text-muted-foreground">{rank}</span>;
}

export function Leaderboard() {
  const [entries, setEntries] = React.useState<LeaderboardEntry[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [tier, setTier] = React.useState("all");
  const [period, setPeriod] = React.useState("all");

  React.useEffect(() => {
    setLoading(true);
    const params = new URLSearchParams({ limit: "50", period });
    if (tier !== "all") params.set("tier", tier);

    fetch(`/api/community/leaderboard?${params}`)
      .then(r => r.json())
      .then(d => setEntries(d.entries ?? []))
      .catch(() => setEntries([]))
      .finally(() => setLoading(false));
  }, [tier, period]);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-lg font-semibold">Leaderboard</h2>
        <div className="flex items-center gap-2">
          <Select value={tier} onValueChange={setTier}>
            <SelectTrigger className="h-8 w-32 text-xs">
              <SelectValue placeholder="Tier" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Tiers</SelectItem>
              <SelectItem value="legend">Legend</SelectItem>
              <SelectItem value="diamond">Diamond</SelectItem>
              <SelectItem value="platinum">Platinum</SelectItem>
              <SelectItem value="gold">Gold</SelectItem>
              <SelectItem value="silver">Silver</SelectItem>
              <SelectItem value="bronze">Bronze</SelectItem>
            </SelectContent>
          </Select>
          <Select value={period} onValueChange={setPeriod}>
            <SelectTrigger className="h-8 w-28 text-xs">
              <SelectValue placeholder="Period" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Time</SelectItem>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="weekly">Weekly</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {loading ? (
        <div className="space-y-2">
          {Array.from({ length: 10 }).map((_, i) => (
            <div key={i} className="h-14 animate-pulse rounded-lg bg-muted/30" />
          ))}
        </div>
      ) : entries.length === 0 ? (
        <Card className="border-border/60 bg-card/30 p-8 text-center">
          <p className="text-sm text-muted-foreground">No players ranked yet. Start battling!</p>
        </Card>
      ) : (
        <div className="overflow-hidden rounded-xl border border-border/60">
          <div className="grid grid-cols-[auto_1fr_auto_auto_auto] items-center gap-4 bg-muted/20 px-4 py-2 text-xs font-medium text-muted-foreground">
            <span>Rank</span>
            <span>Player</span>
            <span className="text-right">ELO</span>
            <span className="text-right">W/L</span>
            <span className="text-right">WR%</span>
          </div>
          <div className="divide-y divide-border/40">
            {entries.map((entry) => (
              <div
                key={entry.id}
                className={`grid grid-cols-[auto_1fr_auto_auto_auto] items-center gap-4 px-4 py-3 transition-colors hover:bg-card/40 ${entry.rank <= 3 ? "bg-card/20" : ""}`}
              >
                <RankBadge rank={entry.rank} />
                <div className="flex min-w-0 items-center gap-2">
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted/30 text-sm font-bold">
                    {entry.display_name?.[0] ?? entry.handle[0]}
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-1">
                      <Link href={`/app/players/${entry.id}`} className="truncate text-sm font-medium hover:underline">
                        {entry.display_name ?? entry.handle}
                      </Link>
                      {TIER_ICONS[entry.tier]}
                      {entry.is_verified && <span className="text-xs text-blue-400">✓</span>}
                    </div>
                    <span className={`text-xs ${TIER_COLORS[entry.tier] ?? "text-muted-foreground"}`}>
                      {entry.tier.toUpperCase()}
                    </span>
                  </div>
                </div>
                <span className="text-right font-mono text-sm font-semibold">{entry.elo_rating}</span>
                <span className="text-right text-xs text-muted-foreground">
                  {entry.wins}W / {entry.losses}L
                </span>
                <span className="text-right text-xs font-medium text-green-400">
                  {entry.win_rate}%
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { MatchmakingService, MatchmakingRequest } from "@/lib/pvp/MatchmakingService";
import { OpponentProfile } from "@/lib/pvp/OpponentOrchestrator";

interface CasualMatchmakingProps {
  playerId: string;
  playerMMR: number;
  onMatchFound: (match: any) => void;
}

export function CasualMatchmaking({ playerId, playerMMR, onMatchFound }: CasualMatchmakingProps) {
  const [isSearching, setIsSearching] = useState(false);
  const [searchStatus, setSearchStatus] = useState<'idle' | 'searching' | 'found' | 'connecting'>('idle');
  const [opponent, setOpponent] = useState<OpponentProfile | null>(null);
  const [matchTiming, setMatchTiming] = useState<any>(null);
  const [searchProgress, setSearchProgress] = useState(0);

  const matchmakingService = new MatchmakingService();

  const startCasualMatchmaking = async () => {
    setIsSearching(true);
    setSearchStatus('searching');
    setSearchProgress(0);

    const request: MatchmakingRequest = {
      playerId,
      skillEstimate: playerMMR,
      preferredMode: 'casual',
      latencyRegion: 'us-east'
    };

    try {
      const progressInterval = setInterval(() => {
        setSearchProgress(prev => Math.min(prev + 10, 90));
      }, 200);

      const match = await matchmakingService.findMatch(request);

      clearInterval(progressInterval);
      setSearchProgress(100);

      setSearchStatus('found');
      setOpponent(match.opponentProfile);
      setMatchTiming(match.pacingPlan);

      setTimeout(() => {
        setSearchStatus('connecting');

        setTimeout(() => {
          onMatchFound({
            matchId: match.matchId,
            opponent: match.opponentProfile,
            opponentType: match.opponentType,
            timing: match.pacingPlan,
            mode: 'casual'
          });
        }, match.pacingPlan.connectTime);
      }, 700 + Math.random() * 500);

    } catch (error) {
      console.error('Casual matchmaking failed:', error);
      setIsSearching(false);
      setSearchStatus('idle');
      setSearchProgress(0);
    }
  };

  const cancelSearch = () => {
    setIsSearching(false);
    setSearchStatus('idle');
    setOpponent(null);
    setMatchTiming(null);
    setSearchProgress(0);
  };

  const getOpponentTypeLabel = (opponent: OpponentProfile) => {
    if (opponent.isLive) return "Online";
    if (opponent.isGhost) return "Challenger";
    return "Rival";
  };

  const getOpponentTypeColor = (opponent: OpponentProfile) => {
    if (opponent.isLive) return "bg-green-500";
    if (opponent.isGhost) return "bg-blue-500";
    return "bg-purple-500";
  };

  if (isSearching) {
    return (
      <Card className="p-6 max-w-md mx-auto">
        <div className="text-center space-y-4">
          {searchStatus === 'searching' && (
            <>
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <h3 className="text-lg font-semibold">Finding opponent...</h3>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                  style={{ width: `${searchProgress}%` }}
                ></div>
              </div>
              <p className="text-sm text-gray-600">
                Looking for a fun match...
              </p>
              <Button variant="outline" onClick={cancelSearch}>
                Cancel
              </Button>
            </>
          )}

          {searchStatus === 'found' && opponent && (
            <>
              <div className="space-y-4">
                <div className="text-green-600 text-lg font-semibold">Opponent found!</div>

                <div className="flex items-center justify-center space-x-4">
                  <div className="text-center">
                    <Avatar className="h-16 w-16 mx-auto mb-2">
                      <AvatarImage src={opponent.avatar} />
                      <AvatarFallback className="text-2xl">
                        {opponent.name[0]?.toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <div className="font-semibold">{opponent.name}</div>
                    <Badge variant="secondary" className="text-xs">
                      {opponent.rank}
                    </Badge>
                    <div className="text-sm text-gray-600">
                      {opponent.badge} {opponent.rank}
                    </div>
                    <div className="flex items-center justify-center space-x-2 mt-1">
                      <div className={`w-2 h-2 rounded-full ${getOpponentTypeColor(opponent)}`}></div>
                      <span className="text-xs text-gray-500">
                        {getOpponentTypeLabel(opponent)}
                      </span>
                    </div>
                    {opponent.streak !== 0 && (
                      <div className="text-xs text-gray-500">
                        Streak: {opponent.streak > 0 ? '+' : ''}{opponent.streak}
                      </div>
                    )}
                  </div>
                </div>

                <div className="text-sm text-gray-600">
                  <div className="flex justify-between">
                    <span>Win Rate:</span>
                    <span>{Math.round(opponent.winRate * 100)}%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Style:</span>
                    <span className="capitalize">{opponent.persona.replace('_', ' ')}</span>
                  </div>
                </div>

                <div className="text-sm text-blue-600 animate-pulse">
                  Connecting...
                </div>
              </div>
            </>
          )}

          {searchStatus === 'connecting' && (
            <>
              <div className="animate-pulse">
                <div className="text-lg font-semibold">Establishing connection...</div>
                <div className="text-sm text-gray-600 mt-2">
                  Preparing battle arena
                </div>
              </div>
            </>
          )}
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-6 max-w-md mx-auto">
      <div className="text-center space-y-4">
        <h3 className="text-lg font-semibold">Casual Match</h3>
        <p className="text-sm text-gray-600">
          Play for fun without rank pressure!
        </p>

        <div className="text-sm text-gray-500 space-y-1">
          <div>Quick matches, relaxed competition</div>
        </div>

        <Button 
          onClick={startCasualMatchmaking}
          className="w-full"
        >
          Start Casual Match
        </Button>

        <div className="text-xs text-gray-400 space-y-1">
          <div>• Skill-based matchmaking ensures fair battles</div>
        </div>
      </div>
    </Card>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { MatchmakingService, MatchmakingRequest } from "@/lib/pvp/MatchmakingService";
import { OpponentProfile } from "@/lib/pvp/OpponentOrchestrator";

interface RankedMatchmakingProps {
  playerId: string;
  playerMMR: number;
  placementMatches: number;
  totalPlacementMatches: number;
  onMatchFound: (match: any) => void;
}

export function RankedMatchmaking({ 
  playerId, 
  playerMMR, 
  placementMatches, 
  totalPlacementMatches,
  onMatchFound 
}: RankedMatchmakingProps) {
  const [isSearching, setIsSearching] = useState(false);
  const [searchStatus, setSearchStatus] = useState<'idle' | 'searching' | 'found' | 'connecting'>('idle');
  const [opponent, setOpponent] = useState<OpponentProfile | null>(null);
  const [matchTiming, setMatchTiming] = useState<any>(null);
  const [searchProgress, setSearchProgress] = useState(0);

  const matchmakingService = new MatchmakingService();

  const getRankTier = (mmr: number) => {
    if (mmr < 1200) return { name: 'Underground', color: 'bg-gray-500' };
    if (mmr < 1800) return { name: 'Contender', color: 'bg-blue-500' };
    if (mmr < 2200) return { name: 'Headliner', color: 'bg-purple-500' };
    return { name: 'Icon', color: 'bg-yellow-500' };
  };

  const getPlacementProgress = () => {
    return (placementMatches / totalPlacementMatches) * 100;
  };

  const startRankedMatchmaking = async () => {
    setIsSearching(true);
    setSearchStatus('searching');
    setSearchProgress(0);

    const request: MatchmakingRequest = {
      playerId,
      skillEstimate: playerMMR,
      preferredMode: 'ranked',
      latencyRegion: 'us-east'
    };

    try {
      const progressInterval = setInterval(() => {
        setSearchProgress(prev => Math.min(prev + 10, 90));
      }, 200);

      const match = await matchmakingService.findMatch(request);

      clearInterval(progressInterval);
      setSearchProgress(100);

      setSearchStatus('found');
      setOpponent(match.opponentProfile);
      setMatchTiming(match.pacingPlan);

      setTimeout(() => {
        setSearchStatus('connecting');

        setTimeout(() => {
          onMatchFound({
            matchId: match.matchId,
            opponent: match.opponentProfile,
            opponentType: match.opponentType,
            timing: match.pacingPlan,
            mode: 'ranked'
          });
        }, match.pacingPlan.connectTime);
      }, 700 + Math.random() * 500);

    } catch (error) {
      console.error('Ranked matchmaking failed:', error);
      setIsSearching(false);
      setSearchStatus('idle');
      setSearchProgress(0);
    }
  };

  const cancelSearch = () => {
    setIsSearching(false);
    setSearchStatus('idle');
    setOpponent(null);
    setMatchTiming(null);
    setSearchProgress(0);
  };

  const getOpponentTypeLabel = (opponent: OpponentProfile) => {
    return "Challenger"; // Always use neutral language for ranked
  };

  const playerRank = getRankTier(playerMMR);

  if (isSearching) {
    return (
      <Card className="p-6 max-w-md mx-auto">
        <div className="text-center space-y-4">
          {searchStatus === 'searching' && (
            <>
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600 mx-auto"></div>
              <h3 className="text-lg font-semibold">Finding opponent...</h3>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="bg-purple-600 h-2 rounded-full transition-all duration-300"
                  style={{ width: `${searchProgress}%` }}
                ></div>
              </div>
              <p className="text-sm text-gray-600">
                Competitive matchmaking in progress...
              </p>
              <Button variant="outline" onClick={cancelSearch}>
                Cancel
              </Button>
            </>
          )}

          {searchStatus === 'found' && opponent && (
            <>
              <div className="space-y-4">
                <div className="text-green-600 text-lg font-semibold">Opponent found!</div>

                <div className="flex items-center justify-center space-x-4">
                  <div className="text-center">
                    <Avatar className="h-16 w-16 mx-auto mb-2">
                      <AvatarImage src={opponent.avatar} />
                      <AvatarFallback className="text-2xl">
                        {opponent.name[0]?.toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <div className="font-semibold">{opponent.name}</div>
                    <Badge variant="secondary" className="text-xs">
                      {opponent.rank}
                    </Badge>
                    <div className="text-sm text-gray-600">
                      {opponent.badge} {opponent.rank}
                    </div>
                    <div className="flex items-center justify-center space-x-2 mt-1">
                      <div className="w-2 h-2 rounded-full bg-purple-500"></div>
                      <span className="text-xs text-gray-500">
                        {getOpponentTypeLabel(opponent)}
                      </span>
                    </div>
                    {opponent.streak !== 0 && (
                      <div className="text-xs text-gray-500">
                        Streak: {opponent.streak > 0 ? '+' : ''}{opponent.streak}
                      </div>
                    )}
                  </div>
                </div>

                <div className="text-sm text-gray-600">
                  <div className="flex justify-between">
                    <span>Win Rate:</span>
                    <span>{Math.round(opponent.winRate * 100)}%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Style:</span>
                    <span className="capitalize">{opponent.persona.replace('_', ' ')}</span>
                  </div>
                </div>

                <div className="text-sm text-purple-600 animate-pulse">
                  Connecting...
                </div>
              </div>
            </>
          )}

          {searchStatus === 'connecting' && (
            <>
              <div className="animate-pulse">
                <div className="text-lg font-semibold">Establishing connection...</div>
                <div className="text-sm text-gray-600 mt-2">
                  Preparing ranked battle arena
                </div>
              </div>
            </>
          )}
        </div>
      </Card>
    );
  }

  const isUnranked = placementMatches < totalPlacementMatches;

  return (
    <Card className="p-6 max-w-md mx-auto">
      <div className="text-center space-y-4">
        <h3 className="text-lg font-semibold">Ranked Match</h3>
        <p className="text-sm text-gray-600">
          Compete for rank and climb the leaderboard.
        </p>

        <div className="space-y-3">
          {isUnranked ? (
            <>
              <div className="flex items-center justify-center space-x-2">
                <Badge variant="outline" className="text-sm">
                  Rank: Unranked
                </Badge>
              </div>
              <div className="space-y-2">
                <div className="text-sm text-gray-600">
                  Placement Matches: {placementMatches} / {totalPlacementMatches}
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div 
                    className="bg-purple-600 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${getPlacementProgress()}%` }}
                  ></div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex items-center justify-center space-x-2">
              <div className={`w-3 h-3 rounded-full ${playerRank.color}`}></div>
              <Badge variant="outline" className="text-sm">
                Rank: {playerRank.name}
              </Badge>
            </div>
          )}
        </div>

        <div className="text-sm text-gray-500 space-y-1">
          <div>Competitive matchmaking enabled</div>
          <div>Battles begin in seconds</div>
        </div>

        <Button 
          onClick={startRankedMatchmaking}
          className="w-full bg-purple-600 hover:bg-purple-700"
        >
          Start Ranked Match
        </Button>

        <div className="text-xs text-gray-400 space-y-1">
          <div>• Skill-based matchmaking ensures fair and competitive battles</div>
        </div>
      </div>
    </Card>
  );
}

