export class BotOpponent {
  private personality: BotPersonality;
  private battleContext: {
    beat: any;
    userLines: string[];
    round: number;
  };

  constructor(personalityId: string, beat: any) {
    this.personality = BOT_PERSONALITIES.find(p => p.id === personalityId) || BOT_PERSONALITIES[0];
    this.battleContext = {
      beat,
      userLines: [],
      round: 1
    };
  }

  generateIntro(): string {
    const lines = this.personality.introLines;
    return lines[Math.floor(Math.random() * lines.length)];
  }

  generateResponse(userLine: string): string {
    this.battleContext.userLines.push(userLine);

    // Generate bot response based on personality and context
    const response = this.createRhymeResponse(userLine);

    return response;
  }

  private createRhymeResponse(userLine: string): string {
    const themes = this.personality.vocabularyThemes;
    const patterns = this.personality.rhymePatterns;

    // Simple rhyme generation based on difficulty
    switch (this.personality.difficulty) {
      case 'easy':
        return this.generateEasyRhyme(userLine);
      case 'medium':
        return this.generateMediumRhyme(userLine);
      case 'hard':
        return this.generateHardRhyme(userLine);
      default:
        return this.generateEasyRhyme(userLine);
    }
  }

  private generateEasyRhyme(userLine: string): string {
    const easyRhymes = [
      "You think you're hot but you're really not!",
      "My rhymes are fire, yours are just weak!",
      "Step to the mic and get burned!",
      "I'm the king, you're the jester!"
    ];

    return easyRhymes[Math.floor(Math.random() * easyRhymes.length)];
  }

  private generateMediumRhyme(userLine: string): string {
    const mediumRhymes = [
      "Your flow's broken while mine's fluid like gold, / Every line I drop is worth more than you're told!",
      "I paint pictures with words, you just doodle and trace, / In this battle of wits, you're not even in the race!",
      "Metaphors sharp as razors, similes cut deep, / While you're still rhyming 'cat' with 'sleep'!",
      "My vocabulary's vast, yours is stuck on repeat, / This battle's over before you could even compete!"
    ];

    return mediumRhymes[Math.floor(Math.random() * mediumRhymes.length)];
  }

  private generateHardRhyme(userLine: string): string {
    const hardRhymes = [
      "I'm a lyrical architect constructing verbal monuments, / You're building sandcastles while I'm building monuments!",
      "Your cadence is elementary, my enunciation's surgical, / Each syllable I speak is purposefully purgatorial!",
      "I manipulate phonetics like a linguistic puppeteer, / Your rhymes are predictable, mine inspire fear!",
      "My wordplay's quantum physics, yours is basic arithmetic, / In this lyrical dimension, you're just plain pathetic!"
    ];

    return hardRhymes[Math.floor(Math.random() * hardRhymes.length)];
  }

  generateVictoryMessage(): string {
    const lines = this.personality.victoryLines;
    return lines[Math.floor(Math.random() * lines.length)];
  }

  generateDefeatMessage(): string {
    const lines = this.personality.defeatLines;
    return lines[Math.floor(Math.random() * lines.length)];
  }

  generateTaunt(): string {
    const lines = this.personality.tauntLines;
    return lines[Math.floor(Math.random() * lines.length)];
  }

  getPersonality(): BotPersonality {
    return this.personality;
  }
}

export function selectBotOpponent(userSkillLevel?: number): BotPersonality {
  // Select bot based on user skill level (0-100)
  if (!userSkillLevel) userSkillLevel = 50;

  if (userSkillLevel < 33) {
    return BOT_PERSONALITIES[0]; // Easy
  } else if (userSkillLevel < 66) {
    return BOT_PERSONALITIES[1]; // Medium
  } else {
    return BOT_PERSONALITIES[2]; // Hard
  }
}

export type BattleState = 
  | 'CREATED'
  | 'CHECKIN' 
  | 'CONFIG'
  | 'COUNTDOWN'
  | 'LIVE_ROUND_1'
  | 'INTERMISSION'
  | 'LIVE_ROUND_2'
  | 'JUDGING'
  | 'FINALIZING'
  | 'COMPLETE'
  | 'CANCELLED'
  | 'FORFEIT'
  | 'ERROR';

export type BattleAction = 
  | 'create_session'
  | 'join'
  | 'leave'
  | 'set_ready'
  | 'cancel'
  | 'lock_config'
  | 'start_countdown'
  | 'start_round'
  | 'end_round'
  | 'start_judging'
  | 'finalize'
  | 'complete'
  | 'admin_transition';

export type BattleRole = 'player' | 'judge' | 'admin' | 'system';

export interface BattleSlot {
  userId: string;
  present: boolean;
  ready: boolean;
  joinedAt: Date;
  lastSeen: Date;
}

export interface BattleConfig {
  rounds: number;
  roundDurationMs: number;
  beat: {
    beatId: string;
    locked: boolean;
  };
  hostId?: string;
}

export interface BattleTimers {
  serverNow: number;
  checkinDeadlineAt?: number;
  countdownStartsAt?: number;
  round1StartsAt?: number;
  round1EndsAt?: number;
  intermissionStartsAt?: number;
  intermissionEndsAt?: number;
  round2StartsAt?: number;
  round2EndsAt?: number;
  judgingStartsAt?: number;
  judgingEndsAt?: number;
  finalizeAt?: number;
}

export interface BattleScores {
  A: number;
  B: number;
}

export interface BattleSession {
  id: string;
  state: BattleState;
  revision: number;
  slots: {
    A: BattleSlot | null;
    B: BattleSlot | null;
  };
  config: BattleConfig;
  timers: BattleTimers;
  scores: BattleScores;
  winner?: 'A' | 'B';
  cancelReason?: string;
  forfeitReason?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface BattleTransition {
  from: BattleState;
  to: BattleState;
  trigger: BattleAction;
  guard?: (ctx: BattleContext) => boolean;
  effect?: (ctx: BattleContext) => void;
  auditLog?: (ctx: BattleContext, transition: BattleTransition) => void;
}

export interface BattleContext {
  session: BattleSession;
  actor: {
    userId: string;
    role: BattleRole;
  };
  intent?: any;
  serverNow: number;
  timers: BattleTimers;
  gracePeriodMs?: number;
}

export class BattleStateMachine {
  private transitions: Map<string, BattleTransition[]> = new Map();

  // Good enough defaults
  private readonly GRACE_PERIOD_MS = 15000;
  private readonly CHECKIN_TIMEOUT_MS = 60000;
  private readonly COUNTDOWN_MS = 5000;
  private readonly DEFAULT_ROUND_DURATION_MS = 30000;
  private readonly JUDGING_WINDOW_MS = 30000;
  private readonly INTERMISSION_MS = 10000;

  constructor() {
    this.initializeTransitions();
  }

  private initializeTransitions() {
    const transitions: BattleTransition[] = [
      // Session creation
      {
        from: 'CREATED',
        to: 'CHECKIN',
        trigger: 'create_session',
        effect: (ctx) => {
          ctx.session.timers.checkinDeadlineAt = ctx.serverNow + this.CHECKIN_TIMEOUT_MS;
          this.auditLog(ctx, {
            from: 'CREATED',
            to: 'CHECKIN',
            trigger: 'create_session',
            message: 'Session created, starting check-in'
          });
        }
      },

      // Check-in to Config (both players ready)
      {
        from: 'CHECKIN',
        to: 'CONFIG',
        trigger: 'set_ready',
        guard: (ctx) => Boolean(ctx.session.slots.A?.ready && ctx.session.slots.B?.ready),
        effect: (ctx) => {
          // Lock slots and assign host if needed
          this.lockSlots(ctx);
          ctx.session.timers.checkinDeadlineAt = undefined;
          this.auditLog(ctx, {
            from: 'CHECKIN',
            to: 'CONFIG',
            trigger: 'set_ready',
            message: 'Both players ready, moving to config'
          });
        }
      },

      // Check-in timeout
      {
        from: 'CHECKIN',
        to: 'CANCELLED',
        trigger: 'cancel',
        guard: (ctx) => ctx.serverNow >= (ctx.session.timers.checkinDeadlineAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'CANCELLED';
          ctx.session.cancelReason = 'Check-in timeout';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'CHECKIN',
            to: 'CANCELLED',
            trigger: 'cancel',
            message: 'Check-in timeout'
          });
        }
      },

      // Config to Countdown
      {
        from: 'CONFIG',
        to: 'COUNTDOWN',
        trigger: 'lock_config',
        guard: (ctx) => ctx.session.config.beat.locked,
        effect: (ctx) => {
          const countdownStartsAt = ctx.serverNow + 1000; // 1s buffer
          const round1StartsAt = countdownStartsAt + this.COUNTDOWN_MS;

          ctx.session.timers.countdownStartsAt = countdownStartsAt;
          ctx.session.timers.round1StartsAt = round1StartsAt;
          ctx.session.timers.round1EndsAt = round1StartsAt + ctx.session.config.roundDurationMs;

          // Set round 2 timers if applicable
          if (ctx.session.config.rounds === 2) {
            ctx.session.timers.intermissionStartsAt = ctx.session.timers.round1EndsAt + 1000;
            ctx.session.timers.intermissionEndsAt = ctx.session.timers.intermissionStartsAt + this.INTERMISSION_MS;
            ctx.session.timers.round2StartsAt = ctx.session.timers.intermissionEndsAt + 1000;
            ctx.session.timers.round2EndsAt = ctx.session.timers.round2StartsAt + ctx.session.config.roundDurationMs;
          }

          ctx.session.state = 'COUNTDOWN';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'CONFIG',
            to: 'COUNTDOWN',
            trigger: 'lock_config',
            message: 'Config locked, starting countdown'
          });
        }
      },

      // Countdown to Live Round 1
      {
        from: 'COUNTDOWN',
        to: 'LIVE_ROUND_1',
        trigger: 'start_round',
        guard: (ctx) => ctx.serverNow >= (ctx.session.timers.countdownStartsAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'LIVE_ROUND_1';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'COUNTDOWN',
            to: 'LIVE_ROUND_1',
            trigger: 'start_round',
            message: 'Round 1 started'
          });
        }
      },

      // Live Round 1 to Intermission (2 rounds)
      {
        from: 'LIVE_ROUND_1',
        to: 'INTERMISSION',
        trigger: 'end_round',
        guard: (ctx) => ctx.session.config.rounds === 2 && ctx.serverNow >= (ctx.session.timers.round1EndsAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'INTERMISSION';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'LIVE_ROUND_1',
            to: 'INTERMISSION',
            trigger: 'end_round',
            message: 'Round 1 ended, starting intermission'
          });
        }
      },

      // Live Round 1 to Judging (1 round)
      {
        from: 'LIVE_ROUND_1',
        to: 'JUDGING',
        trigger: 'end_round',
        guard: (ctx) => ctx.session.config.rounds === 1 && ctx.serverNow >= (ctx.session.timers.round1EndsAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'JUDGING';
          ctx.session.timers.judgingStartsAt = ctx.serverNow;
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'LIVE_ROUND_1',
            to: 'JUDGING',
            trigger: 'end_round',
            message: 'Round 1 ended, starting judging'
          });
        }
      },

      // Intermission to Countdown (round 2)
      {
        from: 'INTERMISSION',
        to: 'COUNTDOWN',
        trigger: 'start_round',
        guard: (ctx) => ctx.serverNow >= (ctx.session.timers.intermissionEndsAt || 0),
        effect: (ctx) => {
          const round2StartsAt = ctx.serverNow + 1000;
          ctx.session.timers.round2StartsAt = round2StartsAt;
          ctx.session.timers.round2EndsAt = round2StartsAt + ctx.session.config.roundDurationMs;

          ctx.session.state = 'COUNTDOWN';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'INTERMISSION',
            to: 'COUNTDOWN',
            trigger: 'start_round',
            message: 'Intermission ended, starting round 2 countdown'
          });
        }
      },

      // Countdown to Live Round 2
      {
        from: 'COUNTDOWN',
        to: 'LIVE_ROUND_2',
        trigger: 'start_round',
        guard: (ctx) => ctx.session.config.rounds === 2 && ctx.serverNow >= (ctx.session.timers.round2StartsAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'LIVE_ROUND_2';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'COUNTDOWN',
            to: 'LIVE_ROUND_2',
            trigger: 'start_round',
            message: 'Round 2 started'
          });
        }
      },

      // Live Round 2 to Judging
      {
        from: 'LIVE_ROUND_2',
        to: 'JUDGING',
        trigger: 'end_round',
        guard: (ctx) => ctx.serverNow >= (ctx.timers.round2EndsAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'JUDGING';
          ctx.session.timers.judgingStartsAt = ctx.serverNow;
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'LIVE_ROUND_2',
            to: 'JUDGING',
            trigger: 'end_round',
            message: 'Round 2 ended, starting judging'
          });
        }
      },

      // Judging to Finalizing
      {
        from: 'JUDGING',
        to: 'FINALIZING',
        trigger: 'finalize',
        guard: (ctx) => {
          // Voting window closed OR all required votes received
          const votingWindowClosed = ctx.serverNow >= (ctx.session.timers.judgingStartsAt! + this.JUDGING_WINDOW_MS);
          const allVotesIn = this.allVotesIn(ctx);
          return votingWindowClosed || allVotesIn;
        },
        effect: (ctx) => {
          this.computeResult(ctx);
          ctx.session.state = 'FINALIZING';
          ctx.session.timers.finalizeAt = ctx.serverNow + 5000; // 5s buffer for finalization
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'JUDGING',
            to: 'FINALIZING',
            trigger: 'finalize',
            message: 'Voting complete, finalizing results'
          });
        }
      },

      // Finalizing to Complete
      {
        from: 'FINALIZING',
        to: 'COMPLETE',
        trigger: 'complete',
        guard: (ctx) => ctx.serverNow >= (ctx.session.timers.finalizeAt || 0),
        effect: (ctx) => {
          ctx.session.state = 'COMPLETE';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'FINALIZING',
            to: 'COMPLETE',
            trigger: 'complete',
            message: 'Battle completed'
          });
        }
      },

      // Forfeit handling (any live state)
      {
        from: 'COUNTDOWN',
        to: 'FORFEIT',
        trigger: 'leave',
        guard: (ctx) => this.shouldForfeit(ctx),
        effect: (ctx) => {
          this.handleForfeit(ctx);
          ctx.session.state = 'FORFEIT';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'COUNTDOWN',
