        }
      },

      {
        from: 'LIVE_ROUND_1',
        to: 'FORFEIT',
        trigger: 'leave',
        guard: (ctx) => this.shouldForfeit(ctx),
        effect: (ctx) => {
          this.handleForfeit(ctx);
