          });
        }
      },

      {
        from: 'INTERMISSION',
        to: 'CANCELLED',
        trigger: 'admin_transition',
        effect: (ctx) => {
          ctx.session.state = 'CANCELLED';
          ctx.session.cancelReason = ctx.intent?.reason || 'Admin cancelled';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
