            message: `Admin cancelled: ${ctx.session.cancelReason}`
          });
        }
      },

      {
        from: 'FINALIZING',
        to: 'CANCELLED',
        trigger: 'admin_transition',
        effect: (ctx) => {
          ctx.session.state = 'CANCELLED';
          ctx.session.cancelReason = ctx.intent?.reason || 'Admin cancelled';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'FINALIZING',
            to: 'CANCELLED',
            trigger: 'admin_transition',
            message: `Admin cancelled: ${ctx.session.cancelReason}`
          });
        }
      },

      {
        from: 'FORFEIT',
        to: 'COMPLETE',
        trigger: 'admin_transition',
        effect: (ctx) => {
          ctx.session.state = 'COMPLETE';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'FORFEIT',
            to: 'COMPLETE',
            trigger: 'admin_transition',
            message: `Admin completed forfeited battle: ${ctx.session.winner}`
          });
        }
      },

      {
        from: 'ERROR',
        to: 'COMPLETE',
        trigger: 'admin_transition',
        effect: (ctx) => {
          ctx.session.state = 'COMPLETE';
          ctx.session.updatedAt = new Date();
          this.auditLog(ctx, {
            from: 'ERROR',
            to: 'COMPLETE',
            trigger: 'admin_transition',
            message: `Admin completed error state`
          });
        }
      }
    ];

    // Group transitions by from state
    for (const transition of transitions) {
      const key = `${transition.from}->${transition.to}`;
      if (!this.transitions.has(key)) {
        this.transitions.set(key, []);
      }
      this.transitions.get(key)!.push(transition);
    }
  }

  // Main transition method
  transition(context: BattleContext): BattleSession | null {
    const currentState = context.session.state;
    const trigger = context.intent?.type || context.intent;

    // Find matching transitions
    for (const [key, transitions] of this.transitions.entries()) {
      if (key.startsWith(`${currentState}->`)) {
        for (const transition of transitions) {
          if (transition.trigger === trigger && (!transition.guard || transition.guard(context))) {
            // Execute effect
            if (transition.effect) {
              transition.effect(context);
            }

            // Update session state
            context.session.state = transition.to;
            context.session.revision += 1;
            context.session.updatedAt = new Date();

            // Log transition
            this.auditLog(context, {
              from: currentState,
              to: transition.to,
              trigger,
              message: `Transition: ${currentState} -> ${transition.to} (${trigger})`
            });

            return context.session;
          }
        }
      }
    }

    return null;
  }

  // Helper methods
  private bothPlayersReady(ctx: BattleContext): boolean {
    return Boolean(ctx.session.slots.A?.ready) && Boolean(ctx.session.slots.B?.ready);
  }

  private lockSlots(ctx: BattleContext): void {
    // Assign host if not assigned
    if (!ctx.session.config.hostId && ctx.session.slots.A?.userId && ctx.session.slots.B?.userId) {
      ctx.session.config.hostId = ctx.session.slots.A.userId; // A gets host by default
    }
  }

  private shouldForfeit(ctx: BattleContext): boolean {
    const gracePeriodMs = ctx.gracePeriodMs || this.GRACE_PERIOD_MS;
    const lastSeen = ctx.actor.userId === ctx.session.slots.A?.userId 
      ? ctx.session.slots.A.lastSeen.getTime()
      : ctx.session.slots.B?.lastSeen?.getTime();

    const timeSinceLastSeen = ctx.serverNow - (lastSeen || 0);

    return timeSinceLastSeen > gracePeriodMs;
  }

  private handleForfeit(ctx: BattleContext): void {
    const remainingPlayer = ctx.actor.userId === ctx.session.slots.A?.userId ? ctx.session.slots.B : ctx.session.slots.A;

    if (remainingPlayer) {
      ctx.session.winner = remainingPlayer.userId === ctx.session.slots.A?.userId ? 'A' : 'B';
      ctx.session.scores[ctx.session.winner] = 100; // Winner gets 100 points
    }

    ctx.session.forfeitReason = ctx.intent?.reason || 'Player disconnected';
  }

  private computeResult(ctx: BattleContext): void {
    // Simple majority vote counting
    const voteCounts: Record<string, number> = {};

    // This would come from the database in real implementation
    // For now, we'll use the scores array
    if (ctx.session.scores.A > ctx.session.scores.B) {
      ctx.session.winner = 'A';
    } else if (ctx.session.scores.B > ctx.session.scores.A) {
      ctx.session.winner = 'B';
    }
  }

  private allVotesIn(ctx: BattleContext): boolean {
    // In real implementation, this would check the database
    // For now, assume votes are in session.scores
    return ctx.session.scores.A > 0 && ctx.session.scores.B > 0;
  }

  private auditLog(ctx: BattleContext, audit: {
    from: BattleState;
    to: BattleState;
    trigger: BattleAction;
    message: string;
  }): void {
    // In real implementation, this would write to an audit log table
    console.log(`[BattleStateMachine] ${ctx.session.id}: ${audit.message}`);
  }

  // Get valid transitions from current state
  getValidTransitions(state: BattleState): BattleTransition[] {
    const validTransitions: BattleTransition[] = [];

    for (const [key, transitions] of this.transitions.entries()) {
      if (key.startsWith(`${state}->`)) {
        validTransitions.push(...transitions);
      }
    }

    return validTransitions;
  }

  // Validate state integrity
  validateState(session: BattleSession): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];

    // Check slot integrity
    const hasA = !!session.slots.A?.userId;
    const hasB = !!session.slots.B?.userId;
    if (!(hasA && hasB)) {
      errors.push('Battle must have exactly 2 participants');
    }

    // Check state sequence validity
    const validSequences: BattleState[][] = [
      ['CREATED', 'CHECKIN', 'CONFIG', 'COUNTDOWN', 'LIVE_ROUND_1', 'INTERMISSION', 'LIVE_ROUND_2', 'JUDGING', 'FINALIZING', 'COMPLETE'],
      ['CREATED', 'CHECKIN', 'CONFIG', 'COUNTDOWN', 'LIVE_ROUND_1', 'JUDGING', 'FINALIZING', 'COMPLETE'],
      ['CREATED', 'CHECKIN', 'CANCELLED'],
      ['CONFIG', 'CANCELLED'],
      ['COUNTDOWN', 'CANCELLED'],
      ['LIVE_ROUND_1', 'FORFEIT'],
      ['LIVE_ROUND_2', 'FORFEIT'],
      ['JUDGING', 'FORFEIT'],
      ['FINALIZING', 'COMPLETE'],
      ['FORFEIT', 'COMPLETE'],
      ['ERROR', 'COMPLETE']
    ];

    const currentStateIndex = this.getStateIndex(session.state);
    const validSequence = validSequences.find(sequence => 
      sequence[currentStateIndex] === session.state
    );

    if (!validSequence) {
      errors.push(`Invalid state sequence: ${session.state}`);
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  private getStateIndex(state: BattleState): number {
    const states: BattleState[] = [
      'CREATED', 'CHECKIN', 'CONFIG', 'COUNTDOWN', 'LIVE_ROUND_1', 'INTERMISSION', 'LIVE_ROUND_2', 'JUDGING', 'FINALIZING', 'COMPLETE', 'CANCELLED', 'FORFEIT', 'ERROR'
    ];
    return states.indexOf(state);
  }
}

// Realtime message contract for battle system

export interface BattleMessage {
  v: 1;
  type: string;
  battleId: string;
  eventId: string;
  ts: number;
  actor: {
    userId: string;
    role: 'player' | 'judge' | 'admin' | 'system';
  };
  payload: any;
}

// Client → Server Intents
export interface ClientIntents {
  'battle.join': {
    slot: 'A' | 'B' | 'spectator';
  };

  'battle.ready': {
    ready: boolean;
  };

  'battle.leave': {
    reason: 'user_exit' | 'error';
  };

  'battle.chat.send': {
    text: string;
    clientMsgId: string;
  };

  'battle.vote.cast': {
    target: 'A' | 'B';
    weight: number;
    clientVoteId: string;
  };

  'battle.beat.select': {
    beatId: string;
    source: 'library';
  };

  'battle.admin.transition': {
    to: 'JUDGING' | 'COMPLETE' | 'CANCELLED';
    reason: string;
  };
}

// Server → Client Facts
export interface ServerFacts {
  'battle.state': {
    state: 'CREATED' | 'CHECKIN' | 'CONFIG' | 'COUNTDOWN' | 'LIVE_ROUND_1' | 'INTERMISSION' | 'LIVE_ROUND_2' | 'JUDGING' | 'FINALIZING' | 'COMPLETE' | 'CANCELLED' | 'FORFEIT' | 'ERROR';
    revision: number;
    slots: {
      A: {
        userId?: string;
        present: boolean;
        ready: boolean;
      } | null;
      B: {
        userId?: string;
        present: boolean;
        ready: boolean;
      } | null;
    };
    config: {
      rounds: number;
      roundDurationMs: number;
      beat: {
        beatId: string;
        locked: boolean;
      };
    };
    timers: {
      serverNow: number;
      countdownStartsAt?: number;
      round1StartsAt?: number;
      round1EndsAt?: number;
      round2StartsAt?: number;
      round2EndsAt?: number;
      judgingStartsAt?: number;
      judgingEndsAt?: number;
    };
    scores: {
      A: number;
      B: number;
    };
    winner?: 'A' | 'B';
    cancelReason?: string;
    forfeitReason?: string;
  };

  'battle.presence': {
    userId: string;
    status: 'join' | 'leave' | 'timeout';
  };

  'battle.chat.message': {
    msgId: string;
    userId: string;
    text: string;
    ts: number;
  };

  'battle.vote.update': {
    totals: {
      A: number;
      B: number;
    };
    locked: boolean;
  };

  'battle.error': {
    code: 'NOT_AUTHORIZED' | 'INVALID_STATE' | 'RATE_LIMIT';
    message: string;
  };
}

export class BattleRealtimeContract {
  // Channel names
  static readonly BATTLE_CHANNEL = (battleId: string) => `battle:${battleId}`;
  static readonly MEDIA_CHANNEL = (battleId: string) => `battle:${battleId}:media`;

  // Message creation helpers
  static createClientMessage<T extends keyof ClientIntents>(
    type: T,
    battleId: string,
    actor: { userId: string; role: string },
    payload: ClientIntents[T]
  ): BattleMessage {
    return {
      v: 1,
      type,
      battleId,
      eventId: this.generateEventId(),
      ts: Date.now(),
      actor: actor as any,
      payload
    };
  }

  static createServerMessage<T extends keyof ServerFacts>(
    type: T,
    battleId: string,
    actor: { userId: string; role: string },
    payload: ServerFacts[T]
  ): BattleMessage {
    return {
      v: 1,
      type,
      battleId,
      eventId: this.generateEventId(),
      ts: Date.now(),
      actor: actor as any,
      payload
    };
  }

  // Validation helpers
  static validateClientMessage(message: BattleMessage): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!message.battleId) errors.push('battleId is required');
    if (!message.eventId) errors.push('eventId is required');
    if (!message.actor.userId) errors.push('actor.userId is required');
    if (!message.actor.role) errors.push('actor.role is required');
    if (message.v !== 1) errors.push('version must be 1');
    if (!message.ts || message.ts <= 0) errors.push('timestamp must be positive');

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  static validateServerMessage(message: BattleMessage): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!message.battleId) errors.push('battleId is required');
    if (!message.eventId) errors.push('eventId is required');
    if (!message.actor.userId) errors.push('actor.userId is required');
    if (!message.actor.role) errors.push('actor.role is required');
    if (message.v !== 1) errors.push('version must be 1');
    if (!message.ts || message.ts <= 0) errors.push('timestamp must be positive');

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  // Rate limiting helpers
  static checkRateLimit(userId: string, type: string, lastSent: number): boolean {
    const now = Date.now();
    const minInterval = this.getMinInterval(type);

    return (now - lastSent) >= minInterval;
  }

  private static getMinInterval(type: string): number {
    const intervals: Record<string, number> = {
      'battle.chat.send': 1000, // 1 second
      'battle.vote.cast': 5000,  // 5 seconds
      'battle.ready': 2000,      // 2 seconds
      'battle.join': 5000,       // 5 seconds
      'battle.leave': 1000,      // 1 second
      'battle.beat.select': 2000, // 2 seconds
      'battle.admin.transition': 1000 // 1 second
    };

    return intervals[type] || 1000;
  }

  // Message deduplication
  static isDuplicate(message: BattleMessage, processedEvents: Set<string>): boolean {
    return processedEvents.has(message.eventId);
  }

  static markProcessed(message: BattleMessage, processedEvents: Set<string>): void {
    processedEvents.add(message.eventId);

    // Keep only last 1000 events to prevent memory leaks
    if (processedEvents.size > 1000) {
      const events = Array.from(processedEvents);
      processedEvents.clear();
      events.slice(-1000).forEach(id => processedEvents.add(id));
    }
  }

  // Payload validation
  static validatePayload(type: string, payload: any): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];

    switch (type) {
      case 'battle.join':
        if (!payload.slot || !['A', 'B', 'spectator'].includes(payload.slot)) {
          errors.push('slot must be A, B, or spectator');
        }
        break;

      case 'battle.chat.send':
        if (!payload.text || typeof payload.text !== 'string') {
          errors.push('text is required and must be a string');
        }
        if (payload.text.length > 500) {
          errors.push('text must be 500 characters or less');
        }
        if (!payload.clientMsgId) {
          errors.push('clientMsgId is required');
        }
        break;

      case 'battle.vote.cast':
        if (!payload.target || !['A', 'B'].includes(payload.target)) {
          errors.push('target must be A or B');
        }
        if (typeof payload.weight !== 'number' || payload.weight < 1 || payload.weight > 10) {
          errors.push('weight must be a number between 1 and 10');
        }
        if (!payload.clientVoteId) {
          errors.push('clientVoteId is required');
        }
        break;

      case 'battle.beat.select':
        if (!payload.beatId) {
          errors.push('beatId is required');
        }
        if (!payload.source || payload.source !== 'library') {
          errors.push('source must be library');
        }
        break;

      case 'battle.admin.transition':
        if (!payload.to || !['JUDGING', 'COMPLETE', 'CANCELLED'].includes(payload.to)) {
          errors.push('to must be JUDGING, COMPLETE, or CANCELLED');
        }
        if (!payload.reason) {
          errors.push('reason is required');
        }
        break;
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  // Message sanitization
  static sanitizePayload(type: string, payload: any): any {
    switch (type) {
      case 'battle.chat.send':
        return {
          ...payload,
          text: payload.text.replace(/<script[^>]*>.*?<\/script>/gi, '').substring(0, 500)
        };

      default:
        return payload;
    }
  }

  // Event ID generation
  private static generateEventId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  // Message serialization
  static serialize(message: BattleMessage): string {
    return JSON.stringify(message);
  }

  static deserialize(data: string): BattleMessage | null {
    try {
      const parsed = JSON.parse(data);
      if (this.validateClientMessage(parsed).isValid || this.validateServerMessage(parsed).isValid) {
        return parsed;
      }
      return null;
    } catch {
      return null;
    }
  }

  // Channel subscription validation
  static canSubscribeToChannel(channel: string, userId: string, battleId: string): boolean {
    if (channel === this.BATTLE_CHANNEL(battleId)) {
      return true; // Anyone can subscribe to battle channel
    }

    if (channel === this.MEDIA_CHANNEL(battleId)) {
      return true; // Anyone can subscribe to media channel
    }

    return false;
  }

  // Message routing
  static routeMessage(message: BattleMessage): {
    isClientIntent: boolean;
    isServerFact: boolean;
    messageType: string;
  } {
    const clientIntents = [
      'battle.join',
      'battle.ready', 
      'battle.leave',
      'battle.chat.send',
      'battle.vote.cast',
      'battle.beat.select',
      'battle.admin.transition'
    ];

    const serverFacts = [
      'battle.state',
      'battle.presence',
      'battle.chat.message',
      'battle.vote.update',
      'battle.error'
    ];

    return {
      isClientIntent: clientIntents.includes(message.type),
      isServerFact: serverFacts.includes(message.type),
      messageType: message.type
    };
  }

  // Message priority for ordering
  static getMessagePriority(type: string): number {
    const priorities: Record<string, number> = {
      'battle.state': 1,        // Highest priority
      'battle.presence': 2,
      'battle.error': 3,
      'battle.vote.update': 4,
      'battle.chat.message': 5,
      'battle.join': 6,
      'battle.leave': 7,
      'battle.ready': 8,
      'battle.beat.select': 9,
      'battle.vote.cast': 10,
      'battle.admin.transition': 11 // Lowest priority
    };

    return priorities[type] || 100;
  }

  // Message ordering
  static sortMessages(messages: BattleMessage[]): BattleMessage[] {
    return messages.sort((a, b) => {
      const priorityA = this.getMessagePriority(a.type);
      const priorityB = this.getMessagePriority(b.type);

      if (priorityA !== priorityB) {
        return priorityA - priorityB;
      }

      // Same priority, sort by timestamp
      return a.ts - b.ts;
    });
  }
}

import { createClient } from '@supabase/supabase-js';
import { RealtimeChannel } from '@supabase/realtime-js';

export type BattleSessionState = {
  id: string;
  status: 'queued' | 'live_round_1' | 'live_round_2' | 'judging' | 'complete';
  current_round: number;
  total_rounds: number;
  countdown_seconds: number;
  locked_beat_id?: string;
  winner?: string;
  created_at: string;
  updated_at: string;
};

export type BattlePresence = {
  user_id: string;
  slot: 1 | 2;
  status: 'connected' | 'ready' | 'recording' | 'disconnected';
  display_name: string;
  joined_at: string;
};

export type BattleMessage = {
  id: string;
  user_id: string;
  body: string;
  timestamp: number;
};

export type BattleVote = {
  user_id: string;
  round_number: number;
  voted_for: string;
  timestamp: number;
};

export class BattleRealtimeSync {
  private supabase: any;
  private channel: RealtimeChannel | null = null;
  private sessionId: string;
  private userId: string;

  constructor(sessionId: string, userId: string) {
    this.sessionId = sessionId;
    this.userId = userId;
    this.supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    );
  }

  // Connect to battle channel
  async connect() {
    const channelName = `battle:${this.sessionId}`;

    this.channel = this.supabase
      .channel(channelName)
      .on('broadcast', { event: 'session_state' }, (payload: any) => {
        this.handleSessionStateUpdate(payload.payload as BattleSessionState);
      })
      .on('broadcast', { event: 'presence' }, (payload: any) => {
        this.handlePresenceUpdate(payload.payload as BattlePresence);
      })
      .on('broadcast', { event: 'chat' }, (payload: any) => {
        this.handleChatMessage(payload.payload as BattleMessage);
      })
      .on('broadcast', { event: 'vote' }, (payload: any) => {
        this.handleVote(payload.payload as BattleVote);
      })
      .on('presence', { event: 'sync' }, () => {
        this.handlePresenceSync();
      })
      .on('presence', { event: 'join' }, ({ key, newPresences }: any) => {
        this.handleUserJoin(key, newPresences);
      })
      .on('presence', { event: 'leave' }, ({ key, leftPresences }: any) => {
        this.handleUserLeave(key, leftPresences);
      });

    if (this.channel) {
      const status = await this.channel.subscribe();
      if (typeof status === 'string' && status !== 'SUBSCRIBED' && status !== 'CHANNEL_ERROR') {
        throw new Error(`Failed to subscribe to battle channel: ${status}`);
      }
    }

    // Track this user's presence
    if (this.channel) {
      await this.channel.track({
        user_id: this.userId,
        status: 'connected',
        online_at: new Date().toISOString(),
      });
    }

    return this.channel;
  }

  // Disconnect from battle channel
  async disconnect() {
    if (this.channel) {
      await this.channel.untrack();
      await this.channel.unsubscribe();
      this.channel = null;
    }
  }

  // Server-authoritative session state updates
  async updateSessionState(state: Partial<BattleSessionState>) {
    if (!this.channel) return;

    await this.channel.send({
      type: 'broadcast',
      event: 'session_state_intent',
      payload: {
        user_id: this.userId,
        updates: state,
        timestamp: Date.now(),
      },
    });
  }

  // Client intents (server validates and applies)
  async sendReady() {
    if (!this.channel) return;

    await this.channel.send({
      type: 'broadcast',
      event: 'ready_intent',
      payload: {
        user_id: this.userId,
        timestamp: Date.now(),
      },
    });
  }

  async sendVote(roundNumber: number, votedFor: string) {
    if (!this.channel) return;

    await this.channel.send({
      type: 'broadcast',
      event: 'vote_intent',
      payload: {
        user_id: this.userId,
        round_number: roundNumber,
        voted_for: votedFor,
        timestamp: Date.now(),
      },
    });
  }

  async sendChatMessage(message: string) {
    if (!this.channel) return;

    await this.channel.send({
      type: 'broadcast',
      event: 'chat_intent',
      payload: {
        user_id: this.userId,
        body: message,
        timestamp: Date.now(),
      },
    });
  }

  async sendLeave() {
    if (!this.channel) return;

    await this.channel.send({
      type: 'broadcast',
      event: 'leave_intent',
      payload: {
        user_id: this.userId,
        timestamp: Date.now(),
      },
    });
  }

  // Event handlers (to be overridden by consuming component)
  private handleSessionStateUpdate(state: BattleSessionState) {
    // Emit custom event for React components
    window.dispatchEvent(new CustomEvent('battle:session_state', { detail: state }));
  }

  private handlePresenceUpdate(presence: BattlePresence) {
    window.dispatchEvent(new CustomEvent('battle:presence', { detail: presence }));
  }

  private handleChatMessage(message: BattleMessage) {
    window.dispatchEvent(new CustomEvent('battle:chat', { detail: message }));
  }

  private handleVote(vote: BattleVote) {
    window.dispatchEvent(new CustomEvent('battle:vote', { detail: vote }));
  }

  private handlePresenceSync() {
    // Sync all presence data
    window.dispatchEvent(new CustomEvent('battle:presence_sync'));
  }

  private handleUserJoin(key: string, newPresences: any[]) {
    window.dispatchEvent(new CustomEvent('battle:user_join', { detail: { key, presences: newPresences } }));
  }

  private handleUserLeave(key: string, leftPresences: any[]) {
    window.dispatchEvent(new CustomEvent('battle:user_leave', { detail: { key, presences: leftPresences } }));
  }

  // Get current channel status
  getChannelStatus() {
    const state = (this.channel as any)?.state;
    return state?.status ?? state;
  }

  // Get current presence state
  getPresenceState() {
    return this.channel?.presenceState();
  }
}

import { createClient } from '@supabase/supabase-js';
import crypto from 'crypto';

export interface MatchEvent {
  seq: number;
  t_ms: number;
  actor: 'player_a' | 'player_b' | 'server' | 'bot';
  event_type: 'MATCH_START' | 'PLAYER_INPUT' | 'OPPONENT_ACTION' | 'SCORE_CHANGE' | 'STATE_SNAPSHOT' | 'MATCH_END' | 'ROUND_START' | 'ROUND_END';
  payload: any;
}

export interface MatchRecording {
  match_id: string;
  mode: 'ranked' | 'casual';
  region: string;
  player_a_id: string;
  player_b_id?: string;
  player_a_mmr: number;
  player_b_mmr?: number;
  winner?: string;
  duration_ms: number;
  summary: any;
  events: MatchEvent[];
  is_bot_match: boolean;
  bot_personality_id?: string;
  governance_tier?: string;
  opponent_plan_id?: string;
}

export interface GhostPattern {
  player_id: string;
  recording_match_id: string;
  player_mmr_at_time: number;
  skill_band: 'easy' | 'mid' | 'hard';
  playstyle_tags: string[];
  reaction_time_avg_ms: number;
  reaction_time_std_ms: number;
  mistake_rate: number;
  aggression_score: number;
  adaptation_score: number;
  opening_patterns: any[];
  response_patterns: any[];
  pressure_responses: any[];
  recording_quality_score: number;
}

export class GhostRecordingSystem {
  private supabase: any;
  private eventBuffer: Map<string, MatchEvent[]> = new Map();
  private recordingSessions: Map<string, MatchRecording> = new Map();

  constructor() {
    this.supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    );
  }

  // Start recording a match
  async startRecording(recording: Omit<MatchRecording, 'events' | 'duration_ms'>): Promise<string> {
    const match_id = recording.match_id;

    // Initialize recording session
    const fullRecording: MatchRecording = {
      ...recording,
      events: [],
      duration_ms: 0
    };

    this.recordingSessions.set(match_id, fullRecording);
    this.eventBuffer.set(match_id, []);

    // Record MATCH_START event
    await this.recordEvent(match_id, {
      seq: 0,
      t_ms: 0,
      actor: 'server',
      event_type: 'MATCH_START',
      payload: {
        mode: recording.mode,
        region: recording.region,
        player_a_id: recording.player_a_id,
        player_b_id: recording.player_b_id,
        player_a_mmr: recording.player_a_mmr,
        player_b_mmr: recording.player_b_mmr,
        is_bot_match: recording.is_bot_match,
        bot_personality_id: recording.bot_personality_id,
        governance_tier: recording.governance_tier
      }
    });

    console.log(`📹 Started recording match: ${match_id}`);
    return match_id;
  }

  // Record an event during the match
  async recordEvent(match_id: string, event: Omit<MatchEvent, 'seq'>): Promise<void> {
    const buffer = this.eventBuffer.get(match_id);
    if (!buffer) {
      console.warn(`No recording session found for match: ${match_id}`);
      return;
    }

    // Assign sequence number
    const seq = buffer.length;
    const fullEvent: MatchEvent = { ...event, seq };

    // Add to buffer
    buffer.push(fullEvent);

    // Periodically flush to database (every 10 events or every 5 seconds)
    if (buffer.length >= 10 || (buffer.length > 0 && Date.now() % 5000 < 100)) {
      await this.flushEvents(match_id);
    }
  }

  // Record player input
  async recordPlayerInput(match_id: string, player_id: string, inputData: any): Promise<void> {
    await this.recordEvent(match_id, {
      t_ms: Date.now(),
      actor: player_id === this.recordingSessions.get(match_id)?.player_a_id ? 'player_a' : 'player_b',
      event_type: 'PLAYER_INPUT',
      payload: inputData
    });
  }

  // Record opponent action
  async recordOpponentAction(match_id: string, actionData: any): Promise<void> {
    await this.recordEvent(match_id, {
      t_ms: Date.now(),
      actor: this.recordingSessions.get(match_id)?.is_bot_match ? 'bot' : 'player_b',
      event_type: 'OPPONENT_ACTION',
      payload: actionData
    });
  }

  // Record score change
  async recordScoreChange(match_id: string, player_a_score: number, player_b_score: number): Promise<void> {
    await this.recordEvent(match_id, {
      t_ms: Date.now(),
      actor: 'server',
      event_type: 'SCORE_CHANGE',
      payload: { player_a_score, player_b_score }
    });
  }

  // Record state snapshot
  async recordStateSnapshot(match_id: string, gameState: any): Promise<void> {
    await this.recordEvent(match_id, {
      t_ms: Date.now(),
      actor: 'server',
      event_type: 'STATE_SNAPSHOT',
      payload: gameState
    });
  }

  // End recording and save to database
  async endRecording(match_id: string, winner?: string, finalScores?: {player_a: number, player_b: number}): Promise<void> {
    const recording = this.recordingSessions.get(match_id);
    if (!recording) {
      console.warn(`No recording session found for match: ${match_id}`);
      return;
    }

    // Flush remaining events
    await this.flushEvents(match_id);

    // Record MATCH_END event
    await this.recordEvent(match_id, {
      t_ms: Date.now(),
      actor: 'server',
      event_type: 'MATCH_END',
      payload: {
        winner,
        final_scores: finalScores,
        duration_ms: Date.now() - recording.events[0]?.t_ms || 0
      }
    });

    // Final flush
    await this.flushEvents(match_id);

    // Calculate final duration and save match replay
    const events = this.eventBuffer.get(match_id) || [];
    const duration_ms = events.length > 0 ? events[events.length - 1].t_ms - events[0].t_ms : 0;

    // Generate event stream hash and server signature
    const eventStreamHash = this.generateEventStreamHash(events);
    const serverSignature = this.generateServerSignature(eventStreamHash);

    // Save to database
    await this.saveMatchReplay({
      ...recording,
      duration_ms,
      summary: this.generateMatchSummary(events),
      event_stream_hash: eventStreamHash,
      server_signature: serverSignature
    }, events);

    // Process for ghost library if it's a human vs human match
    if (!recording.is_bot_match && recording.player_b_id) {
      await this.processForGhostLibrary(recording, events);
    }

    // Clean up
    this.recordingSessions.delete(match_id);
    this.eventBuffer.delete(match_id);

    console.log(`📹 Finished recording match: ${match_id} (${events.length} events, ${duration_ms}ms)`);
  }

  // Flush events to database
  private async flushEvents(match_id: string): Promise<void> {
    const events = this.eventBuffer.get(match_id);
    if (!events || events.length === 0) return;

    try {
      // Insert events in batch
      const { error } = await this.supabase.from('match_replay_events').insert(
        events.map(event => ({
          match_id,
          seq: event.seq,
          t_ms: event.t_ms,
          actor: event.actor,
          event_type: event.event_type,
          payload_json: event.payload
        }))
      );

      if (error) {
        console.error('Failed to flush events:', error);
        return;
      }

      // Clear flushed events
      const remainingEvents = events.slice(-5); // Keep last 5 events in buffer
      this.eventBuffer.set(match_id, remainingEvents);

    } catch (error) {
      console.error('Error flushing events:', error);
    }
  }

  // Save match replay to database
  private async saveMatchReplay(recording: MatchRecording, events: MatchEvent[]): Promise<void> {
    try {
      const { error } = await this.supabase.from('match_replays').insert({
        match_id: recording.match_id,
        mode: recording.mode,
        region: recording.region,
        player_a_id: recording.player_a_id,
        player_b_id: recording.player_b_id,
        player_a_mmr: recording.player_a_mmr,
        player_b_mmr: recording.player_b_mmr,
        winner: recording.winner,
        duration_ms: recording.duration_ms,
        summary_json: recording.summary,
        event_stream_hash: recording.event_stream_hash || '',
        server_signature: recording.server_signature || '',
        is_bot_match: recording.is_bot_match,
        bot_personality_id: recording.bot_personality_id,
        governance_tier: recording.governance_tier,
        opponent_plan_id: recording.opponent_plan_id
      });

      if (error) {
        console.error('Failed to save match replay:', error);
      }

    } catch (error) {
      console.error('Error saving match replay:', error);
    }
  }

  // Process recording for ghost library
  private async processForGhostLibrary(recording: MatchRecording, events: MatchEvent[]): Promise<void> {
    // Analyze both players' patterns
    await this.analyzePlayerForGhost(recording.player_a_id, recording.player_a_mmr, events, 'player_a');

    if (recording.player_b_id) {
      await this.analyzePlayerForGhost(recording.player_b_id, recording.player_b_mmr || 0, events, 'player_b');
    }
  }

  // Analyze player patterns for ghost library
  private async analyzePlayerForGhost(
    player_id: string, 
    player_mmr: number, 
    events: MatchEvent[], 
    actor: 'player_a' | 'player_b'
  ): Promise<void> {
    const playerEvents = events.filter(e => e.actor === actor && e.event_type === 'PLAYER_INPUT');

    if (playerEvents.length < 5) {
      console.log(`Insufficient events for ghost analysis: ${player_id}`);
      return;
    }

    // Calculate metrics
    const skill_band = player_mmr < 1200 ? 'easy' : player_mmr < 1800 ? 'mid' : 'hard';

    // Reaction time analysis
    const reactionTimes = this.calculateReactionTimes(events, actor);
    const reaction_time_avg_ms = reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length;
    const reaction_time_std_ms = this.calculateStandardDeviation(reactionTimes);

    // Mistake rate analysis
    const mistake_rate = this.calculateMistakeRate(events, actor);

    // Aggression and adaptation scores
    const aggression_score = this.calculateAggressionScore(events, actor);
    const adaptation_score = this.calculateAdaptationScore(events, actor);

    // Pattern analysis
    const opening_patterns = this.extractOpeningPatterns(events, actor);
    const response_patterns = this.extractResponsePatterns(events, actor);
    const pressure_responses = this.extractPressureResponses(events, actor);

    // Playstyle tags
    const playstyle_tags = this.generatePlaystyleTags(aggression_score, adaptation_score, mistake_rate);

    // Recording quality score
    const recording_quality_score = this.calculateRecordingQuality(events, actor);

    const ghostPattern: GhostPattern = {
      player_id,
      recording_match_id: events[0].payload.match_id,
      player_mmr_at_time: player_mmr,
      skill_band,
      playstyle_tags,
      reaction_time_avg_ms,
      reaction_time_std_ms,
      mistake_rate,
      aggression_score,
      adaptation_score,
      opening_patterns,
      response_patterns,
      pressure_responses,
      recording_quality_score
    };

    // Save to ghost library
    await this.saveGhostPattern(ghostPattern);
  }

  // Analysis helper methods
  private calculateReactionTimes(events: MatchEvent[], actor: 'player_a' | 'player_b'): number[] {
    const reactionTimes: number[] = [];
    let lastOpponentAction = 0;

    for (const event of events) {
      if (event.actor !== actor && event.event_type === 'OPPONENT_ACTION') {
        lastOpponentAction = event.t_ms;
      } else if (event.actor === actor && event.event_type === 'PLAYER_INPUT' && lastOpponentAction > 0) {
        reactionTimes.push(event.t_ms - lastOpponentAction);
        lastOpponentAction = 0;
      }
    }

    return reactionTimes;
  }

  private calculateStandardDeviation(values: number[]): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const variance = values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / values.length;
    return Math.sqrt(variance);
  }

  private calculateMistakeRate(events: MatchEvent[], actor: 'player_a' | 'player_b'): number {
    const playerInputs = events.filter(e => e.actor === actor && e.event_type === 'PLAYER_INPUT');
    const mistakes = playerInputs.filter(e => e.payload.is_mistake === true).length;
    return mistakes / playerInputs.length;
  }

  private calculateAggressionScore(events: MatchEvent[], actor: 'player_a' | 'player_b'): number {
    const playerInputs = events.filter(e => e.actor === actor && e.event_type === 'PLAYER_INPUT');
    const aggressiveActions = playerInputs.filter(e => e.payload.aggression_level > 0.7).length;
    return aggressiveActions / playerInputs.length;
  }

  private calculateAdaptationScore(events: MatchEvent[], actor: 'player_a' | 'player_b'): number {
    // Simple adaptation score based on pattern variation
    const playerInputs = events.filter(e => e.actor === actor && e.event_type === 'PLAYER_INPUT');
    const patterns = new Set(playerInputs.map(e => e.payload.pattern_type));
    return Math.min(1, patterns.size / 10); // Normalize to 0-1
  }

  private extractOpeningPatterns(events: MatchEvent[], actor: 'player_a' | 'player_b'): any[] {
    const firstThreeInputs = events.filter(e => e.actor === actor && e.event_type === 'PLAYER_INPUT').slice(0, 3);
    return firstThreeInputs.map(e => ({
      pattern_type: e.payload.pattern_type,
      timing: e.t_ms,
      aggression: e.payload.aggression_level
    }));
  }

  private extractResponsePatterns(events: MatchEvent[], actor: 'player_a' | 'player_b'): any[] {
    const patterns: any[] = [];
    let lastOpponentAction: any = null;

    for (const event of events) {
      if (event.actor !== actor && event.event_type === 'OPPONENT_ACTION') {
        lastOpponentAction = event.payload;
      } else if (event.actor === actor && event.event_type === 'PLAYER_INPUT' && lastOpponentAction) {
        patterns.push({
          opponent_action: lastOpponentAction,
          response: event.payload,
          timing: event.t_ms
        });
        lastOpponentAction = null;
      }
    }

    return patterns;
  }

  private extractPressureResponses(events: MatchEvent[], actor: 'player_a' | 'player_b'): any[] {
    const pressureEvents = events.filter(e => e.payload.is_under_pressure === true);
    return pressureEvents.map(e => ({
      event: e.payload,
      response_timing: e.t_ms,
      success: e.payload.successful_response
    }));
  }

  private generatePlaystyleTags(aggression: number, adaptation: number, mistakeRate: number): string[] {
    const tags: string[] = [];

    if (aggression > 0.7) tags.push('aggressive');
    else if (aggression < 0.3) tags.push('defensive');

    if (adaptation > 0.7) tags.push('adaptive');
    else if (adaptation < 0.3) tags.push('predictable');

    if (mistakeRate > 0.1) tags.push('error_prone');
    else if (mistakeRate < 0.05) tags.push('precise');

    return tags;
  }

  private calculateRecordingQuality(events: MatchEvent[], actor: 'player_a' | 'player_b'): number {
    const playerEvents = events.filter(e => e.actor === actor);

    // Quality factors
    const eventCount = playerEvents.length;
    const hasTiming = playerEvents.every(e => e.t_ms > 0);
    const hasPayload = playerEvents.every(e => e.payload && Object.keys(e.payload).length > 0);

    let quality = 0.5; // Base quality

    if (eventCount >= 10) quality += 0.2;
    if (eventCount >= 20) quality += 0.1;
    if (hasTiming) quality += 0.1;
    if (hasPayload) quality += 0.1;

    return Math.min(1, quality);
  }

  // Save ghost pattern to library
  private async saveGhostPattern(pattern: GhostPattern): Promise<void> {
    try {
      const { error } = await this.supabase.from('ghost_library').insert({
        player_id: pattern.player_id,
        recording_match_id: pattern.recording_match_id,
        player_mmr_at_time: pattern.player_mmr_at_time,
        skill_band: pattern.skill_band,
        playstyle_tags: pattern.playstyle_tags,
        reaction_time_avg_ms: pattern.reaction_time_avg_ms,
        reaction_time_std_ms: pattern.reaction_time_std_ms,
        mistake_rate: pattern.mistake_rate,
        aggression_score: pattern.aggression_score,
        adaptation_score: pattern.adaptation_score,
        opening_patterns: pattern.opening_patterns,
        response_patterns: pattern.response_patterns,
        pressure_responses: pattern.pressure_responses,
        recording_quality_score: pattern.recording_quality_score,
        is_verified: pattern.recording_quality_score > 0.8
      });

      if (error) {
        console.error('Failed to save ghost pattern:', error);
      }

    } catch (error) {
      console.error('Error saving ghost pattern:', error);
    }
  }

  // Find similar ghosts for matchmaking
  async findSimilarGhosts(playerMMR: number, skillBand: string, limit: number = 5): Promise<any[]> {
    try {
      const { data, error } = await this.supabase
        .from('ghost_library')
        .select('*')
        .eq('skill_band', skillBand)
        .gte('recording_quality_score', 0.7)
        .order('recording_quality_score', { ascending: false })
        .limit(limit * 2); // Get more to calculate similarity

      if (error) {
        console.error('Failed to find similar ghosts:', error);
        return [];
      }

      // Calculate similarity scores
      const ghosts = data || [];
      const scoredGhosts = ghosts.map(ghost => ({
        ...ghost,
        similarity_score: this.calculateSimilarity(playerMMR, ghost)
      }));

      // Sort by similarity and return top matches
      return scoredGhosts
        .sort((a, b) => b.similarity_score - a.similarity_score)
        .slice(0, limit);

    } catch (error) {
      console.error('Error finding similar ghosts:', error);
      return [];
    }
  }

  private calculateSimilarity(playerMMR: number, ghost: any): number {
    const mmrDiff = Math.abs(playerMMR - ghost.player_mmr_at_time);
    const mmrSimilarity = Math.max(0, 1 - (mmrDiff / 500)); // Normalize MMR difference

    // Combine with quality score
    return (mmrSimilarity * 0.7) + (ghost.recording_quality_score * 0.3);
  }

  // Utility methods
  private generateEventStreamHash(events: MatchEvent[]): string {
    const eventStream = JSON.stringify(events);
    return crypto.createHash('sha256').update(eventStream).digest('hex');
  }

  private generateServerSignature(hash: string): string {
    // In production, this would use a proper private key
    const secret = process.env.SERVER_SIGNATURE_SECRET || 'default-secret';
    return crypto.createHmac('sha256', secret).update(hash).digest('hex');
  }

  private generateMatchSummary(events: MatchEvent[]): any {
    const playerAEvents = events.filter(e => e.actor === 'player_a');
    const playerBEvents = events.filter(e => e.actor === 'player_b');

    return {
      total_events: events.length,
      player_a_actions: playerAEvents.length,
      player_b_actions: playerBEvents.length,
      match_duration: events.length > 0 ? events[events.length - 1].t_ms - events[0].t_ms : 0,
      event_types: [...new Set(events.map(e => e.event_type))]
    };
  }
}

import { createClient } from '@supabase/supabase-js';

interface GovernanceContext {
  execution_type: string;
  playerContext: any;
  matchContext: any;
}

interface GovernanceResult {
  success: boolean;
  data?: any;
  error?: string;
  governance_tier: string;
  risk_scores: any;
  validation_results: any;
  cost_estimate?: number;
  latency_ms?: number;
}

export async function runGovernedExecution(context: GovernanceContext): Promise<GovernanceResult> {
  const startTime = Date.now();

  try {
    // Step 1: Navigator normalization
    const normalizedContext = await navigatorNormalization(context);

    // Step 2: Risk scoring
    const riskScores = await riskScoring(normalizedContext);

    // Step 3: Ecobe routing
    const routingDecision = await ecobeRouting(normalizedContext, riskScores);

    // Step 4: ConvergeOS schema validation
    const schemaValidation = await convergeOSSchemaValidation(normalizedContext);

    // Step 5: VCTT coherence
    const coherenceCheck = await vcttCoherence(normalizedContext);

    // Step 6: Watchtower validation
    const watchtowerValidation = await watchtowerValidation(normalizedContext);

    // Step 7: Community memory similarity check
    const similarityCheck = await communityMemoryCheck(normalizedContext);

    // Step 8: Citizenship fairness evaluation
    const fairnessEvaluation = await citizenshipFairness(normalizedContext);

    // Step 9: Tier rules enforcement
    const tierAssignment = await enforceTierRules({
      riskScores,
      routingDecision,
      schemaValidation,
      coherenceCheck,
      watchtowerValidation,
      similarityCheck,
      fairnessEvaluation
    });

    // Step 10: Generate opponent plan if all validations pass
    let opponentPlan = null;
    if (tierAssignment.success) {
      opponentPlan = await generateOpponentPlan(normalizedContext, tierAssignment);
    }

    const latency = Date.now() - startTime;

    return {
      success: tierAssignment.success && opponentPlan !== null,
      data: opponentPlan,
      governance_tier: tierAssignment.tier,
      risk_scores: riskScores,
      validation_results: {
        navigator: normalizedContext,
        routing: routingDecision,
        schema: schemaValidation,
        coherence: coherenceCheck,
        watchtower: watchtowerValidation,
        similarity: similarityCheck,
        fairness: fairnessEvaluation,
        tier: tierAssignment
      },
      cost_estimate: calculateCost(tierAssignment.tier, riskScores),
      latency_ms: latency
    };

  } catch (error) {
    const latency = Date.now() - startTime;
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown governance error',
      governance_tier: 'BLOCKED',
      risk_scores: null,
      validation_results: null,
      latency_ms: latency
    };
  }
}

// Governance Layer Implementations

async function navigatorNormalization(context: GovernanceContext) {
  // Normalize input data to prevent injection and ensure consistency
  return {
    ...context,
    playerContext: {
      id: context.playerContext.id,
      mmr: Math.max(0, Math.min(5000, context.playerContext.mmr || 1500)),
      region: context.playerContext.region || 'unknown',
      skill_level: context.playerContext.skill_level || 'mid'
    },
    matchContext: {
      mode: context.matchContext.mode || 'casual',
      queue_time: Math.max(0, context.matchContext.queue_time || 0)
    }
  };
}

async function riskScoring(context: GovernanceContext) {
  // Calculate risk scores for fracture, detrimental, drift
  const scores = {
    fracture: calculateFractureRisk(context),
    detrimental: calculateDetrimentalRisk(context),
    drift: calculateDriftRisk(context)
  };

  const overallRisk = Math.max(scores.fracture, scores.detrimental, scores.drift);

  return {
    ...scores,
    overall: overallRisk,
    level: overallRisk > 0.8 ? 'HIGH' : overallRisk > 0.5 ? 'MEDIUM' : 'LOW'
  };
}

async function ecobeRouting(context: GovernanceContext, riskScores: any) {
  // Route based on risk and load balancing
  const route = {
    endpoint: 'primary',
    priority: 'normal',
    load_shed: false
  };

  if (riskScores.overall > 0.8) {
    route.endpoint = 'secondary';
    route.priority = 'low';
  }

  return route;
}

async function convergeOSSchemaValidation(context: GovernanceContext) {
  // Validate schema compliance
  const required = ['execution_type', 'playerContext', 'matchContext'];
  const missing = required.filter(field => !(field in context));

  return {
    valid: missing.length === 0,
    missing_fields: missing,
    schema_version: '1.0'
  };
}

async function vcttCoherence(context: GovernanceContext) {
  // Verify coherence with VCTT principles
  return {
    coherent: true,
    violations: [],
    confidence: 0.95
  };
}

async function watchtowerValidation(context: GovernanceContext) {
  // Watchtower security and policy validation
  const checks = [
    { name: 'injection', passed: true },
    { name: 'privilege', passed: true },
    { name: 'rate_limit', passed: true },
    { name: 'content_policy', passed: true }
  ];

  return {
    passed: checks.every(c => c.passed),
    checks: checks,
    score: 1.0
  };
}

async function communityMemoryCheck(context: GovernanceContext) {
  // Check against community memory for similar patterns
  const similarity = Math.random(); // In real implementation, would query community memory

  return {
    similarity_score: similarity,
    flagged: similarity > 0.9,
    recommendations: similarity > 0.8 ? ['review_for_abuse'] : []
  };
}

async function citizenshipFairness(context: GovernanceContext) {
  // Evaluate fairness according to citizenship principles
  const fairness = {
    bias_score: Math.random() * 0.1, // Should be < 0.12
    manipulation_risk: Math.random() * 0.05, // Should be low
    transparency_score: 0.9 // Should be high
  };

  return {
    passed: fairness.bias_score < 0.12 && fairness.manipulation_risk < 0.1,
    ...fairness
  };
}

async function enforceTierRules(validations: any) {
  // Tier2 requires 3/3 Watchtower pass and full Citizenship pass
  const watchtowerPass = validations.watchtower.passed;
  const citizenshipPass = validations.fairness.passed;
  const riskLevel = validations.riskScores.level;

  if (watchtowerPass && citizenshipPass && riskLevel === 'LOW') {
    return {
      success: true,
      tier: 'TIER2',
      confidence: 0.95
    };
  } else if (watchtowerPass && citizenshipPass) {
    return {
      success: true,
      tier: 'TIER1',
      confidence: 0.85
    };
  } else {
    return {
      success: false,
      tier: 'BLOCKED',
      reason: 'Validation failures',
      blocked_by: !watchtowerPass ? 'watchtower' : 'citizenship'
    };
  }
}

async function generateOpponentPlan(context: GovernanceContext, tierAssignment: any) {
  // Generate opponent plan based on validated context
  const playerMMR = context.playerContext.mmr;
  const matchMode = context.matchContext.mode;

  // Determine skill band based on MMR
  let skill_band: 'easy' | 'mid' | 'hard';
  if (playerMMR < 1200) skill_band = 'easy';
  else if (playerMMR < 1800) skill_band = 'mid';
  else skill_band = 'hard';

  // Select persona
  const personas = ['Aggro', 'Turtle', 'Counter', 'Gambler'];
  const persona = personas[Math.floor(Math.random() * personas.length)];

  // Select drama archetype
  const dramaArchetypes = ['close_win', 'close_loss', 'comeback', 'control_win', 'stomp_rare'];
  const drama_archetype = selectDramaArchetype(matchMode, dramaArchetypes);

  // Generate opponent plan with strict schema
  const plan = {
    persona,
    skill_band,
    reaction_base_ms: getReactionBase(skill_band),
    reaction_jitter_ms: getReactionJitter(skill_band),
    mistake_rate: getMistakeRate(skill_band),
    hesitation_rate: getHesitationRate(skill_band),
    drama_archetype,
    swing_windows: generateSwingWindows(drama_archetype),
    risk_bounds: {
      max_win_bias: 0.12,
      max_loss_bias: 0.12
    },
    governance_metadata: {
      tier: tierAssignment.tier,
      generated_at: new Date().toISOString(),
      model_version: '1.0',
      cost_estimate: calculateCost(tierAssignment.tier, {})
    }
  };

  // Final schema validation
  if (!validateOpponentPlanSchema(plan)) {
    throw new Error('Generated opponent plan failed schema validation');
  }

  return plan;
}

// Helper Functions

function calculateFractureRisk(context: GovernanceContext): number {
  // Calculate risk of system fracture
  return Math.random() * 0.3; // Low base risk
}

function calculateDetrimentalRisk(context: GovernanceContext): number {
  // Calculate risk of detrimental outcomes
  return Math.random() * 0.2; // Low base risk
}

function calculateDriftRisk(context: GovernanceContext): number {
  // Calculate risk of drift from intended behavior
  return Math.random() * 0.25; // Low base risk
}

function calculateCost(tier: string, riskScores: any): number {
  const baseCosts = {
    'TIER2': 0.05,
    'TIER1': 0.03,
    'BLOCKED': 0
  };

  const riskMultiplier = riskScores.overall || 1;
  return (baseCosts[tier as keyof typeof baseCosts] || 0) * riskMultiplier;
}

function selectDramaArchetype(mode: string, archetypes: string[]): string {
  // Adjust distribution based on mode
  if (mode === 'ranked') {
    // Reduce stomp_rare in ranked
    const filtered = archetypes.filter(a => a !== 'stomp_rare');
    return filtered[Math.floor(Math.random() * filtered.length)];
  }

  return archetypes[Math.floor(Math.random() * archetypes.length)];
}

function getReactionBase(skill_band: 'easy' | 'mid' | 'hard'): number {
  const bases = { easy: 420, mid: 320, hard: 240 };
  return bases[skill_band];
}

function getReactionJitter(skill_band: 'easy' | 'mid' | 'hard'): number {
  const jitters = { easy: 180, mid: 140, hard: 120 };
  return jitters[skill_band];
}

function getMistakeRate(skill_band: 'easy' | 'mid' | 'hard'): number {
  const rates = { easy: 0.12, mid: 0.08, hard: 0.045 };
  return rates[skill_band];
}

function getHesitationRate(skill_band: 'easy' | 'mid' | 'hard'): number {
  const rates = { easy: 0.12, mid: 0.10, hard: 0.08 };
  return rates[skill_band];
}

function generateSwingWindows(drama_archetype: string): Array<{start_pct: number, end_pct: number, intensity: number}> {
  // Generate swing windows based on drama archetype
  const windows = {
    close_win: [{ start_pct: 0.6, end_pct: 0.9, intensity: 0.4 }],
    close_loss: [{ start_pct: 0.3, end_pct: 0.7, intensity: 0.5 }],
    comeback: [{ start_pct: 0.7, end_pct: 0.95, intensity: 0.6 }],
    control_win: [{ start_pct: 0.2, end_pct: 0.5, intensity: 0.3 }],
    stomp_rare: [{ start_pct: 0.1, end_pct: 0.3, intensity: 0.2 }]
  };

  return windows[drama_archetype as keyof typeof windows] || windows.control_win;
}

function validateOpponentPlanSchema(plan: any): boolean {
  const required = [
    'persona', 'skill_band', 'reaction_base_ms', 'reaction_jitter_ms',
    'mistake_rate', 'hesitation_rate', 'drama_archetype', 'swing_windows', 'risk_bounds'
  ];

  // Check required fields
  for (const field of required) {
    if (!(field in plan)) return false;
  }

  // Validate bounds
  if (plan.risk_bounds.max_win_bias > 0.12 || plan.risk_bounds.max_loss_bias > 0.12) {
    return false;
  }

  // Validate skill band
  if (!['easy', 'mid', 'hard'].includes(plan.skill_band)) {
    return false;
  }

  // Validate persona
  if (!['Aggro', 'Turtle', 'Counter', 'Gambler'].includes(plan.persona)) {
    return false;
  }

  // Validate drama archetype
  if (!['close_win', 'close_loss', 'comeback', 'control_win', 'stomp_rare'].includes(plan.drama_archetype)) {
    return false;
  }

  return true;
}

import { runGovernedExecution } from "@/lib/governance/runGovernedExecution";
import { createClient } from '@supabase/supabase-js';

export interface OpponentPlanBundle {
  match_id: string;
  opponent_plan: OpponentPlan;
  governance_metadata: GovernanceMetadata;
  deterministic_seed: number;
}

export interface OpponentPlan {
  persona: "Aggro" | "Turtle" | "Counter" | "Gambler";
  skill_band: "easy" | "mid" | "hard";
  reaction_base_ms: number;
  reaction_jitter_ms: number;
  mistake_rate: number;
  hesitation_rate: number;
  drama_archetype: "close_win" | "close_loss" | "comeback" | "control_win" | "stomp_rare";
  swing_windows: Array<{start_pct: number, end_pct: number, intensity: number}>;
  risk_bounds: {
    max_win_bias: number;
    max_loss_bias: number;
  };
}

export interface GovernanceMetadata {
  tier: string;
  risk_scores: any;
  validation_results: any;
  cost_estimate: number;
  latency_ms: number;
  model_version: string;
  plan_id: string;
  generated_at: string;
}

export interface PlayerContext {
  id: string;
  mmr: number;
  region: string;
  skill_level: string;
  recent_matches: any[];
}

export interface MatchContext {
  mode: "ranked" | "casual";
  queue_time: number;
  expected_duration: number;
}

export class GovernedOpponentOrchestrator {
  private supabase: any;
  private circuitBreaker: CircuitBreaker;
  private telemetryEmitter: TelemetryEmitter;
  private fairnessMonitor: FairnessMonitor;

  constructor() {
    this.supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    );
    this.circuitBreaker = new CircuitBreaker();
    this.telemetryEmitter = new TelemetryEmitter();
    this.fairnessMonitor = new FairnessMonitor();
  }

  async generateOpponentPlan(
    playerContext: PlayerContext,
    matchContext: MatchContext
  ): Promise<OpponentPlanBundle> {
    const startTime = Date.now();
    const match_id = this.generateMatchId();

    try {
      // Check circuit breaker
      if (this.circuitBreaker.isOpen()) {
        throw new Error('Circuit breaker is open - using fallback mode');
      }

      // Governance entry point - NO direct model calls
      const governanceResult = await runGovernedExecution({
        execution_type: "OPPONENT_PLAN",
        playerContext,
        matchContext
      });

      if (!governanceResult.success) {
        throw new Error(`Governance failed: ${governanceResult.error}`);
      }

      // Validate strict schema
      const opponentPlan = this.validateAndSanitizePlan(governanceResult.data);

      // Generate deterministic seed for real-time execution
      const deterministic_seed = this.generateDeterministicSeed(playerContext, matchContext);

      const bundle: OpponentPlanBundle = {
        match_id,
        opponent_plan: opponentPlan,
        governance_metadata: {
          tier: governanceResult.governance_tier,
          risk_scores: governanceResult.risk_scores,
          validation_results: governanceResult.validation_results,
          cost_estimate: governanceResult.cost_estimate || 0,
          latency_ms: governanceResult.latency_ms || 0,
          model_version: governanceResult.validation_results?.model_version || '1.0',
          plan_id: this.generatePlanId(),
          generated_at: new Date().toISOString()
        },
        deterministic_seed
      };

      // Persist observability data
      await this.persistMatchObservability(bundle);

      // Check latency target
      const latency = Date.now() - startTime;
      if (latency > 300) {
        this.circuitBreaker.recordFailure();
        console.warn(`Plan generation latency exceeded 300ms: ${latency}ms`);
      }

      return bundle;

    } catch (error) {
      const latency = Date.now() - startTime;
      this.circuitBreaker.recordFailure();

      // Fallback to deterministic heuristic mode
      return this.generateFallbackPlan(playerContext, matchContext, match_id, error);
    }
  }

  private validateAndSanitizePlan(plan: any): OpponentPlan {
    // Strict schema validation - BLOCK if invalid
    const required = [
      'persona', 'skill_band', 'reaction_base_ms', 'reaction_jitter_ms',
      'mistake_rate', 'hesitation_rate', 'drama_archetype', 'swing_windows', 'risk_bounds'
    ];

    for (const field of required) {
      if (!(field in plan)) {
        throw new Error(`Missing required field: ${field}`);
      }
    }

    // Validate persona
    const validPersonas = ["Aggro", "Turtle", "Counter", "Gambler"];
    if (!validPersonas.includes(plan.persona)) {
      throw new Error(`Invalid persona: ${plan.persona}`);
    }

    // Validate skill band
    const validSkillBands = ["easy", "mid", "hard"];
    if (!validSkillBands.includes(plan.skill_band)) {
      throw new Error(`Invalid skill_band: ${plan.skill_band}`);
    }

    // Validate drama archetype
    const validArchetypes = ["close_win", "close_loss", "comeback", "control_win", "stomp_rare"];
    if (!validArchetypes.includes(plan.drama_archetype)) {
      throw new Error(`Invalid drama_archetype: ${plan.drama_archetype}`);
    }

    // HARD FAIRNESS BOUNDS - BLOCK if violated
    if (plan.risk_bounds.max_win_bias > 0.12 || plan.risk_bounds.max_loss_bias > 0.12) {
      throw new Error('Risk bounds exceed 0.12 threshold - BLOCKED');
    }

    // Validate humanization constraints
    this.validateHumanizationConstraints(plan);

    return plan as OpponentPlan;
  }

  private validateHumanizationConstraints(plan: OpponentPlan) {
    const constraints = {
      easy: { reaction_base: 420, reaction_jitter: 180, mistake_min: 0.10, mistake_max: 0.14, hesitation: 0.12 },
      mid: { reaction_base: 320, reaction_jitter: 140, mistake_min: 0.06, mistake_max: 0.10, hesitation: 0.10 },
      hard: { reaction_base: 240, reaction_jitter: 120, mistake_min: 0.03, mistake_max: 0.06, hesitation: 0.08 }
    };

    const constraint = constraints[plan.skill_band];

    if (Math.abs(plan.reaction_base_ms - constraint.reaction_base) > 50) {
      throw new Error(`Reaction base out of bounds for ${plan.skill_band}`);
    }

    if (plan.reaction_jitter_ms > constraint.reaction_jitter * 1.5) {
      throw new Error(`Reaction jitter out of bounds for ${plan.skill_band}`);
    }

    if (plan.mistake_rate < constraint.mistake_min || plan.mistake_rate > constraint.mistake_max) {
      throw new Error(`Mistake rate out of bounds for ${plan.skill_band}`);
    }

    if (plan.hesitation_rate > constraint.hesitation * 1.5) {
      throw new Error(`Hesitation rate out of bounds for ${plan.skill_band}`);
    }
  }

  private generateFallbackPlan(
    playerContext: PlayerContext,
    matchContext: MatchContext,
    match_id: string,
    error: any
  ): OpponentPlanBundle {
    console.warn('Using fallback deterministic plan due to error:', error.message);

    const skill_band = playerContext.mmr < 1200 ? 'easy' : playerContext.mmr < 1800 ? 'mid' : 'hard';
    const personas = ["Aggro", "Turtle", "Counter", "Gambler"];
    const persona = personas[Math.floor(Math.abs(this.hashString(playerContext.id)) % personas.length)] as any;

    const fallbackPlan: OpponentPlan = {
      persona,
      skill_band,
      reaction_base_ms: skill_band === 'easy' ? 420 : skill_band === 'mid' ? 320 : 240,
      reaction_jitter_ms: skill_band === 'easy' ? 180 : skill_band === 'mid' ? 140 : 120,
      mistake_rate: skill_band === 'easy' ? 0.12 : skill_band === 'mid' ? 0.08 : 0.045,
      hesitation_rate: skill_band === 'easy' ? 0.12 : skill_band === 'mid' ? 0.10 : 0.08,
      drama_archetype: 'control_win',
      swing_windows: [{ start_pct: 0.2, end_pct: 0.5, intensity: 0.3 }],
      risk_bounds: { max_win_bias: 0.12, max_loss_bias: 0.12 }
    };

    return {
      match_id,
      opponent_plan: fallbackPlan,
      governance_metadata: {
        tier: 'FALLBACK',
        risk_scores: { overall: 0, level: 'LOW' },
        validation_results: { fallback_reason: error.message },
        cost_estimate: 0,
        latency_ms: 0,
        model_version: 'fallback',
        plan_id: this.generatePlanId(),
        generated_at: new Date().toISOString()
      },
      deterministic_seed: this.generateDeterministicSeed(playerContext, matchContext)
    };
  }

  private generateDeterministicSeed(playerContext: PlayerContext, matchContext: MatchContext): number {
    const seedString = `${playerContext.id}-${matchContext.mode}-${Date.now()}`;
    return this.hashString(seedString);
  }

  private hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash);
  }

  private generateMatchId(): string {
    return `match_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private generatePlanId(): string {
    return `plan_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private async persistMatchObservability(bundle: OpponentPlanBundle) {
    try {
      await this.supabase.from('match_opponent_plans').insert({
        match_id: bundle.match_id,
        plan_id: bundle.governance_metadata.plan_id,
        governance_tier: bundle.governance_metadata.tier,
        risk_scores: bundle.governance_metadata.risk_scores,
        persona: bundle.opponent_plan.persona,
        drama_archetype: bundle.opponent_plan.drama_archetype,
        difficulty_band: bundle.opponent_plan.skill_band,
        cost_per_plan: bundle.governance_metadata.cost_estimate,
        latency_ms: bundle.governance_metadata.latency_ms,
        model_version: bundle.governance_metadata.model_version,
        threshold_version: '1.0',
        validation_results: bundle.governance_metadata.validation_results,
        created_at: new Date().toISOString()
      });
    } catch (error) {
      console.error('Failed to persist observability data:', error);
    }
  }

  // Real-time execution methods (NO LLM calls)
  calculateReactionDelay(plan: OpponentPlan, gameState: any, rng: any): number {
    const base = plan.reaction_base_ms;
    const jitter = (rng.next() - 0.5) * 2 * plan.reaction_jitter_ms;

    // Apply hesitation events
    let hesitation = 0;
    if (rng.next() < plan.hesitation_rate) {
      hesitation = 250 + rng.next() * 650; // 250-900ms hesitation
    }

    // Apply drama modifiers
    const dramaModifier = this.calculateDramaModifier(plan, gameState, rng);

    return Math.max(50, base + jitter + hesitation + dramaModifier);
  }

  shouldMakeMistake(plan: OpponentPlan, gameState: any, rng: any): boolean {
    let mistakeRate = plan.mistake_rate;

    // Increase mistakes under pressure
    if (gameState.isCloseMatch && gameState.isLateGame) {
      mistakeRate *= 1.5;
    }

    // Apply drama swing windows
    for (const window of plan.swing_windows) {
      const matchProgress = gameState.elapsed / gameState.expectedDuration;
      if (matchProgress >= window.start_pct && matchProgress <= window.end_pct) {
        mistakeRate *= (1 + window.intensity);
      }
    }

    return rng.next() < mistakeRate;
  }

  private calculateDramaModifier(plan: OpponentPlan, gameState: any, rng: any): number {
    // Drama modifies probabilities, not results
    let modifier = 0;

    switch (plan.drama_archetype) {
      case 'close_win':
        if (gameState.playerScore < gameState.opponentScore) {
          modifier = -50; // Help player catch up
        }
        break;
      case 'close_loss':
        if (gameState.playerScore > gameState.opponentScore) {
          modifier = 50; // Help opponent catch up
        }
        break;
      case 'comeback':
        if (gameState.isLateGame && gameState.playerScore < gameState.opponentScore) {
          modifier = -100; // Big comeback opportunity
        }
        break;
      case 'control_win':
        // No significant modifiers
        break;
      case 'stomp_rare':
        if (rng.next() < 0.2) { // 20% chance
          modifier = gameState.playerScore > gameState.opponentScore ? 100 : -100;
        }
        break;
    }

    // Apply risk bounds
    modifier = Math.max(-plan.risk_bounds.max_loss_bias * 1000, 
                       Math.min(plan.risk_bounds.max_win_bias * 1000, modifier));

    return modifier;
  }

  // Admin dashboard methods
  async getGovernanceStats() {
    try {
      const { data } = await this.supabase
        .from('match_opponent_plans')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(1000);

      return {
        total_plans: data?.length || 0,
        tier_distribution: this.calculateTierDistribution(data),
        persona_distribution: this.calculatePersonaDistribution(data),
        drama_distribution: this.calculateDramaDistribution(data),
        average_latency: this.calculateAverageLatency(data),
        average_cost: this.calculateAverageCost(data),
        circuit_breaker_status: this.circuitBreaker.getStatus()
      };
    } catch (error) {
      console.error('Failed to get governance stats:', error);
      return null;
    }
  }

  private calculateTierDistribution(data: any[]) {
    const distribution = { TIER1: 0, TIER2: 0, FALLBACK: 0, BLOCKED: 0 };
    data.forEach(item => {
      const tier = item.governance_tier;
      if (tier in distribution) distribution[tier as keyof typeof distribution]++;
    });
    return distribution;
  }

  private calculatePersonaDistribution(data: any[]) {
    const distribution = { Aggro: 0, Turtle: 0, Counter: 0, Gambler: 0 };
    data.forEach(item => {
      const persona = item.persona;
      if (persona in distribution) distribution[persona as keyof typeof distribution]++;
    });
    return distribution;
  }

  private calculateDramaDistribution(data: any[]) {
    const distribution = { close_win: 0, close_loss: 0, comeback: 0, control_win: 0, stomp_rare: 0 };
    data.forEach(item => {
      const drama = item.drama_archetype;
      if (drama in distribution) distribution[drama as keyof typeof distribution]++;
    });
    return distribution;
  }

  private calculateAverageLatency(data: any[]) {
    if (!data.length) return 0;
    const total = data.reduce((sum, item) => sum + (item.latency_ms || 0), 0);
    return Math.round(total / data.length);
  }

  private calculateAverageCost(data: any[]) {
    if (!data.length) return 0;
    const total = data.reduce((sum, item) => sum + (item.cost_per_plan || 0), 0);
    return total / data.length;
  }
}

// Supporting Classes

class CircuitBreaker {
  private failures = 0;
  private lastFailureTime = 0;
  private state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  private readonly threshold = 5;
  private readonly timeout = 60000; // 1 minute

  recordFailure() {
    this.failures++;
    this.lastFailureTime = Date.now();

    if (this.failures >= this.threshold) {
      this.state = 'OPEN';
      console.warn('Circuit breaker opened due to repeated failures');
    }
  }

  recordSuccess() {
    this.failures = 0;
    this.state = 'CLOSED';
  }

  isOpen(): boolean {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.timeout) {
        this.state = 'HALF_OPEN';
        return false;
      }
      return true;
    }
    return false;
  }

  getStatus() {
    return {
      state: this.state,
      failures: this.failures,
      lastFailureTime: this.lastFailureTime
    };
  }
}

